class Marionette:
    def __init__(self, port, capabilities=None):
        self.sock = socket.create_connection(("127.0.0.1", port))
        # nie endlos warten: ein Befehl darf höchstens 11 Minuten dauern (--perf)
        self.sock.settimeout(660)
        self.id = 0
        self._read()
        self.cmd("WebDriver:NewSession", {"capabilities": capabilities or {}})
        self.cmd("Marionette:SetContext", {"value": "chrome"})

    def _recv(self, n):
        chunk = self.sock.recv(n)
        if not chunk:  # Thunderbird hat die Verbindung geschlossen (beendet/abgestürzt)
            raise ConnectionError("Marionette-Verbindung geschlossen")
        return chunk

    def _read(self):
        buf = b""
        while b":" not in buf:
            buf += self._recv(1)
        n, rest = buf.split(b":", 1)
        n = int(n)
        while len(rest) < n:
            rest += self._recv(n - len(rest))
        return json.loads(rest)

    def cmd(self, name, params=None):
        self.id += 1
        data = json.dumps([0, self.id, name, params or {}]).encode()
        self.sock.sendall(str(len(data)).encode() + b":" + data)
        reply = self._read()
        if reply[2]:
            raise RuntimeError(reply[2].get("message", reply[2]))
        return reply[3]

    def js(self, body):
        # --only: Vorbereitungen außerhalb einer Prüfung kennzeichnen – ihre Meldungen in der Fehlerkonsole gehören zu
        # übersprungenen Prüfungen und zählen nicht (konsole_bewerten); späte Meldungen der gelaufenen bleiben „nach …“
        mark = konsole_setze_js("Vorbereitung (--only)") if ONLY and not IN_CHECK else ""
        script = "return (async () => {" + PRELUDE + mark + body + "})();"
        if FV0 != "99.0.0":  # Paket ab 99.0.0: erfundene Versionen darüber
            script = script.replace("99.0.0", FV0).replace("99.0.1", FV1)
        try:
            return self.cmd("WebDriver:ExecuteScript", {"script": script, "args": []}).get("value")
        except RuntimeError as e:
            # mit --only fehlen Vorarbeiten übersprungener Prüfungen – Vorbereitungen außerhalb einer Prüfung dürfen dann scheitern
            if ONLY and not IN_CHECK:
                print(f"Hinweis (--only): Vorbereitung übersprungen – {e}", flush=True)
                return {}
            raise

    def pointer(self, steps):
        self.cmd("WebDriver:PerformActions", {"actions": [
            {"type": "pointer", "id": "maus", "parameters": {"pointerType": "mouse"}, "actions": steps}]})
        self.cmd("WebDriver:ReleaseActions", {})


# gemeinsame Hilfen für alle Prüfungen (im Chrome-Kontext von Thunderbird)
# erfundene „neuere“ Versionen für Update-Hinweis-Prüfungen: 99.0.0/99.0.1, solange das Paket kleiner ist
# (sonst, z. B. bei einer Probeversion 99.0.0, gäbe es keine neuere und die hartkodierten Werte wären nicht „neuer“)
FV0, FV1 = "99.0.0", "99.0.1"


def faktisch_setzen(version):
    global FV0, FV1
    try:
        if tuple(int(x) for x in version.split(".")) >= (99, 0, 0):
            FV0, FV1 = "9999.0.0", "9999.0.1"
    except ValueError:
        pass


PRELUDE = r"""
const w = Services.wm.getMostRecentWindow("mail:3pane"); const d = w.document;
// (ungezählter Zeitgeber, siehe ruhig())
const wait = ms => new Promise(r => (w.__haloSetTimeout || w.setTimeout).call(w, r, ms));
// Abfrage-Takt der Warte-Hilfen: Zeitgeber des Moduls, läuft auch, solange ein modaler Dialog das Hauptfenster anhält
const takt = (ms => { const { setTimeout: t } = ChromeUtils.importESModule("resource://gre/modules/Timer.sys.mjs"); return ms => new Promise(r => t(r, ms)); })();
// Warten auf Bedingungen statt fester Zeiten (AGENTS.md, „Bauen und testen“):
// until() wartet, bis fn() etwas liefert, und gibt sonst den letzten Wert zurück
const until = async (fn, ms = 6000) => { const end = Date.now() + ms; while (Date.now() < end) { const v = fn(); if (v) return v; await takt(25); } return fn(); };
// bis() wie until(), bricht aber bei Zeitüberschreitung mit einer verständlichen Meldung ab (kein stilles Weiterlaufen)
const bis = async (fn, was, ms = 5000) => { const v = await until(fn, ms); if (v) return v; throw new Error(`Zeitüberschreitung nach ${ms} ms: ${was}`); };
// stabil() wartet, bis fn() (z. B. Lage und Größe eines Elements) bei drei Abfragen im Abstand von 40 ms gleich bleibt
const stabil = async (fn, ms = 3000) => { const end = Date.now() + ms; let last, same = 0;
  while (Date.now() < end) { const v = JSON.stringify(fn()); same = v === last ? same + 1 : 0; last = v; if (same >= 2) return true; await takt(40); } return false; };
const tm = d.getElementById("tabmail");
// imTakt() misst eine Animation Bild für Bild im festen Takt von 60 Hz statt in Echtzeit: der Test selbst löst jedes
// Bild aus (windowUtils.advanceTimeAndRefresh, die Uhr der Animationen läuft je Bild genau 16,7 ms weiter) und ruft
// danach jeBild(i). So sieht jede Messung dieselben Bilder, gleich wie schnell der Rechner ist – unter xvfb in der CI
// braucht ein Bild je nach Läufer 35–95 ms (in Echtzeit blieben von 250 ms Animation 3–7 Bilder, Auswertung
// ~/halo-berichte/2026-11-18-flackern.md), einzelne Lastspitzen ließen Bilder ausfallen. Zwischen den Bildern laufen
// Zeitgeber und Zusagen weiter, und die Bilder kommen nicht früher als in Echtzeit (ein langsamer Rechner dehnt die
// Aufnahme nur). Vor dem Auslöser der Animation aufrufen lassen: imTakt(600, …) direkt nach dem Klick. Liefert je Bild
// die Zeit, die sein Aufbau gebraucht hat (ms) – das Maß für „flüssig“, unabhängig von Bildwiederholrate und Last
// zwischen den Bildern. Währenddessen kein ruhig()/requestAnimationFrame abwarten (Bilder kommen nur von hier).
const BILD_MS = 1000 / 60;
const imTakt = async (dauer, jeBild, win = w) => { const wu = win.windowUtils, kosten = [];
  wu.advanceTimeAndRefresh(0);
  try { const t0 = performance.now();
    for (let i = 1; i * BILD_MS <= dauer; i++) {
      await wait(Math.max(0, t0 + i * BILD_MS - performance.now()));
      const t = performance.now(); wu.advanceTimeAndRefresh(BILD_MS); kosten.push(Math.round((performance.now() - t) * 10) / 10); jeBild?.(i); }
  } finally { wu.restoreNormalRefresh(); }
  return kosten; };
// mittlere Aufbauzeit (Median) der Bilder, in denen sich etwas bewegt hat (bewegt[i] gehört zu kosten[i])
const bildKosten = (kosten, bewegt) => { const k = kosten.filter((_, i) => bewegt[i]).sort((a, b) => a - b); return k.length ? k[k.length >> 1] : 0; };
// ruhig() wartet nach einer Bedienung auf Leerlauf: keine laufenden Übergänge/Animationen, kein Dokument lädt, kurze
// Zeitgeber der Fenster abgelaufen (die Erweiterung reagiert oft verzögert), seit 80 ms keine Änderung am DOM.
// Höchstens ms – das ist die frühere feste Pause, länger als vorher wird nie gewartet. Beobachtet alle offenen Fenster
// (auch Dialoge), ihre eingebetteten Seiten (Mail, Adressbuch, Einstellungen) und Rahmen.
// Nicht für Abläufe ohne sichtbares Zeichen (Datenbank, Server, Suche): dort bis() mit dem passenden Fertig-Zeichen,
// und nicht, wo Zeit vergehen soll (Doppelklick-Abstand, „bleibt offen“, Animationsbilder): dort wait().
const ruhig = async (ms = 1000) => {
  const end = Date.now() + ms, wins = new Set();
  const add = x => { try { if (!x || x.closed || !x.document || wins.has(x)) return; wins.add(x);
    for (const b of x.document.querySelectorAll("browser, iframe")) { try { add(b.contentWindow); } catch {} } } catch {} };
  for (const x of Services.wm.getEnumerator(null)) add(x);
  // kurze Zeitgeber je Fenster mitzählen (einmal je Fenster eingehängt, für das ganze Testprofil)
  for (const x of wins) if (!x.__haloTimer) { const open = new Map(), st = x.setTimeout, ct = x.clearTimeout;
    x.setTimeout = function (fn, t = 0, ...a) { let id; id = st.call(x, (...y) => { open.delete(id); if (typeof fn == "function") return fn(...y); }, t, ...a);
      // (fällig um, Name der Funktion – für die Auswertung, wenn bis zur Höchstzeit gewartet wurde)
      if (t <= 1600) open.set(id, [Date.now() + t, typeof fn == "function" ? fn.name || String(fn).replace(/\s+/g, " ").slice(0, 40) : "?"]); return id; };
    x.clearTimeout = function (id) { open.delete(id); return ct.call(x, id); };
    // ebenso angemeldete Bildwechsel (requestAnimationFrame): Zeilen und Karten werden oft erst dort gefüllt
    const frames = new Set(), raf = x.requestAnimationFrame, caf = x.cancelAnimationFrame;
    x.requestAnimationFrame = function (fn) { let id; id = raf.call(x, t => { frames.delete(id); return fn(t); }); frames.add(id); return id; };
    x.cancelAnimationFrame = function (id) { frames.delete(id); return caf.call(x, id); };
    x.__haloFrames = frames; x.__haloTimer = open; x.__haloSetTimeout = st; }
  let last = Date.now(), wer = ""; const obs = [];
  // (Attribute, die nur mit demselben Wert neu gesetzt werden, zählen nicht – auch nicht, wenn sie im selben Durchgang
  // entfernt und wieder gesetzt werden: maßgeblich ist der Wert vor dem ersten Eintrag; die Toolbar-Anpassung nimmt
  // mc-squeezed bei jedem Messen erst weg und setzt es danach gleich wieder, das zählte als Änderung)
  const vorher = rs => { const v = new Map(); for (const r of rs) if (r.type == "attributes") { let a = v.get(r.target);
    if (!a) v.set(r.target, a = new Map()); if (!a.has(r.attributeName)) a.set(r.attributeName, r.oldValue); } return v; };
  const echt = (r, v) => { try { return r.type != "attributes" || v.get(r.target).get(r.attributeName) !== r.target.getAttribute(r.attributeName); } catch { return true; } };
  // welches Element sich zuletzt änderte (für die Auswertung, wenn bis zur Höchstzeit gewartet wurde)
  const name = r => { const e = r.target.nodeType == 1 ? r.target : r.target.parentElement;
    return `${e?.localName || "?"}${e?.id ? "#" + e.id : e?.classList?.length ? "." + e.classList[0] : ""} ${r.type == "attributes" ? "[" + r.attributeName + "]" : r.type == "childList" ? "Kinder" : "Text"}`; };
  for (const x of wins) { try { const o = new x.MutationObserver(rs => { const v = vorher(rs), r = rs.findLast(q => echt(q, v)); if (r) { last = Date.now(); wer = name(r); } });
    o.observe(x.document, { subtree: true, childList: true, attributes: true, attributeOldValue: true, characterData: true }); obs.push(o); } catch {} }
  // (ein Fenster, das inzwischen geschlossen wurde, wird nicht mehr beobachtet)
  const busy = () => [...wins].some(x => { try { return busyWin(x); } catch { wins.delete(x); return false; } });
  let grund = "";  // was zuletzt aufgehalten hat (für die Auswertung am Ende des Laufs)
  const busyWin = x => { const doc = x.document, u = String(x.location?.href).split(/[?#]/)[0].split("/").pop();
    if (doc.readyState != "complete") return (grund = "lädt " + u);
    // (Zeitgeber, die erst nach der Höchstzeit fällig werden, hätte auch die feste Pause nicht abgewartet)
    const tm0 = [...(x.__haloTimer?.values() ?? [])].find(([t]) => t > Date.now() - 50 && t <= end);
    if (tm0) return (grund = "Zeitgeber " + u + " (" + tm0[1] + ")");
    if (x.__haloFrames?.size) return (grund = "Bildwechsel " + u);
    if ([...doc.querySelectorAll("browser")].some(b => { try { return b.webProgress?.isLoadingDocument; } catch { return false; } })) return (grund = "Browser lädt " + u);
    const a = doc.getAnimations().find(a => a.playState == "running" && Number.isFinite(a.effect?.getComputedTiming().endTime));
    return a ? (grund = "Animation " + (a.animationName || a.transitionProperty) + " " + u) : false; };
  try {
    await takt(30);
    while (Date.now() < end) { if (!busy()) { if (Date.now() - last >= 80) return true; grund = wer ? "DOM ändert sich: " + wer : `ruhig(${ms}) kürzer als 80 ms Ruhe`; } await takt(25); }
    // Höchstzeit erreicht: Auswertung am Ende des Laufs, je Grund und Prüfung
    if (!grund) grund = `kein Durchgang (ruhig(${ms}) kürzer als ein Takt)`;
    const v = (w.__haloRuhigVoll ||= {}), k = grund + " ⟵ " + (w.__haloCheck || "?"); v[k] = (v[k] || 0) + 1;
    return false;
  } finally { obs.forEach(o => { try { o.disconnect(); } catch {} }); }
};
const { cal } = ChromeUtils.importESModule("resource:///modules/calendar/calUtils.sys.mjs");
const toMail = async () => { tm.switchToTab(0);
  const a3 = await bis(() => tm.currentTabInfo == tm.tabInfo[0] && tm.currentAbout3Pane?.document.readyState == "complete" && tm.currentAbout3Pane, "Mail-Tab");
  await ruhig(900); return a3; };
// Kalender: Tab gewählt, Ansicht sichtbar und ihre Termine geladen (view.ready)
const toCalendar = async () => { tm.openTab("calendar", {});
  const view = await bis(() => tm.currentTabInfo?.mode?.name == "calendar" && (v => v?.getBoundingClientRect().width > 0 && v)(w.currentView?.()), "Kalender-Tab");
  await Promise.race([view.ready, wait(4000)]); await ruhig(1500); };
const testCalendar = () => cal.manager.getCalendars().find(c => c.name == "Halo Test");
// liegengebliebene Aufgaben früherer Prüfungen im Testkalender entfernen (Vorbedingung leere Aufgabenliste); Titel zurück
const leftoverTodos = async () => { const c = testCalendar(); const l = (await c.getItemsAsArray(Ci.calICalendar.ITEM_FILTER_ALL_ITEMS, 0, null, null)).filter(i => i.isTodo?.());
  for (const it of l) { try { await c.deleteItem(it); } catch {} } return l.map(i => i.title); };
const items = async title => { const c = testCalendar(); return (await c.getItemsAsArray(Ci.calICalendar.ITEM_FILTER_ALL_ITEMS, 0, null, null)).filter(i => i.title == title); };
const rect = el => { const r = el.getBoundingClientRect(); return { l: Math.round(r.left), r: Math.round(r.right), w: Math.round(r.width) }; };
// Prüfungen, die absichtlich einen Fehler in halo.spaces auslösen (kein Netz, kaputte Daten, ersetzte Funktionen), melden
// ihn hier an: Meldungen, die auf das Muster passen, zählen in der Prüfung der Fehlerkonsole nur für diese Prüfung nicht
const erwartet = re => { const k = [...Services.wm.getEnumerator("mail:3pane")].find(x => x.__haloKonsole)?.__haloKonsole; if (k) k.erwartet.push({ check: k.check, re: re.source, fl: re.flags }); };
"""


ONLY = None  # --only: nur Prüfungen, deren Name auf diesen regulären Ausdruck passt
IN_CHECK = False
LAST_END = None  # Ende der vorigen Prüfung: die Dauer einer Prüfung zählt ihre Vorbereitung mit
CHECK_M = None  # Marionette des laufenden Tests (setzt main)
DURATIONS = []


FRAMES_WARN = os.environ.get("HALO_FRAMES_WARN") == "1"
FRAME_CHECK = re.compile(r"flüssig|verlorene Bilder|Bildzeit|ohne Ruck|ruckelfrei", re.I)


def mark_check(name):
    """Name der laufenden Prüfung für ruhig() und die Mitschrift der Fehlerkonsole (wer eine Meldung auslöste)."""
    if CHECK_M:
        try:
            CHECK_M.cmd("WebDriver:ExecuteScript", {"script": PRELUDE.split("const wait")[0] + f"w.__haloCheck = {json.dumps(name[:70])}; "
                        + konsole_setze_js(name) + " return 1;", "args": []})
        except Exception:
            pass


# bekannt=True: offener Bug als Prüfung festgehalten (Konvention aus dem Comment Ranker, „Known gaps“). Sie heißt
# „BEKANNTER FEHLER: …“, ist grün, solange der Fehler besteht (fn meldet Fehlschlag), und rot, sobald er – auch
# nebenbei – behoben ist; dann in eine normale Prüfung umwandeln (bekannt=True weg). So fallen mitbehobene Bugs auf
def check(name, fn, results, immer=False, bekannt=False):
    global IN_CHECK, LAST_END
    if bekannt:
        name = f"BEKANNTER FEHLER: {name}"
    if ONLY and not ONLY.search(name) and not immer:
        return
    start = LAST_END or time.time()
    mark_check(name)
    IN_CHECK = True
    try:
        ok, detail = fn()
    except Exception as e:  # Fehler in der Prüfung selbst zählen als Fehlschlag
        ok, detail = False, f"Ausnahme: {e}"
    finally:
        IN_CHECK = False
    # Meldungen bis zur nächsten Prüfung stammen aus deren Vorbereitung (bei --only teils übersprungen)
    mark_check("nach " + name)
    LAST_END = time.time()
    DURATIONS.append((LAST_END - start, name))
    # Rechner ohne Grafikkarte (HALO_FRAMES_WARN=1, Windows-Job auf GitHub): Prüfungen, die am Bildtakt hängen
    # (flüssig, verlorene Bilder, Bildzeiten), nur als Warnung – Bewegungsabläufe (Sprung, Endplatz) bleiben Fehler
    if not ok and FRAMES_WARN and FRAME_CHECK.search(name):
        print(f"WARNUNG {name} – am Bildtakt, auf diesem Rechner nur Warnung – {detail}", flush=True)
        ok, detail = True, f"WARNUNG (Bildtakt): {detail}"
    if bekannt:
        ok, detail = (not ok), (f"besteht noch – {detail}" if not ok else f"behoben? läuft jetzt durch – in eine normale Prüfung umwandeln – {detail}")
    results.append((name, ok, detail))
    print(f"{'OK     ' if ok else 'FEHLER '} {name}" + (f" – {detail}" if detail else ""), flush=True)


# ---------------------------------------------------------------------------
# Fehlerkonsole und Fehlerprotokoll (AGENTS.md, „Fehlerkonsole“): Mitschrift ab dem Start des Laufs, Auswertung am
# Ende – nie ein Fehlschlag, je Fehler eine Zeile „KONSOLE  …“ bzw. „PROTOKOLL  …“ für den CI-Wächter
# ---------------------------------------------------------------------------

KONSOLE_PUFFER = 250  # so viele Meldungen hält die Fehlerkonsole (nsConsoleService), ältere fallen heraus
KONSOLE_DUNKEL = False  # Lauf im Dunkelmodus (steht in den Zeilen, damit „behoben“ im richtigen Modus geprüft wird)
KONSOLE_STAND = None  # so viele Einträge der Mitschrift hat die Prüfung schon gemeldet (None: noch nicht gelaufen)
PROTOKOLL_STAND = None  # ebenso für das Fehlerprotokoll (Prüfung „Fehlerprotokoll der Erweiterung …“)

# Mitschrift im Hauptfenster suchen (auch wenn ein zweites Mail-Fenster das zuletzt benutzte ist)
KONSOLE_FIND = '[...Services.wm.getEnumerator("mail:3pane")].find(x => x.__haloKonsole)?.__haloKonsole'

# Meldung einordnen: nur Fehler aus halo.spaces (Quelle oder Aufrufstapel im Paket) und Thunderbird-Meldungen, die auf
# einen Eingriff von uns deuten, werden mitgeschrieben; Thunderbirds übrige Fehler und alle Warnungen nur gezählt.
# norm() nimmt Teile heraus, die sich je Lauf ändern (Profil, Temp-Pfade, Kennung der Erweiterung) – sonst ergäbe
# dieselbe Meldung in jedem Lauf einen neuen Board-Eintrag
KONSOLE_JS = r"""
  const host = (() => { try { return WebExtensionPolicy.getByID("mail-cards@sebastian.local")?.mozExtensionHostname || ""; } catch { return ""; } })();
  const esc = x => x.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  // (…/api/*.js – implementation.js und ihre Teile – auch ohne bekannte Kennung: nach dem Deinstallieren liefert getByID nichts mehr)
  const OURS = new RegExp("resource://mailcards/|mail-cards@sebastian\\.local|moz-extension://[^/]+/api/[\\w-]+\\.js" + (host ? "|moz-extension://" + esc(host) : ""));
  // Thunderbird meldet das, wenn ein Add-on die Kalender vor dem ersten Fenster lädt (GitHub #38)
  const HINTS = [/initialised calendars before loadCalendarComponent/];
  const prof = PathUtils.profileDir, profUrl = (() => { try { return PathUtils.toFileURI(prof); } catch { return prof; } })();
  const norm = t => String(t || "").split(profUrl).join("<Profil>").split(prof).join("<Profil>")
    .replace(/moz-extension:\/\/[0-9a-f-]{8,}/gi, "moz-extension://…")
    .replace(/(?:\/private)?\/var\/folders\/[^\s'"),]+|\/tmp\/[^\s'"),]+|[A-Za-z]:\\[^\s'"),]*\\Temp\\[^\s'"),]+/g, "<tmp>")
    .replace(/\s+/g, " ").trim();
  const neu = () => ({ eintraege: [], fremd: 0, warnungen: 0, start: 0, voll: false, erwartet: [], check: "Start",
    zeitplan: [[Date.now(), "Start"]], host, startfremd: [], sammleFremd: false });
  const add = (k, msg) => {
    if (!(msg instanceof Ci.nsIScriptError)) return;
    if (msg.flags & Ci.nsIScriptError.warningFlag || msg.flags & Ci.nsIScriptError.infoFlag) { k.warnungen++; return; }
    const raw = String(msg.errorMessage || "");
    let stack = ""; try { stack = String(msg.stack?.toString?.() || ""); } catch {}
    if (!(OURS.test(msg.sourceName || "") || OURS.test(stack) || HINTS.some(h => h.test(raw)))) {
      k.fremd++;
      // Startphase: Thunderbirds übrige Fehler für den Vergleich mit dem Lauf ohne halo.spaces (je Schlüssel einmal)
      if (k.sammleFremd && k.startfremd.length < 300) {
        const schluessel = konsoleSchluessel(norm(raw), msg.sourceName);
        if (!k.startfremd.some(e => e.schluessel === schluessel))
          k.startfremd.push({ schluessel, text: norm(raw).slice(0, 200), wo: `${(msg.sourceName || "?").replace(/^.*\//, "")}:${msg.lineNumber}` });
      }
      return;
    }
    if (k.eintraege.length < 2000) k.eintraege.push({ text: norm(raw).slice(0, 200), wo: `${(msg.sourceName || "?").replace(/^.*\//, "")}:${msg.lineNumber}`, check: k.check });
  };
  const setze = (k, name) => { k.check = name; k.zeitplan.push([Date.now(), name]); };
""" + open(os.path.join(ROOT, "tests", "logik", "konsole-schluessel.js"), encoding="utf-8").read()


def konsole_start(m):
    """Mitschrift starten: was seit dem Start in der Konsole steht, dann jede neue Meldung (der Puffer der Konsole
    läuft in einem langen Lauf über – ohne Mitschrift fielen gerade die Startfehler heraus)."""
    try:
        m.js(KONSOLE_JS + f"""
          if ({KONSOLE_FIND}) return 1;
          const k = w.__haloKonsole = neu();
          const snap = Services.console.getMessageArray() || [];
          k.voll = snap.length >= {KONSOLE_PUFFER}; k.start = snap.length;
          k.sammleFremd = true;  // Startphase: bis hierher (wie im Vergleichslauf ohne halo.spaces, vergleich_aufnehmen)
          for (const msg of snap) add(k, msg);
          k.sammleFremd = false;
          setze(k, "Start (nach dem Verbinden)");
          k.listener = {{ observe: msg => {{ try {{ add(k, msg); }} catch {{}} }} }};
          Services.console.registerListener(k.listener);
          return 1;""")
    except Exception as e:  # ohne Mitschrift wertet die Prüfung am Ende den Puffer aus (und sagt das)
        print(f"Hinweis: Mitschrift der Fehlerkonsole nicht gestartet – {e}", flush=True)


def konsole_setze_js(name):
    """JS, das den Namen der laufenden Prüfung (bzw. „nach …“, „Vorbereitung …“) in der Mitschrift setzt."""
    return f"{{ const __k = {KONSOLE_FIND}; if (__k) {{ __k.check = {json.dumps(name)}; __k.zeitplan.push([Date.now(), __k.check]); }} }}"


def konsole_lesen(m):
    """Mitschrift lesen; fehlt sie (nicht gestartet, Fenster ersetzt), den Puffer der Konsole."""
    return m.js(KONSOLE_JS + f"""
      let k = {KONSOLE_FIND}, quelle = "Mitschrift";
      if (!k) {{ k = neu(); quelle = "Puffer"; const snap = Services.console.getMessageArray() || [];
        k.voll = snap.length >= {KONSOLE_PUFFER}; for (const msg of snap) add(k, msg); }}
      return {{ eintraege: k.eintraege, fremd: k.fremd, warnungen: k.warnungen, voll: k.voll, erwartet: k.erwartet, quelle,
               startfremd: quelle === "Mitschrift" ? k.startfremd : null }};""") or {}


def protokoll_lesen(m):
    """Fehler aus mail-cards-debug.log (die unser Code selbst abfängt), je Zeile der Prüfung zugeordnet, die zu ihrem
    Zeitstempel lief (Zeitplan der Mitschrift); dieselbe Form wie die Einträge der Konsole."""
    return m.js(KONSOLE_JS + f"""
      const k = {KONSOLE_FIND}, plan = k?.zeitplan || [];
      const p = PathUtils.join(PathUtils.profileDir, "mail-cards-debug.log");
      let lines = []; try {{ lines = (await IOUtils.readUTF8(p)).split("\\n"); }} catch {{}}
      // nur Zeilen dieser Thunderbird-Sitzung (der Update-Test startet dasselbe Profil mehrmals, zuerst mit der alten Version)
      let t0 = 0; try {{ t0 = Services.startup.getStartupInfo().process.getTime() - 1000; }} catch {{}}
      const out = [];
      for (const l of lines) {{
        if (!/error|fehler/i.test(l) || /preview stats/.test(l)) continue;
        const ts = Date.parse(l.split(" ")[0]);
        if (t0 && ts < t0) continue;
        let check = "Start"; for (const [t, n] of plan) {{ if (t <= ts) check = n; else break; }}
        out.push({{ text: norm(l.replace(/^\\S+Z /, "")).slice(0, 300), wo: "", check }});
      }}
      return {{ eintraege: out.slice(0, 2000), erwartet: k?.erwartet || [] }};""") or {}


def konsole_bewerten(res, only=None):
    """Einträge auswerten: (Fehler, Hinweise) – je Fehler eine Zeile „Text (Datei:Zeile) – während Prüfung(en)“."""
    expected = []
    for e in res.get("erwartet") or []:
        try:
            r = re.compile(e["re"], re.I if "i" in e.get("fl", "") else 0)
        except re.error:  # JS-Muster, das Python nicht versteht: als wörtlicher Text (nie eine Ausnahme)
            r = re.compile(re.escape(e["re"]))
        expected.append((e.get("check") or "?", r))
    groups = {}
    for e in res.get("eintraege") or []:
        chk = e.get("check") or "?"
        # angemeldet gilt auch für späte Meldungen derselben Prüfung („nach …“)
        if any(chk in (c, "nach " + c) and r.search(e["text"]) for c, r in expected):
            continue
        # --only: nur Meldungen des Starts und der gelaufenen Prüfungen – auch späte („nach …“, z. B. ein Zeitgeber, der
        # erst nach dem Ende der Prüfung feuert); Vorbereitungen übersprungener Prüfungen dürfen scheitern (Marionette.js)
        if only and not chk.startswith("Start") and (chk.startswith("Vorbereitung") or not only.search(chk.removeprefix("nach "))):
            continue
        groups.setdefault(e["text"] + (f" ({e['wo']})" if e.get("wo") else ""), []).append(chk)
    errors = []
    for key, checks in groups.items():
        where = sorted(set(checks), key=checks.index)
        errors.append((f"{len(checks)}× " if len(checks) > 1 else "") + key + " – während " + "; ".join(c[:80] for c in where[:3])
                      + (f" und {len(where) - 3} weiteren" if len(where) > 3 else "") + (" · dunkel" if KONSOLE_DUNKEL else ""))
    notes = []
    if res.get("voll"):  # als Fehlerzeile: frühe Fehler (wie GitHub #38) könnten fehlen – das gehört ins Board
        errors.append(f"Fehlerkonsole schon beim Start voll ({KONSOLE_PUFFER} Meldungen), frühe Fehler können fehlen – während Start"
                      + (" · dunkel" if KONSOLE_DUNKEL else ""))
    if res.get("quelle") == "Puffer":
        notes.append("ohne Mitschrift, nur der Puffer der Konsole ausgewertet – frühe Meldungen können fehlen")
    return errors, notes


def konsole_melden(errors, notes, art="KONSOLE"):
    """Je Fehler eine Zeile „KONSOLE  …“ bzw. „PROTOKOLL  …“ – der CI-Wächter trägt sie als Bug ins Board."""
    for e in errors:
        print(f"{art}  {e}", flush=True)
    for n in notes:
        print(f"Hinweis Fehlerkonsole: {n}", flush=True)


def konsole_nachtrag(m, wann):
    """Meldungen, die nach der Prüfung „Fehlerkonsole“ kamen (Screenshots) bzw. alle, wenn sie nie lief (Abbruch der
    Prüfungen) – nur Ausgabe, nie eine Ausnahme."""
    try:
        res = konsole_lesen(m)
        if KONSOLE_STAND is not None:
            res["eintraege"] = (res.get("eintraege") or [])[KONSOLE_STAND:]
            res["voll"] = False
        errors, notes = konsole_bewerten(res)
        konsole_melden(errors, notes)
        # Fehlerprotokoll: alles, wenn seine Prüfung nie lief, sonst nur, was danach kam (Konsolen-Prüfung, Screenshots)
        pres = protokoll_lesen(m)
        if PROTOKOLL_STAND is not None:
            pres["eintraege"] = (pres.get("eintraege") or [])[PROTOKOLL_STAND:]
        perrors, _ = konsole_bewerten(pres)
        konsole_melden(perrors, [], "PROTOKOLL")
        if errors:
            print(f"Hinweis Fehlerkonsole: {len(errors)} Meldung(en) {wann}", flush=True)
    except Exception as e:
        print(f"Hinweis: Fehlerkonsole {wann} nicht lesbar – {e}", flush=True)


# Vergleichslauf ohne halo.spaces (Entscheidung des Maintainers vom 9.11.2026: nur die Startphase mit und ohne
# halo.spaces vergleichen): Thunderbirds eigene Fehler aus der Startphase eines frischen Profils ohne Paket, einmal je
# Thunderbird-Version und Plattform aufgezeichnet und zwischengespeichert. Startmeldungen von Thunderbird, die dort nie
# auftreten, meldet die Prüfung „Fehlerkonsole …“ als Zeile „KONSOLE  …“ (nur Warnung). Die Prüfphase wertet weiter
# nur die bestehende Einordnung aus (Fehler aus halo.spaces, HINTS).
VERGLEICH_AUS = False  # --ohne-vergleich
KONSOLE_VERGLEICH = None  # Schlüssel (tests/logik/konsole-schluessel.js) der Startfehler ohne halo.spaces; None: kein Vergleich
VERGLEICH_ORDNER = os.environ.get("HALO_KONSOLE_VERGLEICH") or os.path.join(os.path.expanduser("~"), ".cache", "halo-spaces",
                                                                           "konsole-vergleich")


def tb_ini(tb):
    """Text der application.ini des Thunderbird-Programms (neben dem Programm, unter macOS in Contents/Resources, beim
    Snap der Linux-VM /snap/bin/<name> → /snap/<name>/current/usr/lib/thunderbird) – None, wenn nicht lesbar."""
    d = os.path.dirname(os.path.realpath(shutil.which(tb) or tb))
    orte = [os.path.join(d, "application.ini"), os.path.join(d, "..", "Resources", "application.ini")]
    if tb.startswith("/snap/bin/"):
        orte.append(f"/snap/{os.path.basename(tb)}/current/usr/lib/thunderbird/application.ini")
    for ini in orte:
        try:
            return open(ini, encoding="utf-8", errors="replace").read()
        except OSError:
            continue
    return None


def tb_kennung(tb):
    """Version und Build-ID des Thunderbird-Programms aus application.ini (tb_ini) – None, wenn sie nicht lesbar ist
    (dann ohne Zwischenspeicher)."""
    text = tb_ini(tb) or ""
    v, b = re.search(r"^Version=(.+)$", text, re.M), re.search(r"^BuildID=(.+)$", text, re.M)
    if v:
        return re.sub(r"[^\w.-]", "_", f"{v.group(1).strip()}-{b.group(1).strip() if b else '0'}")
    return None


def vergleich_aufnehmen(tb, port, dark):
    """Startet Thunderbird einmal im frischen Profil OHNE halo.spaces und liefert Thunderbirds Fehler der Startphase
    (je Schlüssel einmal)."""
    profile = create_profile(None, port, dark, prefix="halo-test-vergleich-")
    proc = start_thunderbird(tb, profile)
    try:
        if not wait_port(port):
            raise RuntimeError("Thunderbird hat Marionette nicht geöffnet")
        m = Marionette(port)

        def run(body):
            return m.cmd("WebDriver:ExecuteScript", {"script": "return (async () => {" + body + "})();", "args": []}).get("value")
        end = time.time() + 90
        while not run('return Services.wm.getMostRecentWindow("mail:3pane")?.document.readyState === "complete";'):
            if time.time() > end:
                raise RuntimeError("kein Hauptfenster nach 90 s")
            time.sleep(0.5)
        # Feste Pause mit Absicht: der eigentliche Lauf liest die Startphase 8 s nach dem Port (main()); hier etwas
        # länger, damit späte Startmeldungen sicher im Vergleich stehen (sonst würden sie fälschlich gemeldet)
        time.sleep(12)
        return run(KONSOLE_JS + """
          const k = neu(); k.sammleFremd = true;
          for (const msg of Services.console.getMessageArray() || []) add(k, msg);
          return k.startfremd;""") or []
    finally:
        stop_thunderbird(port, proc)
        shutil.rmtree(profile, ignore_errors=True)


def vergleich_laden(tb, port, dark, neu=False):
    """Vergleichsliste aus dem Zwischenspeicher (je Plattform und Thunderbird-Version), sonst mit vergleich_aufnehmen
    erzeugen und speichern. Eine neue Aufnahme (--vergleich-neu) ergänzt die alte (Vereinigung: Thunderbirds
    Startfehler schwanken). Nie eine Ausnahme: ohne Liste kein Vergleich (Hinweis)."""
    kennung = tb_kennung(tb)
    # je Modus eine eigene Liste: der Vergleichslauf startet hell bzw. dunkel, Startfehler nur im Dunkelmodus gehörten
    # sonst nicht zur Liste des dunklen Laufs
    datei = os.path.join(VERGLEICH_ORDNER, f"{sys.platform}-{kennung}{'-dunkel' if dark else ''}.json") if kennung else None
    alt = []
    if datei and os.path.exists(datei):
        try:
            alt = json.load(open(datei, encoding="utf-8")).get("schluessel") or []
        except (OSError, ValueError, AttributeError):
            alt = []
        if alt and not neu:
            print(f"Vergleich ohne halo.spaces: {len(alt)} Startfehler von Thunderbird aus {datei}", flush=True)
            return set(alt)
    began = time.time()
    try:
        gefunden = vergleich_aufnehmen(tb, port, dark)
    except Exception as e:
        print(f"Hinweis Fehlerkonsole: Vergleichslauf ohne halo.spaces gescheitert ({e}) – Startmeldungen von Thunderbird "
              "werden nicht verglichen", flush=True)
        return set(alt) if alt else None
    schluessel = sorted(set(alt) | {e["schluessel"] for e in gefunden})
    print(f"Vergleichslauf ohne halo.spaces: {len(gefunden)} Startfehler von Thunderbird ({time.time() - began:.0f} s)"
          + (f", gespeichert in {datei}" if datei else ", ohne Zwischenspeicher (Version unbekannt)"), flush=True)
    for e in gefunden:
        print(f"  ohne halo.spaces: {e['text'][:160]} ({e['wo']})", flush=True)
    if datei:
        try:
            os.makedirs(VERGLEICH_ORDNER, exist_ok=True)
            with open(datei + ".neu", "w", encoding="utf-8") as f:
                json.dump({"thunderbird": kennung, "plattform": sys.platform, "aufgenommen": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
                           "schluessel": schluessel}, f, ensure_ascii=False, indent=1)
            os.replace(datei + ".neu", datei)
        except OSError as e:
            print(f"Hinweis Fehlerkonsole: Vergleichsliste nicht gespeichert – {e}", flush=True)
    return set(schluessel)


def konsole_start_vergleichen(startfremd, vergleich):
    """Startfehler von Thunderbird, die im Lauf ohne halo.spaces nie auftreten – je eine Zeile wie konsole_bewerten
    (der CI-Wächter schneidet „ – während …“ und den Ort „(…)“ für den Schlüssel ab)."""
    if vergleich is None or startfremd is None:
        return []
    return [f"{e['text']} ({e['wo']}) – während Start (Thunderbird-Meldung, im Vergleichslauf ohne halo.spaces nie)"
            + (" · dunkel" if KONSOLE_DUNKEL else "") for e in startfremd if e.get("schluessel") not in vergleich]


def wait_port(port, timeout=60):
    end = time.time() + timeout
    while time.time() < end:
        try:
            socket.create_connection(("127.0.0.1", port), timeout=1).close()
            return True
        except OSError:
            time.sleep(0.5)
    return False


def local_https(host):
    """Lokaler HTTPS-Server (selbst signiert, für host) für die Netzprüfung der
    Absenderbilder, dazu ein „Gerät im lokalen Netz“ (http auf 127.0.0.1), das
    jeden Zugriff mitschreibt. Liefert Port, Zertifikat (DER, Base64), die
    Zugriffe aufs Gerät, die empfangenen POSTs und eine Funktion zum Beenden."""
    import base64
    import http.server
    import ssl
    import threading
    tmp = tempfile.mkdtemp(prefix="halo-netz-")
    key, crt = os.path.join(tmp, "key.pem"), os.path.join(tmp, "cert.pem")
    subprocess.run([OPENSSL, "req", "-x509", "-newkey", "rsa:2048", "-nodes", "-keyout", key, "-out", crt, "-days", "2",
                    "-subj", f"/CN={host}", "-addext", f"subjectAltName=DNS:{host}",
                    "-addext", "basicConstraints=critical,CA:FALSE"], check=True, capture_output=True)
    hits, posts, stop = [], [], threading.Event()

    class Device(http.server.BaseHTTPRequestHandler):
        def do_GET(self):
            hits.append(self.path)
            self.send_response(200)
            self.end_headers()

        def log_message(self, *args):
            pass

    class Sender(http.server.BaseHTTPRequestHandler):
        def do_GET(self):
            if self.path == "/umleitung":  # Absender leitet auf ein Gerät im lokalen Netz um
                self.send_response(302)
                self.send_header("Location", f"http://127.0.0.1:{device.server_port}/geraet")
                self.end_headers()
            elif self.path == "/weiter":  # Umleitung auf eine öffentliche Adresse bleibt erlaubt
                self.send_response(302)
                self.send_header("Location", f"https://{host}:{server.server_port}/ziel")
                self.end_headers()
            elif self.path == "/ziel":
                self.send_response(200)
                self.send_header("Content-Type", "text/html; charset=utf-8")
                self.end_headers()
                self.wfile.write("<head></head>Grüße".encode())
            elif self.path == "/anmelden":  # wie iCloud-Fotos: 401 ohne Anmeldedialog
                self.send_response(401)
                self.send_header("WWW-Authenticate", 'Basic realm="Halo"')
                self.end_headers()
            elif self.path == "/endlos":  # Daten ohne Ende (höchstens 20 MB)
                self.send_response(200)
                self.send_header("Content-Type", "image/png")
                self.end_headers()
                try:
                    for _ in range(320):
                        self.wfile.write(b"x" * 65536)
                except OSError:
                    pass
            elif self.path == "/stumm":  # nach den Kopfzeilen kommt nichts mehr
                self.send_response(200)
                self.send_header("Content-Type", "image/png")
                self.end_headers()
                self.wfile.write(b"x" * 10)
                self.wfile.flush()
                stop.wait(30)
            else:
                self.send_response(404)
                self.end_headers()

        def do_POST(self):
            posts.append(self.rfile.read(int(self.headers.get("Content-Length") or 0)).decode())
            if self.path == "/abmelden-umleitung":  # Abmeldung leitet auf eine Bestätigungsseite im lokalen Netz um
                self.send_response(303)
                self.send_header("Location", f"http://127.0.0.1:{device.server_port}/bestaetigt")
                self.end_headers()
                return
            self.send_response(200)
            self.end_headers()

        def log_message(self, *args):
            pass

    device = http.server.ThreadingHTTPServer(("127.0.0.1", 0), Device)
    server = http.server.ThreadingHTTPServer(("127.0.0.1", 0), Sender)
    ctx = ssl.SSLContext(ssl.PROTOCOL_TLS_SERVER)
    ctx.load_cert_chain(crt, key)
    server.socket = ctx.wrap_socket(server.socket, server_side=True)
    for s in (device, server):
        s.daemon_threads = True
        threading.Thread(target=s.serve_forever, daemon=True).start()
    der = base64.b64encode(ssl.PEM_cert_to_DER_cert(open(crt).read())).decode()

    def close():
        stop.set()
        for s in (device, server):
            s.shutdown()
            s.server_close()
        shutil.rmtree(tmp, ignore_errors=True)
    return server.server_port, der, hits, posts, close


def create_profile(xpi, port, dark=False, prefix="halo-test-"):
    """Legt ein leeres, temporäres Profil mit installiertem Paket an (keine Konten, keine echten Daten); ohne xpi
    ohne Paket (Vergleichslauf)."""
    profile = tempfile.mkdtemp(prefix=prefix)
    os.makedirs(os.path.join(profile, "extensions"))
    if xpi:
        shutil.copy(xpi, os.path.join(profile, "extensions", f"{ADDON_ID}.xpi"))
    with open(os.path.join(profile, "user.js"), "w") as f:
        for pref, value in {
            "extensions.autoDisableScopes": 0,
            "marionette.port": port,
            "mail.shell.checkDefaultClient": False,
            "mail.provider.suppress_dialog_on_startup": True,
            "mail.rights.version": 1,
            "app.update.enabled": False,
            "datareporting.policy.dataSubmissionPolicyBypassNotification": True,
            "toolkit.telemetry.reportingpolicy.firstRun": False,
            "calendar.timezone.useSystemTimezone": True,
            # Zeitgeber im Hintergrund nicht drosseln
            "widget.windows.window_occlusion_tracking.enabled": False,
            "dom.timeout.enable_budget_timer_throttling": False,
            "dom.min_background_timeout_value": 4,
            # das macOS-Adressbuch (echte Kontakte) nicht einbinden
            "ldap_2.servers.osx.position": 0,
            # Marionette schaltet Add-on-Updates beim Start ab, sofern hier nichts steht; die Vorbereitung
            # schaltet sie erst danach wieder ein – unter Last (ESR in der CI) zu spät für die Prüfung
            # beim Start nach 20 s. Die Abfrage der updates.json blockt die Vorbereitung weiterhin.
            "extensions.update.enabled": True,
            # updates.json auf GitHub vom ersten Augenblick an unerreichbar (Name zeigt auf den eigenen Rechner, dort
            # lauscht nichts auf 443): die Sperre der Vorbereitung (http-on-modify-request) kommt erst nach den ersten
            # Prüfungen, die Update-Prüfung beim Start läuft nach 20 s – unter Last kam sie zuerst und holte das echte,
            # gerade veröffentlichte 3.30.0 in ein Paket 3.29.0 (CI 18.11. Lauf 44263445114 linux beta: Prüfung beim Start
            # 08:02:53, Vorbereitung erst danach; „Updates: bereitliegendes Update …“ fand den roten Punkt schon vorher)
            "network.dns.localDomains": "raw.githubusercontent.com",
            **({"ui.systemUsesDarkTheme": 1} if dark else {}),
        }.items():
            f.write(f"user_pref({json.dumps(pref)}, {json.dumps(value)});\n")
    # Alte Designkopie im Profil, wie sie „Design ohne Aufblitzen“ einer früheren Fassung hinterlässt: Thunderbird lädt
    # sie beim Programmstart und behält sie bis zum Beenden (so sieht ein Update ohne Neustart aus). halo.spaces räumt
    # Datei und Einstellungen beim Start weg (Option ist aus) und muss das schon geladene Stilblatt stilllegen –
    # Prüfung „Design: alte Kopie aus dem Profil …“. In prefs.js statt user.js, damit es nur für den ersten Start gilt
    if xpi:
        os.makedirs(os.path.join(profile, "chrome"))
        with open(os.path.join(profile, "chrome", "userChrome.css"), "w") as f:
            f.write("/* halo.spaces: automatisch geschrieben (Start ohne Aufblitzen), Version 0.0.1 Stand 00000000 – nicht von Hand "
                    "ändern, wird ersetzt */\n:root { --mt-accent: AccentColor; --mc-test-alte-fassung: 1; }\n")
        with open(os.path.join(profile, "prefs.js"), "w") as f:
            f.write('user_pref("toolkit.legacyUserProfileCustomizations.stylesheets", true);\n'
                    'user_pref("extensions.mailcards.earlyThemeSetLegacy", true);\n')
    return profile


def start_thunderbird(tb, profile, log=None):
    """Startet Thunderbird mit Marionette im angegebenen Profil."""
    out = open(log, "w") if log else subprocess.DEVNULL
    return subprocess.Popen([tb, "-profile", profile, "-no-remote", "-marionette", "-remote-allow-system-access"],
                            stdout=out, stderr=subprocess.STDOUT if log else subprocess.DEVNULL,
                            # ab Thunderbird 159 zusätzlich als Umgebungsvariable nötig
                            env={**os.environ, "MOZ_REMOTE_ALLOW_SYSTEM_ACCESS": "1"})


def stop_thunderbird(port, proc):
    """Beendet das Test-Thunderbird (nur den selbst gestarteten Prozess)."""
    try:
        Marionette(port).js("Services.startup.quit(Ci.nsIAppStartup.eForceQuit); return 1;")
    except Exception:
        pass
    try:
        proc.wait(timeout=20)
    except subprocess.TimeoutExpired:
        proc.kill()
        try:
            proc.wait(timeout=10)
        except subprocess.TimeoutExpired:
            pass
    # erst zurück, wenn der Marionette-Port nichts mehr annimmt: sonst verbindet sich wait_port() des nächsten Starts
    # (Vergleichslauf → eigentlicher Lauf, gleicher Port) noch mit dem alten Thunderbird und Marionette() trifft 8 s
    # später auf den geschlossenen Port (CI linux 15.11.2026: Port nach 0,4 s „offen“, dann „Connection refused“)
    began, end = time.time(), time.time() + 30
    while time.time() < end:
        try:
            socket.create_connection(("127.0.0.1", port), timeout=1).close()
        except OSError:
            break
        time.sleep(0.25)
    else:
        print(f"Hinweis: Marionette-Port {port} nimmt 30 s nach dem Beenden von Thunderbird noch Verbindungen an", flush=True)
        if shutil.which("lsof"):
            subprocess.run(["lsof", "-nP", f"-iTCP:{port}", "-sTCP:LISTEN"], check=False)
        return
    if time.time() - began > 0.5:
        print(f"Hinweis: Marionette-Port {port} nach dem Beenden von Thunderbird noch {time.time() - began:.1f} s offen",
              flush=True)


# VM-Funktionen auf dem Mac (prlctl, Sperre, Kurztest Bildtakt, kalter Neustart): tests/vm_frisch.py. In der VM
# selbst nicht gebraucht (die Datei wird nicht hineinkopiert)
if os.path.dirname(os.path.abspath(__file__)) not in sys.path:
    sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
try:
    import vm_frisch as vmf
    from vm_frisch import prl, vm_exec, vm_state, vm_ready, vm_vorbereiten
except ImportError:
    vmf = None


def vm_frisch_danach(vm):
    """Nach einem Lauf mit --vm: VM herunterfahren, gelöst im Hintergrund (tests/vm_frisch.py --nach-lauf; jede VM
    auf neon nach dem Test aus, Maintainer 21.11.2026). Die Sperre geht ohne Lücke an ihn über; ein Folgelauf (auch
    die Wiederholung durch ci-wiederholen.sh) wartet so und startet die VM danach frisch. Liefert True, wenn die
    Sperre übergeben ist."""
    try:
        nacht = os.path.expanduser("~/halo-nacht")
        p = vmf.hintergrund(["--vm", vm, "--nach-lauf", "--nach-pid", str(os.getpid())],
                            os.path.join(nacht, "vm-frisch.log") if os.path.isdir(nacht) else None)
        vmf.lock_uebergeben(p.pid, "vm-frisch nach Lauf")
        print("VM wird nach dem Lauf im Hintergrund heruntergefahren (Protokoll ~/halo-nacht/vm-frisch.log)", flush=True)
        return True
    except OSError as e:
        print(f"HINWEIS Herunterfahren der VM im Hintergrund nicht gestartet: {e}", flush=True)
        return False


THEME_KEY = r"HKCU\Software\Microsoft\Windows\CurrentVersion\Themes\Personalize"


def vm_theme(vm, values=None):
    """Liest bzw. setzt das Windows-Farbschema (AppsUseLightTheme/SystemUsesLightTheme, 1 = hell)."""
    names = ("AppsUseLightTheme", "SystemUsesLightTheme")
    if values is None:
        out = {}
        for n in names:
            m = re.search(r"0x([0-9a-f]+)", vm_exec(vm, "reg", "query", THEME_KEY, "/v", n, check=False).stdout)
            out[n] = int(m.group(1), 16) if m else 1
        return out
    for n in names:
        vm_exec(vm, "reg", "add", THEME_KEY, "/v", n, "/t", "REG_DWORD", "/d", str(values[n]), "/f")


def wait_turn(mine):
    """Wartet, bis kein Lauf der anderen Plattform mehr läuft (höchstens eine Stunde)."""
    def busy():
        if mine == "vm" and subprocess.run(["pgrep", "-f", "--", "-profile .*/halo-test-"], capture_output=True).returncode == 0:
            if vmf:
                vmf.lauf_warten_ende()  # wartet auf den Mac, nicht auf die Sperre: keine VM übernehmen
            return True  # Test-Thunderbird auf dem Mac
        # Lauf in der VM bzw. Wartung (vm_frisch.py); ein Lauf in der VM nimmt die Sperre dabei gleich atomar und
        # meldet sich als wartend (übernimmt dann die laufende VM, statt dass die Wartung sie herunterfährt)
        return not vmf.lauf_lock_nehmen() if mine == "vm" else vmf.lock_pid() is not None
    end, said = time.time() + 3600, False
    while busy():
        if time.time() > end:
            sys.exit("Abbruch: der andere Testlauf ist nach einer Stunde noch nicht fertig")
        if not said:
            print("Warte: es läuft ein Test " + ("auf dem Mac" if mine == "vm" else "in der Windows-VM") + " – Mac- und Windows-Läufe nie gleichzeitig …", flush=True)
            said = True
        time.sleep(10)


def run_in_vm(args, xpi):
    """Führt diesen Test in der Windows-VM aus: Dateien über die Freigabe, Python und Thunderbird in der VM,
    Marionette dort lokal (Port wie --port, nur in der VM erreichbar). Screenshots kommen zurück auf den Mac."""
    if not shutil.which("prlctl"):
        sys.exit("prlctl fehlt – Parallels Desktop (Pro) installieren")
    vm = args.vm
    os.makedirs(VM_SHARE, exist_ok=True)
    wait_turn("vm")  # nimmt die Sperre ~/halo-vm/lauf.lock atomar (vm_frisch.lock_nehmen)
    run = tempfile.mkdtemp(prefix="lauf-", dir=VM_SHARE)
    win = VM_UNC + "\\" + os.path.basename(run)
    before = theme = None
    try:
        os.makedirs(os.path.join(run, "tests"))
        for f in ("halo_test.py", "testserver.py", "sprung_lib.py", "toolbar_lib.py", "perf.js", "win-display.ps1", "win-bildtakt.ps1", "logik/konsole-schluessel.js"):
            os.makedirs(os.path.dirname(os.path.join(run, "tests", f)), exist_ok=True)
            shutil.copy(os.path.join(ROOT, "tests", f), os.path.join(run, "tests", f))
        # manifest.json und Stilblätter (z. B. options/options.css) lesen einzelne Prüfungen direkt
        shutil.copytree(os.path.join(ROOT, "extension"), os.path.join(run, "extension"))
        shutil.copy(os.path.join(ROOT, "updates.json"), os.path.join(run, "updates.json"))  # für die Prüfung des Update-Wegs
        shutil.copy(xpi, os.path.join(run, os.path.basename(xpi)))
        inner = {"xpi": win + "\\" + os.path.basename(xpi), "tb": VM_TB["beta" if args.beta else "release"] if args.tb == DEFAULT_TB else args.tb,
                 "port": args.port, "dark": args.dark, "keep": args.keep, "only": args.only, "eval": args.eval, "perf": args.perf,
                 "tb_log": win + "\\thunderbird.log" if args.tb_log else None,
                 "shots": win + "\\shots" if args.shots else None, "compare": None,
                 "ohne_vergleich": args.ohne_vergleich, "vergleich_neu": args.vergleich_neu}
        if args.compare:
            shutil.copytree(args.compare, os.path.join(run, "vorher"))
            inner["compare"] = win + "\\vorher"
        json.dump(inner, open(os.path.join(run, "args.json"), "w"))

        before = vm_state(vm)  # vor der Vorbereitung gesetzt: bricht sie ab, fährt finally die VM trotzdem herunter
        vm_vorbereiten(vm, run, win)
        print(f"Windows-VM „{vm}“ (vorher {before}) · {inner['tb']}", flush=True)
        try:
            shown = open(os.path.join(run, "display.txt")).read().split()
            if len(shown) == 3 and (int(shown[1]) < 1600 or int(shown[2]) < 1000):
                print(f"HINWEIS Bildschirm der VM nur {shown[1]} × {shown[2]} – Skalierung 100 %? (tests/win-vm-setup.ps1 -Benutzer)", flush=True)
        except (OSError, ValueError):
            print("HINWEIS Bildschirmgröße der VM unbekannt", flush=True)
        theme = vm_theme(vm)
        want = 0 if args.dark else 1
        if set(theme.values()) != {want}:
            vm_theme(vm, {k: want for k in theme})
            time.sleep(3)  # Windows färbt Fensterrahmen und Taskleiste um
        for attempt in (1, 2):
            began = time.time()
            proc = subprocess.Popen(["prlctl", "exec", vm, "--current-user", VM_PY, "-u", win + "\\tests\\halo_test.py",
                                     "--vm-args", win + "\\args.json"])
            try:
                rc = proc.wait(timeout=3600)
            except subprocess.TimeoutExpired:
                proc.kill()
                vm_exec(vm, "taskkill", "/f", "/im", "thunderbird.exe", check=False)
                rc = 1
                print("FEHLER  Testlauf in der VM nach einer Stunde abgebrochen", flush=True)
            # 255 nach wenigen Sekunden: prlctl hat den Lauf gar nicht gestartet (Gastwerkzeuge
            # nach dem Fortsetzen noch nicht bereit) – einmal warten und neu versuchen
            if rc != 255 or time.time() - began > 60 or attempt == 2:
                break
            print("HINWEIS prlctl exec scheiterte sofort (Code 255) – VM noch nicht bereit, neuer Versuch in 20 s", flush=True)
            time.sleep(20)
            vm_ready(vm)
        if args.shots and os.path.isdir(os.path.join(run, "shots")):
            shutil.copytree(os.path.join(run, "shots"), args.shots, dirs_exist_ok=True)
        if args.tb_log and os.path.exists(os.path.join(run, "thunderbird.log")):
            shutil.copy(os.path.join(run, "thunderbird.log"), args.tb_log)
        return rc
    finally:
        try:
            if theme and before:
                try:
                    vm_theme(vm, theme)
                except (subprocess.CalledProcessError, subprocess.TimeoutExpired) as e:
                    print(f"HINWEIS Farbschema der VM nicht zurückgestellt: {e}", flush=True)
            # jede VM auf neon nach dem Test ganz herunterfahren, nie pausieren (Maintainer 21.11.2026; Speicher für
            # die macOS-Tests, der nächste Lauf startet sie frisch): im Hintergrund, sonst hier (--vm-weiter: laufen
            # lassen für Handarbeit)
            if before and not args.vm_weiter and not vm_frisch_danach(vm):
                vmf.vm_stoppen(vm)
        finally:
            shutil.rmtree(run, ignore_errors=True)
            vmf.lock_freigeben()  # (nur, wenn sie noch uns gehört; übergeben ist sie dem Herunterfahren)
            vmf.lauf_warten_ende()


# Abbruch von außen (pkill, Zeitgrenze eines Werkzeugs, beendete Sitzung): SIGTERM und SIGHUP lösen SystemExit aus, damit
# die finally-Blöcke laufen – Thunderbird beenden, Profil löschen, VM herunterfahren. Ohne das starb Python sofort und
# Thunderbird lief unter launchd weiter (Vorfall 24./25.11.2026: verwaister Test-Thunderbird hielt den Nachtlauf eine
# Stunde auf, ~/halo-berichte/2026-11-25-verwaiste-testprozesse.md). Gegen SIGKILL hilft das nicht (dafür
# verwaiste_tb_beenden in tests/lauf-hilfen.zsh). Exitcode 128 + Signalnummer wie bei einem Abbruch durch das Signal.
AUFRAEUMEN = False    # True, solange das Aufräumen läuft: ein weiteres Signal unterbricht es dann nicht mehr
SIGNAL_CODE = None    # Signal während des Aufräumens: Exitcode für danach
ABGEBROCHEN = False   # durch Signal abgebrochen: keine Nachträge mehr über Marionette (Antwort evtl. noch unterwegs)


def signal_beenden(signum, frame):
    global SIGNAL_CODE, ABGEBROCHEN
    if AUFRAEUMEN:
        SIGNAL_CODE = SIGNAL_CODE or 128 + signum
        return
    ABGEBROCHEN = True
    print(f"\nAbbruch durch Signal {signum}: räume auf (Thunderbird beenden, Profil löschen) …", flush=True)
    raise SystemExit(128 + signum)


def signale_abfangen():
    signal.signal(signal.SIGTERM, signal_beenden)
    # SIGHUP gibt es unter Windows nicht; mit nohup gestartet (SIGHUP ignoriert) bleibt es beim Ignorieren
    if hasattr(signal, "SIGHUP") and signal.getsignal(signal.SIGHUP) != signal.SIG_IGN:
        signal.signal(signal.SIGHUP, signal_beenden)


def main():
    global LAST_END, CHECK_M, KONSOLE_DUNKEL, KONSOLE_VERGLEICH, VERGLEICH_AUS, AUFRAEUMEN
    signale_abfangen()
    ap = argparse.ArgumentParser()
    ap.add_argument("--xpi", help="Paket (Standard: neuestes dist/halo-spaces-*.xpi)")
    ap.add_argument("--tb", default=DEFAULT_TB, help="Thunderbird-Programm")
    ap.add_argument("--keep", action="store_true", help="Testprofil nicht löschen")
    ap.add_argument("--tb-log", help="Ausgabe von Thunderbird in diese Datei schreiben (zur Fehlersuche)")
    ap.add_argument("--dark", action="store_true", help="im Dunkelmodus starten")
    ap.add_argument("--shots", help="Ordner für Screenshots aller Bereiche")
    ap.add_argument("--eval", help="nur dieses JavaScript ausführen (Chrome-Kontext, mit den Hilfen aus PRELUDE) und das Ergebnis ausgeben – zum Untersuchen")
    ap.add_argument("--perf", action="store_true", help="nur die Geschwindigkeit messen (5000 Mails, mit und ohne halo.spaces)")
    ap.add_argument("--port", type=int, default=PORT, help=f"Marionette-Port (Standard {PORT}; eigener Port erlaubt mehrere Testläufe gleichzeitig)")
    ap.add_argument("--compare", help="Ordner mit früheren Screenshots: zeigt, wo sich etwas verändert hat (braucht --shots)")
    ap.add_argument("--only", help="nur Prüfungen, deren Name auf diesen regulären Ausdruck passt (z. B. \"Anhänge\")")
    ap.add_argument("--vm", nargs="?", const=VM_NAME, help=f"in der Windows-VM testen (Parallels, Standard „{VM_NAME}“, sonst $HALO_VM); "
                    "startet die VM vorher und fährt sie danach herunter (HALO_VM_KEIN_NEUSTART=1: kein Neustart bei gestörtem Bildtakt)")
    ap.add_argument("--linux-vm", action="store_true", help="in der Linux-VM testen (Parallels „Ubuntu“, tests/linux_vm.py; nur "
                    "Werkzeug für Rundgang und Design, zählt nie für die Testmarke); startet die VM vorher und fährt sie danach herunter")
    ap.add_argument("--beta", action="store_true", help="mit --vm bzw. --linux-vm: Thunderbird Beta der VM")
    ap.add_argument("--vm-weiter", action="store_true", help="mit --vm bzw. --linux-vm: VM nach dem Lauf laufen lassen (Handarbeit)")
    ap.add_argument("--ohne-vergleich", action="store_true", help="ohne Vergleichslauf ohne halo.spaces (Startmeldungen von "
                    "Thunderbird in der Fehlerkonsole werden dann nicht verglichen)")
    ap.add_argument("--vergleich-neu", action="store_true", help="Vergleichslauf ohne halo.spaces neu aufnehmen (ergänzt die "
                    f"gespeicherte Liste in {VERGLEICH_ORDNER})")
    ap.add_argument("--vm-args", help=argparse.SUPPRESS)  # in der VM: Optionen aus der Datei (prlctl reicht keine Anführungszeichen weiter)
    args = ap.parse_args()
    if args.vm_args:
        for k, v in json.load(open(args.vm_args)).items():
            setattr(args, k, v)
    if args.only:
        global ONLY
        ONLY = re.compile(args.only, re.I)

    if not args.xpi:
        # ohne Angabe immer den aktuellen Stand bauen (sonst testet man ein altes Paket)
        built = subprocess.run([os.path.join(ROOT, "build.sh")], capture_output=True, text=True, cwd=ROOT)
        if built.returncode != 0:
            sys.exit("build.sh fehlgeschlagen:\n" + built.stderr)
    xpi = args.xpi or max((x for x in glob.glob(os.path.join(ROOT, "dist", "halo-spaces-*.xpi")) if not x.endswith("-atn.xpi")),
                           key=os.path.getmtime, default=None)  # nicht die Store-Variante (ohne update_url)
    if not xpi or not os.path.exists(xpi):
        sys.exit("Kein Paket gefunden – zuerst ./build.sh")
    # Version aus dem getesteten Paket (nicht aus dem Checkout: der Notfall-Release baut mit anderer Version als das Repo);
    # beim Standardbau stimmen beide überein
    with zipfile.ZipFile(xpi) as zf:
        version = json.loads(zf.read("manifest.json"))["version"]
    faktisch_setzen(version)
    if args.vm:
        sys.exit(run_in_vm(args, xpi))
    if getattr(args, "linux_vm", False):  # (in der VM selbst kommt die Option nicht aus args.json, bleibt also aus)
        import linux_vm
        sys.exit(linux_vm.lauf(args, xpi))
    if sys.platform == "darwin":
        wait_turn("mac")
    VERGLEICH_AUS = bool(args.ohne_vergleich)
    if not (args.eval or args.perf or args.ohne_vergleich):
        # Startphase ohne halo.spaces (einmal je Thunderbird-Version und Plattform, sonst aus dem Zwischenspeicher)
        KONSOLE_VERGLEICH = vergleich_laden(args.tb, args.port, args.dark, args.vergleich_neu)

    profile = create_profile(xpi, args.port, args.dark)
    proc = None
    results = []
    try:
        print(f"halo.spaces {version} · Paket {os.path.basename(xpi)} · Profil {profile}", flush=True)
        if args.vm_args:  # in der VM: welches System und welche Thunderbird-Version (application.ini, tb_ini)
            tbv = re.search(r"^Version=(.+)$", tb_ini(args.tb) or "", re.M)
            print(f"{platform.system()} {platform.release() if sys.platform.startswith('linux') else platform.version()}"
                  f" · Thunderbird {tbv.group(1).strip() if tbv else '?'}", flush=True)
        proc = start_thunderbird(args.tb, profile, args.tb_log)
        if not wait_port(args.port):
            sys.exit("Thunderbird hat Marionette nicht geöffnet")
        time.sleep(8)  # Erweiterung und Fenster fertig aufbauen lassen
        m = Marionette(args.port)
        if args.perf:
            args.eval = open(os.path.join(ROOT, "tests", "perf.js")).read()
        if args.eval:
            m.cmd("WebDriver:SetTimeouts", {"script": 600000})
            print(json.dumps(m.js(args.eval), indent=1, ensure_ascii=False))
            return
        KONSOLE_DUNKEL = bool(args.dark)
        konsole_start(m)
        LAST_END = started = time.time()
        CHECK_M = m
        try:
            run_checks(m, version, profile, results)
        finally:
            if KONSOLE_STAND is None and not ABGEBROCHEN:  # Prüfungen abgebrochen: Konsole und Protokoll trotzdem ausgeben (oft die Erklärung)
                konsole_nachtrag(m, "bis zum Abbruch der Prüfungen")
        try:  # wie oft ruhig() bis zur Höchstzeit (der früheren festen Pause) gewartet hat
            full = m.cmd("WebDriver:ExecuteScript", {"script": PRELUDE.split("const wait")[0] + "return w.__haloRuhigVoll || {};", "args": []}).get("value")
        except Exception:
            full = "?"
        print(f"\nDauer der Prüfungen: {(time.time() - started) / 60:.1f} Min.; am längsten:", flush=True)
        for sec, name in sorted(DURATIONS, reverse=True)[:10]:
            print(f"  {sec:5.1f} s  {name[:90]}", flush=True)
        if isinstance(full, dict):
            print(f"ruhig() bis zur Höchstzeit (frühere feste Pause): {sum(full.values())}×, aufgehalten durch (Grund ⟵ Prüfung):", flush=True)
            for why, n in sorted(full.items(), key=lambda x: -x[1])[:15]:
                print(f"  {n:4d}×  {why[:160]}", flush=True)
        if args.shots:
            mark_check("Screenshots")
            try:
                take_shots(m, args.shots, "dark" if args.dark else "light")
            finally:
                if not ABGEBROCHEN:
                    konsole_nachtrag(m, "bei den Screenshots")
            if args.compare:
                compare_shots(m, args.compare, args.shots)
    finally:
        AUFRAEUMEN = True
        if proc:
            stop_thunderbird(args.port, proc)
        if not args.keep:
            shutil.rmtree(profile, ignore_errors=True)
        AUFRAEUMEN = False
    if SIGNAL_CODE:  # Signal kam während des Aufräumens: Aufräumen fertig, dann mit dem Signalcode enden
        sys.exit(SIGNAL_CODE)

    failed = [r for r in results if not r[1]]
    print(f"\n{len(results) - len(failed)} von {len(results)} Prüfungen OK" + (f", {len(failed)} FEHLER" if failed else ""))
    sys.exit(1 if failed else 0)


def take_shots(m, folder, scheme):
    """Screenshots aller Bereiche (Testprofil, keine echten Daten)."""
    import base64
    os.makedirs(folder, exist_ok=True)
    for name, js in [
        ("mail", "await toMail();"),
        ("message", MESSAGE_JS),
        # Aktionen beim Überfahren (Kapsel unter dem Mailkopf) – :hover festgehalten
        ("message-hover", MESSAGE_JS + """const hd = tm.currentAbout3Pane.messageBrowser.contentDocument;
          hd.getElementById("mcHoverActions")?.style.setProperty("transition", "none");
          InspectorUtils.addPseudoClassLock(hd.documentElement, ":hover");"""),
        ("message-remote", """const { MailServices } = ChromeUtils.importESModule("resource:///modules/MailServices.sys.mjs"); await toMail();
          const hd = tm.currentAbout3Pane.messageBrowser.contentDocument; InspectorUtils.clearPseudoClassLocks(hd.documentElement);
          hd.getElementById("mcHoverActions")?.style.removeProperty("transition"); const f = MailServices.accounts.localFoldersServer.rootFolder.getChildNamed("Schrift");
          const a3 = tm.currentAbout3Pane; a3.displayFolder(f.URI); await bis(() => a3.gFolder?.URI == f.URI && a3.gDBView?.rowCount, "Ordner Schrift", 5000); await ruhig(800);
          for (let i = 0; i < a3.gDBView.rowCount; i++) if (a3.gDBView.getMsgHdrAt(i).subject == "Schrift 1") a3.threadTree.selectedIndex = i;
          await bis(() => a3.messageBrowser?.contentWindow?.gMessage?.subject == "Schrift 1", "Mail Schrift 1 geladen", 8000); await ruhig(6000);"""),
        ("mail-1280", "w.resizeTo(1280, 900); await until(() => w.outerWidth == 1280 || w.innerWidth == 1280, 3000); await ruhig(1200); await toMail();"),
        ("calendar-week", 'await toCalendar(); w.switchToView("week"); await ruhig(800);'),
        ("calendar-month", 'await toCalendar(); w.switchToView("month"); await ruhig(800);'),
        ("tasks", 'tm.openTab("tasks", {}); await ruhig(1500);'),
        ("addressbook", 'tm.openTab("addressBookTab", {}); await ruhig(2000);'),
        ("addressbook-edit", ADDRESS_EDIT_JS),
        ("settings", "w.openPreferencesTab(); await ruhig(2000);"),
        ("addon-settings", f'w.openAddonsMgr("addons://detail/" + encodeURIComponent("{ADDON_ID}") + "/preferences"); await ruhig(3000);'),
        # Mehrfachauswahl als Stapel (drei markierte Mails)
        ("mail-stack", MAILLIST_JS + """await showFolder(); await asCards(); const v = a3.gDBView;
          a3.threadTree.selectedIndices = [...Array(v.rowCount).keys()].filter(k => ["halo-ml-3@example.invalid", "halo-ml-4@example.invalid", "halo-ml-5@example.invalid"].includes(v.getMsgHdrAt(k)?.messageId));
          await bis(() => a3.document.querySelector("#mcConversation.mc-stack browser")?.contentDocument?.getElementById("expandedsubjectBox")?.textContent.includes("Halo"), "Stapel geladen", 8000); await ruhig(1500);"""),
    ]:
        m.js(("" if "resizeTo" in js else "w.resizeTo(1500, 900); ") + js + " await until(() => [1280, 1500].includes(w.outerWidth) || [1280, 1500].includes(w.innerWidth), 3000); await ruhig(600); return 1;")
        data = m.cmd("WebDriver:TakeScreenshot", {})["value"]
        path = os.path.join(folder, f"{scheme}-{name}.png")
        open(path, "wb").write(base64.b64decode(data))
        print(f"Screenshot {path}", flush=True)
    # eigene Fenster: Verfassen und Termin-Dialog
    for name, js in [
        ("compose", COMPOSE_JS),
        ("event-dialog", 'await toCalendar(); w.switchToView("week"); w.createEventWithDialog(null, null, null, "Halo Dialog"); await bis(() => [...Services.wm.getEnumerator(null)].find(x => x.location.href.includes("calendar-event-dialog") && x.document.readyState == "complete"), "Termin-Dialog offen", 6000); await ruhig(2500); return 1;'),
        ("calendar-properties", 'w.openDialog("chrome://calendar/content/calendar-properties-dialog.xhtml", "_blank", "centerscreen,chrome,titlebar,resizable", { calendar: testCalendar() }); await bis(() => [...Services.wm.getEnumerator(null)].find(x => x.location.href.includes("calendar-properties-dialog") && x.document.readyState == "complete"), "Kalender-Eigenschaften offen", 6000); await ruhig(2000); return 1;'),
    ]:
        handles = lambda: (lambda r: r["value"] if isinstance(r, dict) else r)(m.cmd("WebDriver:GetWindowHandles"))
        main = (lambda r: r["value"] if isinstance(r, dict) else r)(m.cmd("WebDriver:GetWindowHandle"))
        before = set(handles())
        m.js(js)
        new = [h for h in handles() if h not in before]
        if not new:
            print(f"Screenshot {name}: kein Fenster", flush=True)
            continue
        m.cmd("WebDriver:SwitchToWindow", {"handle": new[0]})
        # einheitliche Bildgröße – das Terminfenster aber in seiner eigenen (schmalen) Breite, nur höher
        m.cmd("WebDriver:ExecuteScript", {"script": "if (document.documentElement.hasAttribute('mc-event')) window.resizeTo(window.outerWidth, 700); else window.resizeTo(900, 700); return new Promise(r => setTimeout(r, 800));", "args": []})
        data = m.cmd("WebDriver:TakeScreenshot", {})["value"]
        path = os.path.join(folder, f"{scheme}-{name}.png")
        open(path, "wb").write(base64.b64decode(data))
        print(f"Screenshot {path}", flush=True)
        m.cmd("WebDriver:ExecuteScript", {"script": "window.close(); return 1;", "args": []})
        m.cmd("WebDriver:SwitchToWindow", {"handle": main})


