SERVER_ACCOUNT_JS = r"""
  const { MailServices } = ChromeUtils.importESModule("resource:///modules/MailServices.sys.mjs");
  const existing = MailServices.accounts.accounts.find(a => a.incomingServer?.hostName == "127.0.0.1" && a.incomingServer.port == %(imap)d);
  if (existing) return existing.key;
  // wie der Konto-Assistent: „Lokale Ordner“ mit Postausgang gehören dazu (ohne sie sendet Thunderbird nicht im Hintergrund)
  try { MailServices.accounts.localFoldersServer; } catch { MailServices.accounts.createLocalMailAccount(); await ruhig(500); }
  const server = MailServices.accounts.createIncomingServer("halo", "127.0.0.1", "imap");
  server.port = %(imap)d;
  server.socketType = Ci.nsMsgSocketType.plain;
  server.authMethod = Ci.nsMsgAuthMethod.passwordCleartext;
  server.password = "halo-test";
  server.prettyName = "Halo Testkonto";
  const outgoing = MailServices.outgoingServer || MailServices.smtp;
  const smtp = outgoing.createServer("smtp");
  const sm = smtp.QueryInterface ? smtp.QueryInterface(Ci.nsISmtpServer) : smtp;
  sm.hostname = "127.0.0.1"; sm.port = %(smtp)d; smtp.authMethod = Ci.nsMsgAuthMethod.none; smtp.socketType = Ci.nsMsgSocketType.plain;
  const id = MailServices.accounts.createIdentity();
  id.email = "halo@example.invalid"; id.fullName = "Halo Test"; id.smtpServerKey = smtp.key;
  const account = MailServices.accounts.createAccount();
  account.addIdentity(id); account.incomingServer = server;
  return account.key;"""


def server_checks(m, results):
    """Konto mit lokalem Server (tests/testserver.py, nur 127.0.0.1): IMAP-Ordner und Abrufen, Senden über SMTP,
    Fehler beim Senden, Abonnieren-Dialog, falsches Passwort – Oberflächen, die ohne Konto nie erscheinen.
    Läuft am Ende, damit das Konto die übrigen Prüfungen nicht verändert."""
    sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
    from testserver import MailServers
    servers = MailServers()
    servers.imap.add("INBOX", "From: Anna Beispiel <anna@example.invalid>\nTo: Halo Test <halo@example.invalid>\nSubject: Willkommen im Testkonto\n"
                     "Date: Sat, 24 Oct 2026 09:00:00 +0200\nMessage-ID: <srv-1@example.invalid>\n\nErste Mail vom Testserver.\n")
    try:
        key = m.js(SERVER_ACCOUNT_JS % {"imap": servers.imap_port, "smtp": servers.smtp_port})

        def account_folders():
            # Konto erscheint in der Ordnerliste mit seinen Ordnern, die Mail im Posteingang kommt an
            res = m.js(r"""
              const { MailServices } = ChromeUtils.importESModule("resource:///modules/MailServices.sys.mjs");
              const acc = MailServices.accounts.getAccount("%s"), root = acc.incomingServer.rootFolder;
              const a3 = await toMail();
              const inbox = await until(() => root.getFolderWithFlags(Ci.nsMsgFolderFlags.Inbox), 10000);
              a3.displayFolder(inbox.URI);
              await until(() => a3.gDBView?.rowCount > 0, 15000);
              // die übrigen Ordner (LIST) kommen teils erst nach der ersten Mail an – darauf warten statt sofort zu zählen
              await until(() => root.subFolders.some(f => f.name == "Sent"), 15000);
              return { folders: root.subFolders.map(f => f.name).sort(), rows: a3.gDBView?.rowCount || 0,
                       subject: a3.gDBView?.rowCount ? a3.gDBView.getMsgHdrAt(0).mime2DecodedSubject : null,
                       inTree: !!a3.document.querySelector(`#folderTree li[data-server-key="${acc.incomingServer.key}"], #folderTree li[data-folder-uri^="${root.URI}"]`) };""" % key)
            ok = res["rows"] >= 1 and res["subject"] == "Willkommen im Testkonto" and "Sent" in str(res["folders"]) and res["inTree"]
            return ok, f"{res}"
        check("Testkonto: IMAP-Ordner in der Ordnerliste, Mail im Posteingang", account_folders, results)

        def favourites_columns():
            # wie Apple Mail (Maintainer 11.11.2026, Variante A): Symbole von All Inboxes/All Sent bündig über den
            # Ordnersymbolen der Konten; „Favourites“, „Tags“ und die Kontotitel an einer Kante (Maintainer 17.11.2026,
            # „ok dann setzen wir A um“); aufgeklappt stehen die Konten unter All Inboxes ohne eigenes Symbol, ihr
            # Punkt unter dem Text der Zeile darüber. Breite bleibt
            # 206 px, „Local Folders“ darf dort mit „…“ gekürzt erscheinen (Maintainer 15.11.2026); unter Linux ist
            # die Ordnerliste in diesem Fenster nur 160 px breit, die Spalten müssen trotzdem stimmen
            res = m.js(r"""
              const { MailServices } = ChromeUtils.importESModule("resource:///modules/MailServices.sys.mjs");
              const acc = MailServices.accounts.getAccount("%s"), root = acc.incomingServer.rootFolder;
              // „Local Folders“ unter All Inboxes wie im Alltag (mit --only fehlt der Posteingang sonst)
              try { MailServices.accounts.localFoldersServer; } catch { MailServices.accounts.createLocalMailAccount(); }
              const lroot = MailServices.accounts.localFoldersServer.rootFolder;
              if (!lroot.containsChildNamed("Inbox")) { lroot.createSubfolder("Inbox", null); }
              const a3 = await toMail(), ad = a3.document, tree = ad.getElementById("folderTree");
              await until(() => root.getFolderWithFlags(Ci.nsMsgFolderFlags.Inbox), 10000);
              const left0 = ad.getElementById("folderPane").getBoundingClientRect().left;
              const shown = el => !!el && el.getBoundingClientRect().width > 0 && el.getBoundingClientRect().height > 0;
              const x = el => shown(el) ? Math.round(el.getBoundingClientRect().left - left0) : null;
              // Textanfang (nicht die Box): ein Range über den Text
              const tx = el => { if (!shown(el) || !el.firstChild) return null; const r = ad.createRange(); r.selectNodeContents(el);
                                 return Math.round(r.getBoundingClientRect().left - left0); };
              const smart = await until(() => tree.querySelector(':scope > li[data-mode="smart"]'), 8000);
              const fav = smart && [...smart.querySelectorAll(':scope > ul > li[is="folder-tree-row"]')].filter(shown);
              const inboxRow = fav?.find(l => l.dataset.folderType == "inbox");
              const accRow = await until(() => [...tree.querySelectorAll(':scope > li[data-mode="all"] > ul > li[data-server-type="imap"]')].find(shown), 8000);
              await until(() => [...(accRow?.querySelectorAll(':scope > ul > li[is="folder-tree-row"]') || [])].some(shown), 15000);
              const accFolders = [...(accRow?.querySelectorAll(':scope > ul > li[is="folder-tree-row"]') || [])].filter(shown);
              const icon = li => x(li.querySelector(":scope > .container .icon"));
              const name = li => tx(li.querySelector(":scope > .container .name"));
              const out = { favIcons: fav?.map(icon), favText: fav?.map(name), accIcons: [...new Set(accFolders.map(icon))], accText: [...new Set(accFolders.map(name))],
                            header: tx(smart?.querySelector(":scope > .mode-container .mode-name")), accName: name(accRow) };
              // aufgeklappt: Konten unter All Inboxes
              if (inboxRow?.classList.contains("collapsed")) inboxRow.querySelector(":scope > .container .twisty")?.click();
              await until(() => [...inboxRow?.querySelectorAll(":scope > ul > li") || []].some(shown), 4000);
              // Kontopunkte setzt die Erweiterung kurz nach dem Aufklappen
              await until(() => [...(inboxRow?.querySelectorAll(":scope > ul > li") || [])].some(l => l.style.getPropertyValue("--mc-acc")), 3000).catch(() => null);
              const kids = [...(inboxRow?.querySelectorAll(":scope > ul > li[is='folder-tree-row']") || [])].filter(shown);
              out.kidIcons = [...new Set(kids.map(icon))]; out.inboxText = inboxRow ? name(inboxRow) : null;
              // Variante A (Maintainer 17.11.2026): Konten darunter ohne wiederholtes Symbol, Punkt unter dem Text der
              // Zeile darüber, Name 15 px dahinter, auch ohne Punkt („Local Folders“)
              const dotX = li => { const n = li.querySelector(":scope > .container .name"), cs = a3.getComputedStyle(n, "::before");
                                   return cs.content == "none" || !shown(n) ? null : Math.round(n.getBoundingClientRect().left - left0 + parseFloat(cs.marginLeft || 0)); };
              out.kidDots = [...new Set(kids.map(dotX).filter(v => v != null))]; out.kidText = [...new Set(kids.map(name))];
              // alle Abschnittstitel an einer Kante: „Favourites“ und „Tags“ dort, wo der Punkt der Kontotitel sitzt;
              // über jedem Titel außer dem ersten mehr Luft als darunter (Mitte zu Mitte)
              const fp = a3.folderPane, oldModes = fp.activeModes;
              if (!oldModes.includes("tags")) { fp.activeModes = [...oldModes, "tags"]; await ruhig(800); }
              const tagHead = tree.querySelector(':scope > li[data-mode="tags"] > .mode-container .mode-name');
              out.tagHeader = tx(tagHead); out.accDot = dotX(accRow);
              const mid = el => { const r = el.getBoundingClientRect(); return r.top + r.height / 2; };
              const tagC = tagHead?.closest(".mode-container"), tagFirst = tree.querySelector(':scope > li[data-mode="tags"] > ul > li > .container');
              // die sichtbare Zeile direkt darüber (nach Lage, nicht nach DOM: „Local Folders“ steht per order vorn)
              const above = el => { const t = el.getBoundingClientRect().top;
                return [...tree.querySelectorAll('li[is="folder-tree-row"] > .container')].filter(c => shown(c) && c.getBoundingClientRect().bottom <= t + 1)
                  .sort((a, b) => b.getBoundingClientRect().bottom - a.getBoundingClientRect().bottom)[0]; };
              const before = tagC && above(tagC);
              out.tagGap = before && tagFirst ? [Math.round(mid(tagC) - mid(before)), Math.round(mid(tagFirst) - mid(tagC))] : null;
              const accC = accRow.querySelector(":scope > .container"), accPrev = above(accC);
              out.accGap = accPrev ? Math.round(mid(accC) - mid(accPrev)) : null;
              fp.activeModes = oldModes; await ruhig(600);
              // der Aufklapp-Pfeil bleibt links vom Symbol in eigener Spalte (sichtbar beim Überfahren)
              const tw = inboxRow?.querySelector(":scope > .container .twisty .twisty-icon")?.getBoundingClientRect();
              out.twisty = tw && tw.width > 0 ? [Math.round(tw.left - left0), Math.round(tw.right - left0)] : null;
              // je Konto: Name, ganz sichtbar, sonst mit „…“ gekürzt
              out.kidNames = kids.map(l => (n => [n?.textContent, !!n && n.scrollWidth <= n.clientWidth,
                                                  !!n && a3.getComputedStyle(n).textOverflow == "ellipsis"])(l.querySelector(":scope > .container .name")));
              out.pane = Math.round(ad.getElementById("folderPane").getBoundingClientRect().width);
              return out;""" % key)
            fi, ai = res.get("favIcons") or [], res.get("accIcons") or []
            ok = (len(fi) >= 2 and len(ai) == 1 and all(v == ai[0] for v in fi)
                  and len(set(res.get("favText") or [])) == 1 and res.get("favText")[0] == (res.get("accText") or [None])[0]
                  and res.get("header") is not None
                  and res.get("kidIcons") == [None] and len(res.get("kidDots") or []) == 1 and abs(res["kidDots"][0] - res["inboxText"]) <= 1
                  and len(res.get("kidText") or []) == 1 and res["kidText"][0] - res["kidDots"][0] == 15
                  and res.get("accDot") is not None and abs(res["header"] - res["accDot"]) <= 1 and res.get("tagHeader") == res["header"]
                  and res.get("tagGap") and res["tagGap"][0] > res["tagGap"][1] and res.get("accGap") == res["tagGap"][0]
                  and res.get("twisty") and res["twisty"][0] >= 0 and res["twisty"][1] <= fi[0]
                  # „Local Folders“ da, ganz oder mit „…“ gekürzt (Maintainer 15.11.2026)
                  and any(n == "Local Folders" and (fits or dots) for n, fits, dots in res.get("kidNames") or []))
            return ok, f"{res}"
        check("Ordnerliste: Favoriten-Symbole bündig mit den Spalten der Konten, „Favourites“, „Tags“ und Kontotitel an einer Kante mit mehr Luft darüber, Konten unter All Inboxes ohne Symbol mit Punkt unter dem Text darüber", favourites_columns, results)

        def favourites_collapse():
            # Abschnittstitel einklappbar wie die Konten (Maintainer 17.11.2026, „Bezüglich 1 und 2 folge ich deiner
            # Empfehlung“): Pfeil an derselben Stelle wie bei den Kontotiteln, Klick klappt „Favourites“ zu (Zeilen weg,
            # Pfeiltasten überspringen sie, Zustand gemerkt) und wieder auf; in „Kompakt“ stehen Titel und Kontopunkt
            # weiter an einer Kante, über dem Titel 8 px Luft (Titelzeile 20 px), Mitte zu Mitte wie über den Kontotiteln
            res = m.js(r"""
              const a3 = await toMail(), ad = a3.document, tree = ad.getElementById("folderTree"), PREF = "extensions.mailcards.collapsedFolderModes";
              const left0 = ad.getElementById("folderPane").getBoundingClientRect().left;
              const shown = el => !!el && el.getBoundingClientRect().width > 0 && el.getBoundingClientRect().height > 0;
              const X = el => shown(el) ? Math.round(el.getBoundingClientRect().left - left0) : null;
              const mid = el => { const r = el.getBoundingClientRect(); return r.top + r.height / 2; };
              const smart = await until(() => tree.querySelector(':scope > li[data-mode="smart"]'), 8000);
              const head = smart.querySelector(":scope > .mode-container"), tw = head.querySelector(":scope > .twisty");
              const accRow = [...tree.querySelectorAll(':scope > li[data-mode="all"] > ul > li[data-server-type="imap"]')].find(shown);
              const out = { tw: X(tw), accTw: X(accRow?.querySelector(":scope > .container .twisty")), pref0: Services.prefs.getStringPref(PREF, "") };
              const favRows = () => [...smart.querySelectorAll(':scope > ul > li[is="folder-tree-row"]')].filter(shown).length;
              out.rows0 = favRows();
              // zu: Klick auf den Pfeil
              const sel = tree.selectedRow;
              tw.click(); await ruhig(400);
              out.closed = { rows: favRows(), attr: smart.hasAttribute("mc-collapsed"), pref: Services.prefs.getStringPref(PREF, ""),
                             rot: getComputedStyle(tw.querySelector(".twisty-icon")).transform,
                             // Pfeiltasten: keine Zeile der eingeklappten Favoriten (außer einer schon gewählten)
                             inRows: tree.rows.filter(r => smart.contains(r) && r != sel).length,
                             // der nächste Titel (oberstes Konto, auch „On My Mac“) rückt direkt unter „Favourites“
                             accMid: Math.round(Math.min(...[...tree.querySelectorAll(':scope > li[data-mode="all"] > ul > li[data-server-type] > .container')]
                                                              .filter(shown).map(mid)) - mid(head)) };
              // auf: Klick auf den Titel selbst
              head.querySelector(".mode-name").click(); await ruhig(400);
              out.open = { rows: favRows(), attr: smart.hasAttribute("mc-collapsed"), pref: Services.prefs.getStringPref(PREF, "") };
              // Kompakt
              const dens = Services.prefs.getIntPref("mail.uidensity", 1);
              Services.prefs.setIntPref("mail.uidensity", 0); await ruhig(800);
              const tx = el => { const r = ad.createRange(); r.selectNodeContents(el); return Math.round(r.getBoundingClientRect().left - left0); };
              const nm = accRow.querySelector(":scope > .container .name");
              const above = el => { const t = el.getBoundingClientRect().top;
                return [...tree.querySelectorAll('li[is="folder-tree-row"] > .container')].filter(c => shown(c) && c.getBoundingClientRect().bottom <= t + 1)
                  .sort((a, b) => b.getBoundingClientRect().bottom - a.getBoundingClientRect().bottom)[0]; };
              const accC = accRow.querySelector(":scope > .container");
              out.compact = { head: tx(head.querySelector(".mode-name")), dot: Math.round(nm.getBoundingClientRect().left - left0), h: Math.round(head.getBoundingClientRect().height),
                              tw: X(tw), accTw: X(accRow.querySelector(":scope > .container .twisty")),
                              accGap: above(accC) ? Math.round(mid(accC) - mid(above(accC))) : null };
              Services.prefs.setIntPref("mail.uidensity", dens); await ruhig(800);
              return out;""")
            c, o, k = res.get("closed") or {}, res.get("open") or {}, res.get("compact") or {}
            ok = (res.get("tw") is not None and abs(res["tw"] - (res.get("accTw") or -99)) <= 1 and res.get("rows0", 0) >= 2
                  and c.get("rows") == 0 and c.get("attr") and c.get("pref") == "smart" and "matrix" in (c.get("rot") or "") and c.get("inRows") == 0
                  and 28 <= (c.get("accMid") or 0) <= 40
                  and o.get("rows") == res["rows0"] and o.get("attr") is False and o.get("pref") == ""
                  and k.get("head") is not None and abs(k["head"] - k.get("dot", -99)) <= 1 and k.get("h") == 20
                  and k.get("tw") is not None and abs(k["tw"] - (k.get("accTw") or -99)) <= 1 and k.get("accGap") == 30)
            return ok, f"{res}"
        check("Ordnerliste: „Favourites“ einklappbar wie die Konten (Pfeil an derselben Stelle, Zustand gemerkt), in „Kompakt“ Titel und Kontopunkt an einer Kante mit 8 px Luft über dem Titel", favourites_collapse, results)

        def sidebar_fonts():
            # Seitenleisten aus einem Guss (Variante A, Maintainer 16.11.2026): Zeilen 13 px, die gewählte Zeile halbfett (600)
            # in Mail (Ordnerliste), Kalender (Kalenderliste), Aufgaben (Filter) und Adressbuch, die übrigen normal; ein
            # gewählter Ordner bleibt halbfett, auch wenn er ungelesen ist oder neue Mails hat, ein nicht gewählter ungelesener
            # Ordner bleibt normal (Chat: Prüfung „Testkonto: Chat mit Testserver“)
            res = m.js(r"""
              const { MailServices } = ChromeUtils.importESModule("resource:///modules/MailServices.sys.mjs");
              const acc = MailServices.accounts.getAccount("%s"), root = acc.incomingServer.rootFolder;
              const f = e => e ? [e.ownerDocument.defaultView.getComputedStyle(e).fontSize, e.ownerDocument.defaultView.getComputedStyle(e).fontWeight] : null;
              const out = {};
              const a3 = await toMail(), tree = a3.document.getElementById("folderTree");
              const inbox = await until(() => root.getFolderWithFlags(Ci.nsMsgFolderFlags.Inbox), 10000);
              const rows = await until(() => (r => r.some(l => l.uri == inbox.URI) && r)([...tree.querySelectorAll(':scope > li[data-mode="all"] li[is="folder-tree-row"]')]
                .filter(l => l.getBoundingClientRect().height)), 8000) || [];
              const target = rows.find(l => l.uri == inbox.URI);
              if (target) { target.querySelector(":scope > .container").click(); await until(() => target.classList.contains("selected"), 4000); await ruhig(300); }
              const sel = rows.find(l => l.classList.contains("selected") && l.uri == inbox.URI), other = rows.find(l => !l.classList.contains("selected") && !l.dataset.serverType);
              const nm = l => l?.querySelector(":scope > .container > .name");
              out.mail = { sel: f(nm(sel)), other: f(nm(other)) };
              if (sel && other) {
                const had = [sel.classList.contains("unread"), other.classList.contains("unread")];
                sel.classList.add("unread", "new-messages"); other.classList.add("unread", "new-messages"); await ruhig(100);
                out.mail.selUnread = f(nm(sel)); out.mail.otherUnread = f(nm(other));
                sel.classList.remove("new-messages"); other.classList.remove("new-messages");
                if (!had[0]) sel.classList.remove("unread"); if (!had[1]) other.classList.remove("unread");
              }
              const go = async id => { d.getElementById(id).click(); await until(() => d.getElementById(id).classList.contains("current"), 8000); await ruhig(800); };
              await go("calendarButton");
              out.cal = { sel: f(await until(() => d.querySelector("#calendar-list > li.selected .calendar-name"), 4000)),
                          other: f(d.querySelector("#calendar-list > li:not(.selected) .calendar-name")) };
              await go("tasksButton");
              out.tasks = { sel: f(await until(() => d.querySelector("#mcTaskLists .mc-tl-row.selected .mc-tl-name"), 4000)),
                            other: f(d.querySelector("#mcTaskLists .mc-tl-row:not(.selected) .mc-tl-name")) };
              await go("addressBookButton");
              const ab = await until(() => tm.currentTabInfo.browser?.contentDocument?.querySelector("#books .bookRow.selected .bookRow-name") && tm.currentTabInfo.browser.contentDocument, 6000);
              out.ab = { sel: f(ab?.querySelector("#books .bookRow.selected .bookRow-name")), other: f(ab?.querySelector("#books .bookRow:not(.selected) .bookRow-name")) };
              await toMail();
              for (const t of [...tm.tabInfo].slice(1)) tm.closeTab(t);
              return out;""" % key)
            want_sel, want_other = ["13px", "600"], ["13px", "400"]
            ok = all((res.get(k) or {}).get("sel") == want_sel and (res.get(k) or {}).get("other") == want_other for k in ("mail", "cal", "tasks", "ab"))
            ok = ok and res["mail"].get("selUnread") == want_sel and res["mail"].get("otherUnread") == want_other
            return ok, f"{res}"
        check("Seitenleisten: Zeilen 13 px, gewählter Eintrag halbfett in Mail, Kalender, Aufgaben und Adressbuch, übrige und ungelesene normal", sidebar_fonts, results)

        def local_hidden():
            # wie Apple Mail: „On My Mac“ ganz ausgeblendet, solange die lokalen Ordner leer sind (es gibt ein anderes Konto);
            # liegt dort etwas, ist es wieder da
            res = m.js(r"""
              const { MailServices } = ChromeUtils.importESModule("resource:///modules/MailServices.sys.mjs");
              const a3 = await toMail(), tree = a3.document.getElementById("folderTree");
              const row = () => tree.querySelector(':scope > li[data-mode="all"] > ul > li[data-server-type="none"]');
              const vis = () => { const r = row(); return !!r && r.getBoundingClientRect().height > 0; };
              const local = MailServices.accounts.localFoldersServer.rootFolder;
              // leer zählt wie in der Erweiterung: nur leere Ordner ohne Unterordner (das Testprofil hat hier schon Mails)
              const empty = () => local.subFolders.every(f => f.getFlag(Ci.nsMsgFolderFlags.Virtual) || (!f.hasSubFolders && f.getTotalMessages(false) == 0));
              const out = { empty: empty(), before: vis() };
              local.createSubfolder("Halo Sichtbar", null);
              const f = await until(() => local.getChildNamed?.("Halo Sichtbar"), 3000);
              f?.createSubfolder("Unter", null);
              await ruhig(1500); out.withFolder = vis();
              // wie Apple Mail: Papierkorb und Postausgang darunter nur, solange darin etwas liegt
              const rowOf = fo => fo && [...tree.querySelectorAll(':scope > li[data-mode="all"] li[is="folder-tree-row"]')].find(l => l.uri == fo.URI);
              const shownRow = fo => { const r = rowOf(fo); return !!r && r.getBoundingClientRect().height > 0; };
              const trash = local.getFolderWithFlags(Ci.nsMsgFolderFlags.Trash), outbox = local.getFolderWithFlags(Ci.nsMsgFolderFlags.Queue);
              const expect = fo => !!fo && (fo.hasSubFolders || fo.getTotalMessages(false) > 0);
              out.special = { trash: [shownRow(trash), expect(trash)], outbox: [shownRow(outbox), expect(outbox)] };
              if (trash && !trash.getTotalMessages(false)) {
                trash.QueryInterface(Ci.nsIMsgLocalMailFolder).addMessage("From - Thu Nov 05 10:00:00 2026\r\nFrom: Anna Beispiel <anna@example.invalid>\r\nSubject: Halo Papierkorb\r\nDate: Thu, 05 Nov 2026 10:00:00 +0100\r\nMessage-ID: <halo-trash@example.invalid>\r\n\r\nweg\r\n");
                await bis(() => shownRow(trash), "Papierkorb mit Mail sichtbar", 4000).catch(() => {});
                out.trashFull = shownRow(trash);
                trash.emptyTrash(null);
                await bis(() => !shownRow(trash), "leerer Papierkorb ausgeblendet", 4000).catch(() => {});
                out.trashEmptied = shownRow(trash);
              }
              // wie Apple Mail ohne Wahl (Option entfernt 17.11.2026): mit Inhalt immer da – das Kontextmenü der Zeile bietet
              // kein Ausblenden, ein alter Wert der früheren Einstellung (beim Start gelöscht) bliebe wirkungslos
              local.createSubfolder("Halo Sichtbar2", null); const f2 = await until(() => local.getChildNamed?.("Halo Sichtbar2"), 3000); f2?.createSubfolder("Unter", null);
              await ruhig(1000);
              const popup = a3.document.getElementById("folderPaneContext");
              const shown = new Promise(r => popup.addEventListener("popupshown", r, { once: true }));
              row()?.querySelector(".container")?.dispatchEvent(new a3.MouseEvent("contextmenu", { bubbles: true, button: 2, clientX: 20, clientY: 10 }));
              out.menuOpened = await Promise.race([shown.then(() => true), wait(3000).then(() => false)]);
              out.hideItem = !!a3.document.getElementById("mcFolderHideLocal");
              popup.hidePopup();
              out.startPref = Services.prefs.prefHasUserValue("extensions.mailcards.showLocalFolders");
              Services.prefs.setBoolPref("extensions.mailcards.showLocalFolders", false);
              // neuer Unterordner: die Ordnerliste wird neu beschriftet (mit dem alten Wert, falls er noch zählte)
              local.createSubfolder("Halo Sichtbar3", null); const f3 = await until(() => local.getChildNamed?.("Halo Sichtbar3"), 3000);
              await ruhig(1200);
              out.oldPref = vis();
              try { f3 && local.propagateDelete(f3, true); } catch {}
              Services.prefs.clearUserPref("extensions.mailcards.showLocalFolders");
              try { f && local.propagateDelete(f, true); } catch {}
              try { f2 && local.propagateDelete(f2, true); } catch {}
              await ruhig(1500); out.after = vis();
              out.emptyAfter = empty();
              return out;""")
            sp = res.get("special") or {}
            ok = (res.get("before") is not res.get("empty") and res.get("withFolder") is True and res.get("after") is not res.get("emptyAfter")
                  and all(v and v[0] == v[1] for v in sp.values()) and res.get("trashFull", True) is True and res.get("trashEmptied", False) is False
                  and res.get("menuOpened") is True and res.get("hideItem") is False and res.get("startPref") is False
                  and res.get("oldPref") is True)
            return ok, f"{res}"
        check("Ordnerliste: „On My Mac“ ganz ausgeblendet, solange die lokalen Ordner leer sind, Papierkorb und Postausgang darin nur mit Inhalt; "
              "mit Inhalt immer da wie Apple Mail (kein Ausblenden im Kontextmenü, alte Einstellung wirkungslos)", local_hidden, results)

        def get_new():
            # neue Mail auf dem Server → „Abrufen“ in der Toolbar holt sie; das Menü am Knopf ist im halo-Stil
            servers.imap.add("INBOX", "From: Ben <ben@example.invalid>\nTo: Halo Test <halo@example.invalid>\nSubject: Nachzuegler\n"
                             "Date: Sat, 24 Oct 2026 10:00:00 +0200\nMessage-ID: <srv-2@example.invalid>\n\nZweite Mail.\n")
            res = m.js(r"""
              const a3 = await toMail();
              const li = [...d.querySelectorAll('#unifiedToolbarContent li[item-id="get-messages"]')].find(l => l.getBoundingClientRect().width);
              const btn = li?.querySelector("button");
              btn?.click();
              const found = await until(() => { for (let i = 0; i < (a3.gDBView?.rowCount || 0); i++) if (a3.gDBView.getMsgHdrAt(i).mime2DecodedSubject == "Nachzuegler") return true; return false; }, 15000);
              const { getState } = ChromeUtils.importESModule("resource:///modules/CustomizationState.mjs");
              return { button: !!btn, found, folder: a3.gFolder?.URI, rows: a3.gDBView?.rowCount, toolbar: btn ? null : getState().mail,
                       items: btn ? null : [...d.querySelectorAll('#unifiedToolbarContent li')].map(l => l.getAttribute("item-id") + ":" + Math.round(l.getBoundingClientRect().width)) };""")
            return res["button"] and res["found"], f"{res} IMAP: {servers.imap.log[-8:]}"
        check("Testkonto: „Abrufen“ holt neue Mail vom Server", get_new, results)

        def send_smtp():
            # Verfassen und Senden: Fenster schließt sofort, die Mail kommt beim SMTP-Server an
            before = len(servers.smtp.sent)
            res = m.js(r"""
              const { MailServices } = ChromeUtils.importESModule("resource:///modules/MailServices.sys.mjs");
              const acc = MailServices.accounts.getAccount("%s");
              const params = Cc["@mozilla.org/messengercompose/composeparams;1"].createInstance(Ci.nsIMsgComposeParams);
              const fields = Cc["@mozilla.org/messengercompose/composefields;1"].createInstance(Ci.nsIMsgCompFields);
              Services.prefs.setIntPref("extensions.mailcards.undoSend", 0);
              fields.to = "ziel@example.invalid"; fields.subject = "Halo Sendeprobe"; fields.body = "Hallo vom Test.";
              params.type = Ci.nsIMsgCompType.New; params.format = Ci.nsIMsgCompFormat.PlainText; params.composeFields = fields; params.identity = acc.defaultIdentity;
              MailServices.compose.OpenComposeWindowWithParams(null, params);
              const cw = await until(() => [...Services.wm.getEnumerator("msgcompose")].find(x => x.document.readyState == "complete" && x.gMsgCompose), 10000);
              await bis(() => cw.gLoadingComplete, "Verfassen-Fenster fertig geladen", 8000); await ruhig(1500);
              cw.goDoCommand("cmd_sendNow");
              const closed = await until(() => cw.closed, 10000);
              return { closed: !!closed };""" % key)
            for _ in range(40):
                if len(servers.smtp.sent) > before:
                    break
                time.sleep(0.5)
            got = servers.smtp.sent[before:] if len(servers.smtp.sent) > before else []
            ok = res["closed"] and len(got) == 1 and "Halo Sendeprobe" in got[0][2] and "ziel@example.invalid" in got[0][1][0]
            return ok, f"{res} gesendet: {[(g[0], g[1]) for g in got]}"
        check("Testkonto: Senden über SMTP – Fenster schließt, Mail kommt beim Server an", send_smtp, results)

        def undo_send():
            # Senden rückgängig: Fenster verschwindet sofort, unten „Senden rückgängig“, nichts geht hinaus; rückgängig →
            # Fenster wieder da; erneut senden → nach der Wartezeit beim Server, Fenster zu (Wartezeit hier 2 s)
            before = len(servers.smtp.sent)
            res = m.js(r"""
              const { MailServices } = ChromeUtils.importESModule("resource:///modules/MailServices.sys.mjs");
              const acc = MailServices.accounts.getAccount("%s");
              Services.prefs.setIntPref("extensions.mailcards.undoSend", 6);
              const params = Cc["@mozilla.org/messengercompose/composeparams;1"].createInstance(Ci.nsIMsgComposeParams);
              const fields = Cc["@mozilla.org/messengercompose/composefields;1"].createInstance(Ci.nsIMsgCompFields);
              fields.to = "ziel@example.invalid"; fields.subject = "Halo Rueckholprobe"; fields.body = "Noch nicht senden.";
              params.type = Ci.nsIMsgCompType.New; params.format = Ci.nsIMsgCompFormat.PlainText; params.composeFields = fields; params.identity = acc.defaultIdentity;
              MailServices.compose.OpenComposeWindowWithParams(null, params);
              const cw = await until(() => [...Services.wm.getEnumerator("msgcompose")].find(x => x.document.readyState == "complete" && x.gMsgCompose), 10000);
              await bis(() => cw.gLoadingComplete, "Verfassen-Fenster fertig geladen", 8000); await ruhig(1500);
              const visible = () => !cw.document.hidden;
              const out = { types: [], errs: [] };
              cw.addEventListener("compose-send-message", e => out.types.push([e.detail?.msgType, e.defaultPrevented]), false);
              const cl = { observe: m => { if (m instanceof Ci.nsIScriptError && m.flags == 0) out.errs.push(m.errorMessage.slice(0, 160)); } };
              Services.console.registerListener(cl);
              cw.goDoCommand("cmd_sendNow");
              const bar = await until(() => d.getElementById("mcUndoSend"), 4000);
              // (Windows und Linux ohne Fenstermanager melden das versteckte Fenster nicht – nur kurz warten)
              await until(() => cw.document.hidden, 1200);
              out.held = { visible: visible(), closed: cw.closed, bar: bar?.textContent };
              Services.console.unregisterListener(cl); out.errs = out.errs.filter(e => !/editorContent|security/i.test(e)).slice(0, 6);
              bar?.querySelector(".mc-us-undo").click(); await until(() => !cw.document.hidden, 2000);
              out.undone = { visible: visible(), closed: cw.closed, bar: !!d.getElementById("mcUndoSend") };
              w.__mcUndoWin = cw;
              return out;""" % key)
            time.sleep(7)
            after_undo = len(servers.smtp.sent) - before
            res2 = m.js(r"""
              const cw = w.__mcUndoWin; delete w.__mcUndoWin;
              cw.goDoCommand("cmd_sendNow");
              const closed = await until(() => cw.closed, 20000);
              Services.prefs.clearUserPref("extensions.mailcards.undoSend");
              return { closed: !!closed, bar: !!d.getElementById("mcUndoSend") };""")
            for _ in range(20):
                if len(servers.smtp.sent) > before:
                    break
                time.sleep(0.5)
            got = [g for g in servers.smtp.sent[before:] if "Halo Rueckholprobe" in g[2]]
            h, u = res.get("held") or {}, res.get("undone") or {}
            ok = ((h.get("visible") is False or sys.platform != "darwin") and not h.get("closed") and "Undo Send" in (h.get("bar") or "")
                  and u == {"visible": True, "closed": False, "bar": False} and after_undo == 0
                  and res2["closed"] and not res2["bar"] and len(got) == 1)
            return ok, f"{res} nach Rückgängig gesendet: {after_undo} {res2} danach gesendet: {len(got)}"
        check("Testkonto: Senden rückgängig – Fenster weg, Hinweis unten, rückgängig holt es zurück, danach gesendet", undo_send, results)

        def send_later():
            # Später senden: Pfeil neben „Senden“ mit „Morgen …“ und „Später senden …“; geplante Mail liegt als Entwurf mit
            # X-Halo-Send-At, wird zur Zeit in den Postausgang geschoben und gesendet (Zeit hier: in 3 s)
            before = len(servers.smtp.sent)
            res = m.js(r"""
              const { MailServices } = ChromeUtils.importESModule("resource:///modules/MailServices.sys.mjs");
              const { ExtensionParent } = ChromeUtils.importESModule("resource://gre/modules/ExtensionParent.sys.mjs");
              const g = ExtensionParent.GlobalManager.getExtension("%s").experimentAPIManager.global;
              const SL = Cu.evalInSandbox("SendLater", g);
              const acc = MailServices.accounts.getAccount("%s");
              Services.prefs.setIntPref("extensions.mailcards.undoSend", 0);
              const params = Cc["@mozilla.org/messengercompose/composeparams;1"].createInstance(Ci.nsIMsgComposeParams);
              const fields = Cc["@mozilla.org/messengercompose/composefields;1"].createInstance(Ci.nsIMsgCompFields);
              fields.to = "ziel@example.invalid"; fields.subject = "Halo Spaeter"; fields.body = "Kommt gleich.";
              params.type = Ci.nsIMsgCompType.New; params.format = Ci.nsIMsgCompFormat.PlainText; params.composeFields = fields; params.identity = acc.defaultIdentity;
              MailServices.compose.OpenComposeWindowWithParams(null, params);
              const cw = await until(() => [...Services.wm.getEnumerator("msgcompose")].find(x => x.document.readyState == "complete" && x.gMsgCompose), 10000);
              await bis(() => cw.gLoadingComplete, "Verfassen-Fenster fertig geladen", 8000); await ruhig(1500);
              const btn = cw.document.getElementById("mcSendLater"), popup = cw.document.getElementById("mcSendLaterPopup");
              const out = { button: !!btn && btn.getBoundingClientRect().width > 0 };
              popup.dispatchEvent(new cw.Event("popupshowing"));
              out.menu = [...popup.querySelectorAll("menuitem")].map(i => i.getAttribute("label"));
              SL.schedule(cw, new Date(Date.now() + 3000));
              out.closed = !!(await until(() => cw.closed, 10000));
              // ESR 153 kennt getOrCreateDraftsFolderAsync noch nicht (wie SendLater.draftFolders)
              const ident = acc.defaultIdentity;
              const drafts = typeof ident.getOrCreateDraftsFolderAsync == "function" ? await ident.getOrCreateDraftsFolderAsync()
                : MailServices.folderLookup.getFolderForURL(ident.draftsFolderURI) || acc.incomingServer.rootFolder.getFolderWithFlags(Ci.nsMsgFolderFlags.Drafts);
              out.draftsFolder = drafts?.prettyName;
              await ruhig(500);
              let found = null;
              for (let t = 0; t < 30 && !found; t++) { try { drafts.updateFolder(null); } catch {}; await wait(300);
                found = [...drafts.msgDatabase.enumerateMessages()].find(h => h.mime2DecodedSubject == "Halo Spaeter"); }
              out.draft = found ? { at: !!Number(found.getStringProperty("x-halo-send-at")) } : null;
              await wait(3500);
              await SL.check(true);
              Services.prefs.clearUserPref("extensions.mailcards.undoSend");
              return out;""" % (ADDON_ID, key))
            for _ in range(40):
                if any("Halo Spaeter" in g[2] for g in servers.smtp.sent[before:]):
                    break
                time.sleep(0.5)
            got = [g for g in servers.smtp.sent[before:] if "Halo Spaeter" in g[2]]
            # die interne Kopfzeile darf nicht an die Empfänger gehen (Thunderbirds Postausgang entfernt sie nicht)
            leak = [g for g in got if "x-halo-send-at" in g[2].lower()]
            ok = (res.get("button") and len(res.get("menu", [])) >= 3 and res["menu"][0] == "Send Now" and res["menu"][-1] == "Send Later …"
                  and res.get("closed") and res.get("draft") == {"at": True} and len(got) == 1 and not leak
                  and "Kommt gleich." in got[0][2])
            return ok, f"{res} gesendet: {len(got)} mit X-Halo-Send-At: {len(leak)}"
        check("Testkonto: Später senden – Menü am Senden-Knopf, geplante Mail als Entwurf, zur Zeit gesendet ohne interne Kopfzeile", send_later, results)

        def outbox_held():
            # Thunderbirds „Später senden“ (Datei-Menü, Postausgang) hält die Mail zurück; halo.spaces sendet im Hintergrund
            # über den Postausgang und leerte ihn dabei ganz – die zurückgehaltene Mail ging mit der nächsten gesendeten
            # Mail hinaus. Jetzt geht nur die neue Mail, die zurückgehaltene bleibt, bis man den Postausgang selbst sendet
            before = len(servers.smtp.sent)
            compose = r"""
              const { MailServices } = ChromeUtils.importESModule("resource:///modules/MailServices.sys.mjs");
              const acc = MailServices.accounts.getAccount("%s");
              Services.prefs.setIntPref("extensions.mailcards.undoSend", 0);
              const params = Cc["@mozilla.org/messengercompose/composeparams;1"].createInstance(Ci.nsIMsgComposeParams);
              const fields = Cc["@mozilla.org/messengercompose/composefields;1"].createInstance(Ci.nsIMsgCompFields);
              fields.to = "ziel@example.invalid"; fields.subject = "%s"; fields.body = "Probe.";
              params.type = Ci.nsIMsgCompType.New; params.format = Ci.nsIMsgCompFormat.PlainText; params.composeFields = fields; params.identity = acc.defaultIdentity;
              MailServices.compose.OpenComposeWindowWithParams(null, params);
              const cw = await until(() => [...Services.wm.getEnumerator("msgcompose")].find(x => x.document.readyState == "complete" && x.gMsgCompose), 10000);
              await bis(() => cw.gLoadingComplete, "Verfassen-Fenster fertig geladen", 8000); await ruhig(1500);
              cw.goDoCommand("%s");
              const closed = !!(await until(() => cw.closed, 15000));
              const outbox = MailServices.accounts.localFoldersServer.rootFolder.getFolderWithFlags(Ci.nsMsgFolderFlags.Queue);
              const subjects = outbox ? [...outbox.msgDatabase.enumerateMessages()].map(h => h.mime2DecodedSubject) : [];
              return { closed, outbox: subjects };"""
            sent = lambda s: [g for g in servers.smtp.sent[before:] if s in g[2]]
            try:
                held = m.js(compose % (key, "Halo Zurueckgehalten", "cmd_sendLater"))
                # Thunderbird sendet einen neu im Postausgang abgelegten Brief im Hintergrund nach rund 1 s, halo.spaces
                # nach 2 s – 6 s ohne Senden belegen, dass die Mail liegen bleibt (feste Wartezeit: es soll nichts geschehen)
                time.sleep(6)
                held_sent = len(sent("Halo Zurueckgehalten"))
                now = m.js(compose % (key, "Halo Sofortprobe", "cmd_sendButton"))
                for _ in range(40):
                    if sent("Halo Sofortprobe"):
                        break
                    time.sleep(0.5)
                time.sleep(6)  # wie oben: halo.spaces leerte den Postausgang 2 s nach dem Senden
                after = m.js(r"""
                  const { MailServices } = ChromeUtils.importESModule("resource:///modules/MailServices.sys.mjs");
                  const outbox = MailServices.accounts.localFoldersServer.rootFolder.getFolderWithFlags(Ci.nsMsgFolderFlags.Queue);
                  return outbox ? [...outbox.msgDatabase.enumerateMessages()].map(h => h.mime2DecodedSubject) : [];""")
                held_after = len(sent("Halo Zurueckgehalten"))
                # „Nicht gesendete Nachrichten senden“ (vom Nutzer ausgelöst) schickt die zurückgehaltene Mail dann hinaus
                m.js('Services.wm.getMostRecentWindow("mail:3pane").SendUnsentMessages(); return 1;')
                for _ in range(40):
                    if sent("Halo Zurueckgehalten"):
                        break
                    time.sleep(0.5)
            finally:
                m.js(r"""
                  const { MailServices } = ChromeUtils.importESModule("resource:///modules/MailServices.sys.mjs");
                  Services.prefs.clearUserPref("extensions.mailcards.undoSend");
                  for (const x of [...Services.wm.getEnumerator("msgcompose")]) x.close();
                  const outbox = MailServices.accounts.localFoldersServer.rootFolder.getFolderWithFlags(Ci.nsMsgFolderFlags.Queue);
                  const hdrs = outbox ? [...outbox.msgDatabase.enumerateMessages()] : [];
                  if (hdrs.length) outbox.deleteMessages(hdrs, null, true, false, null, false);
                  return 1;""")
            ok = (held.get("closed") and "Halo Zurueckgehalten" in held.get("outbox", []) and held_sent == 0
                  and now.get("closed") and len(sent("Halo Sofortprobe")) == 1 and held_after == 0
                  and after == ["Halo Zurueckgehalten"] and len(sent("Halo Zurueckgehalten")) == 1)
            return ok, (f"zurückgehalten {held} gesendet {held_sent}; danach Senden {now} beim Server: Sofortprobe "
                        f"{len(sent('Halo Sofortprobe'))}, Zurueckgehalten {held_after}; Postausgang danach {after}; nach „Send Unsent“ gesendet {len(sent('Halo Zurueckgehalten'))}")
        check("Testkonto: mit „Später senden“ im Postausgang zurückgehaltene Mail bleibt liegen, wenn danach eine andere Mail gesendet wird, und geht erst mit „Send Unsent Messages“", outbox_held, results)

        def send_later_place():
            # „Später senden“ als kleiner Pfeil gleich rechts neben dem runden Senden-Knopf (war eine leere Kapsel links)
            res = m.js(r"""
              const { MailServices } = ChromeUtils.importESModule("resource:///modules/MailServices.sys.mjs");
              const acc = MailServices.accounts.getAccount("%s");
              const params = Cc["@mozilla.org/messengercompose/composeparams;1"].createInstance(Ci.nsIMsgComposeParams);
              const fields = Cc["@mozilla.org/messengercompose/composefields;1"].createInstance(Ci.nsIMsgCompFields);
              fields.to = "ziel@example.invalid"; fields.subject = "Halo Pfeilprobe";
              params.type = Ci.nsIMsgCompType.New; params.format = Ci.nsIMsgCompFormat.HTML; params.composeFields = fields; params.identity = acc.defaultIdentity;
              MailServices.compose.OpenComposeWindowWithParams(null, params);
              const cw = await until(() => [...Services.wm.getEnumerator("msgcompose")].find(x => x.document.readyState == "complete" && x.gMsgCompose), 10000);
              await bis(() => cw.gLoadingComplete, "Verfassen-Fenster fertig geladen", 8000); await ruhig(1500);
              const r = id => { const b = cw.document.getElementById(id)?.getBoundingClientRect(); return b ? { l: Math.round(b.left), r: Math.round(b.right), w: Math.round(b.width), t: Math.round(b.top), b: Math.round(b.bottom) } : null; };
              const later = cw.document.getElementById("mcSendLater");
              const out = { send: r("button-send"), later: r("mcSendLater"), mask: later ? cw.getComputedStyle(later).maskImage.includes("resource://mailcards/icons/send-later.svg") : false, win: cw.innerWidth };
              cw.gMsgCompose.compFields.subject = ""; cw.close(); await ruhig(500);
              for (const x of [...Services.wm.getEnumerator("msgcompose")]) x.close();
              return out;""" % key)
            sd, lt = res.get("send") or {}, res.get("later") or {}
            ok = (sd and lt and res.get("mask") and 0 <= lt["l"] - sd["r"] <= 6 and lt["w"] <= 20 and res["win"] - lt["r"] <= 20
                  and abs((lt["t"] + lt["b"]) - (sd["t"] + sd["b"])) <= 2)
            return ok, f"{res}"
        check("Verfassen: „Später senden“ als kleiner Pfeil direkt rechts neben dem Senden-Knopf", send_later_place, results)

        def remind_me():
            # Erinnern: Kontextmenü „Remind Me“ mit Zeiten; die Mail wandert in den Ordner „Remind Me“ des Kontos und kommt
            # zur Zeit ungelesen in den Posteingang zurück (Zeit hier: in 2 s)
            servers.imap.add("INBOX", "From: Clara <clara@example.invalid>\nTo: Halo Test <halo@example.invalid>\nSubject: Bitte morgen ansehen\n"
                             "Date: Sat, 24 Oct 2026 11:00:00 +0200\nMessage-ID: <srv-remind@example.invalid>\n\nErinnerungsprobe.\n", flags=["\\Seen"])
            res = m.js(r"""
              const { MailServices } = ChromeUtils.importESModule("resource:///modules/MailServices.sys.mjs");
              const { ExtensionParent } = ChromeUtils.importESModule("resource://gre/modules/ExtensionParent.sys.mjs");
              const g = ExtensionParent.GlobalManager.getExtension("%s").experimentAPIManager.global;
              const R = Cu.evalInSandbox("Remind", g);
              const acc = MailServices.accounts.getAccount("%s"), root = acc.incomingServer.rootFolder;
              const inbox = root.getFolderWithFlags(Ci.nsMsgFolderFlags.Inbox);
              const a3 = await toMail(); a3.displayFolder(inbox.URI);
              const find = () => { for (let i = 0; i < (a3.gDBView?.rowCount || 0); i++) if (a3.gDBView.getMsgHdrAt(i).mime2DecodedSubject == "Bitte morgen ansehen") return i; return -1; };
              await until(() => { inbox.updateFolder(a3.msgWindow); return find() >= 0; }, 15000);
              a3.threadTree.selectedIndex = find(); await ruhig(800);
              const popup = a3.document.getElementById("mailContext");
              popup.dispatchEvent(new a3.Event("popupshowing"));
              const menu = a3.document.getElementById("mcRemindMenu");
              const out = { menu: !!menu && !menu.hidden };
              const inner = menu?.menupopup || menu?.querySelector("menupopup");
              inner?.dispatchEvent(new a3.Event("popupshowing"));
              out.items = inner ? inner.querySelectorAll("menuitem").length : 0;
              const hdr = a3.gDBView.getMsgHdrAt(find());
              await R.remind([hdr], new Date(Date.now() + 2000));
              const box = await until(() => root.containsChildNamed("Remind Me") && root.getChildNamed("Remind Me"), 8000);
              out.moved = !!(await until(() => { try { box.updateFolder(null); } catch {} return box?.msgDatabase?.getMsgHdrForMessageID("srv-remind@example.invalid"); }, 10000));
              out.gone = find() < 0;
              await wait(2500);
              await R.check();
              const back = await until(() => { inbox.updateFolder(a3.msgWindow); return inbox.msgDatabase.getMsgHdrForMessageID("srv-remind@example.invalid"); }, 15000);
              out.back = !!back; out.unread = back ? !back.isRead : null;
              out.left = R.list().length;
              return out;""" % (ADDON_ID, key))
            ok = res.get("menu") and res.get("items", 0) >= 3 and res.get("moved") and res.get("back") and res.get("unread") and res.get("left") == 0
            return ok, f"{res}"
        check("Testkonto: Erinnern – Mail in „Remind Me“, kommt zur Zeit ungelesen zurück", remind_me, results)

        def follow_up():
            # Nachfassen: eigene Mail von vor 5 Tagen ohne Antwort → Hinweis über dem Posteingang mit „Follow Up“; ✕ blendet aus
            five = time.strftime("%a, %d %b %Y 09:00:00 +0000", time.gmtime(time.time() - 5 * 86400))
            servers.imap.add("Sent", f"From: Halo Test <halo@example.invalid>\nTo: Kunde <kunde@example.invalid>\nSubject: Angebot Fenster\n"
                             f"Date: {five}\nMessage-ID: <srv-follow@example.invalid>\n\nWie besprochen.\n", flags=["\\Seen"])
            res = m.js(r"""
              const SHOT = %s;
              const { MailServices } = ChromeUtils.importESModule("resource:///modules/MailServices.sys.mjs");
              const { ExtensionParent } = ChromeUtils.importESModule("resource://gre/modules/ExtensionParent.sys.mjs");
              const g = ExtensionParent.GlobalManager.getExtension("%s").experimentAPIManager.global;
              const FU = Cu.evalInSandbox("FollowUp", g);
              const acc = MailServices.accounts.getAccount("%s"), root = acc.incomingServer.rootFolder;
              const sent = root.getFolderWithFlags(Ci.nsMsgFolderFlags.SentMail), inbox = root.getFolderWithFlags(Ci.nsMsgFolderFlags.Inbox);
              const a3 = await toMail();
              a3.displayFolder(sent.URI);
              await until(() => { sent.updateFolder(a3.msgWindow); return sent.msgDatabase.getMsgHdrForMessageID("srv-follow@example.invalid"); }, 15000);
              FU.cache = null;
              a3.displayFolder(inbox.URI); await ruhig(1200);
              const bar = await until(() => a3.document.getElementById("mcFollowUp"), 5000);
              const out = { bar: bar?.textContent || null };
              // Aussehen wie die Hinweiskarte über der Mail (E22, Variante A 17.11.2026; vorher hellblau mit blauem Knopf):
              // graue Karte (--mt-hint-bg) Radius 10, Text 12 px in Textfarbe, „Follow Up“ graue Textkapsel 24 px mit
              // Lichtkante der Knopf-Familie (keine Akzentfarbe), Schließen grauer Kreis 24 px mit halo-×
              if (bar) {
                const cs = el => a3.getComputedStyle(el), r = el => el.getBoundingClientRect();
                const go = bar.querySelector(".mc-fu-go"), x = bar.querySelector(".mc-fu-close");
                const mk = v => { const e = a3.document.createElementNS("http://www.w3.org/1999/xhtml", "div"); e.style.background = v; e.style.color = v; bar.append(e); return e; };
                const probe = mk("AccentColor"), pHint = mk("var(--mt-hint-bg)"), pCtl = mk("var(--mt-control)"), pText = mk("var(--mt-text)");
                out.look = { accent: cs(probe).backgroundColor, hint: cs(pHint).backgroundColor, ctl: cs(pCtl).backgroundColor, textColor: cs(pText).color,
                             barBg: cs(bar).backgroundColor, barRadius: cs(bar).borderTopLeftRadius,
                             goBg: cs(go).backgroundColor, goColor: cs(go).color, goShadow: cs(go).boxShadow, goH: Math.round(r(go).height), goRadius: cs(go).borderTopLeftRadius,
                             xBg: cs(x).backgroundColor, xImg: cs(x).backgroundImage, xW: Math.round(r(x).width), xH: Math.round(r(x).height), xRadius: cs(x).borderTopLeftRadius,
                             text: cs(bar.querySelector(".mc-fu-text")).fontSize, barH: Math.round(r(bar).height),
                             // Luft bis zur Mailliste darunter (vorher 2 px, Hinweis klebte an der ersten Kachel)
                             gap: Math.round(r(a3.document.getElementById("threadTree")).top - r(bar).bottom) };
                for (const e of [probe, pHint, pCtl, pText]) e.remove();
                if (SHOT) {
                  // Bild des Hinweises samt erster Mail-Kachel (nur Testprofil)
                  const pr = r(a3.document.getElementById("threadPane")), br = r(bar);
                  const bm = await a3.browsingContext.currentWindowGlobal.drawSnapshot(new a3.DOMRect(pr.left, br.top - 8, Math.min(pr.width, 520), br.height + 80), 2, "white");
                  const cv = a3.document.createElementNS("http://www.w3.org/1999/xhtml", "canvas"); cv.width = bm.width; cv.height = bm.height;
                  cv.getContext("2d").drawImage(bm, 0, 0); out.png = cv.toDataURL("image/png").split(",")[1];
                  out.dark = a3.matchMedia("(prefers-color-scheme: dark)").matches;
                }
              }
              // Schalter „Follow-Up Suggestions“ aus: Hinweis sofort weg (ohne Ordnerwechsel), an: wieder da
              Services.prefs.setBoolPref("extensions.mailcards.followUp", false); await ruhig(300);
              out.off = !!a3.document.getElementById("mcFollowUp");
              Services.prefs.clearUserPref("extensions.mailcards.followUp");
              out.on = !!(await until(() => a3.document.getElementById("mcFollowUp"), 3000));
              bar?.querySelector(".mc-fu-close").click(); a3.document.querySelector("#mcFollowUp .mc-fu-close")?.click(); await ruhig(300);
              out.afterDismiss = !!a3.document.getElementById("mcFollowUp") && a3.document.getElementById("mcFollowUp").textContent.includes("Angebot Fenster");
              Services.prefs.clearUserPref("extensions.mailcards.followUpDismissed"); FU.cache = null;
              return out;""" % ("true" if os.environ.get("HALO_SHOTS") else "false", ADDON_ID, key))
            if res.get("png"):
                import base64
                os.makedirs(os.environ["HALO_SHOTS"], exist_ok=True)
                path = os.path.join(os.environ["HALO_SHOTS"], f"nachfassen-{'dunkel' if res.get('dark') else 'hell'}.png")
                open(path, "wb").write(base64.b64decode(res.pop("png")))
                print(f"Bild {path}", flush=True)
            ok = ("Angebot Fenster" in (res.get("bar") or "") and "Follow Up" in (res.get("bar") or "") and not res.get("afterDismiss")
                  and res.get("off") is False and res.get("on") is True)
            lk = res.get("look") or {}
            ok = ok and (lk.get("barBg") == lk.get("hint") and lk.get("barRadius") == "10px"
                         and lk.get("goBg") == lk.get("ctl") and lk.get("goBg") != lk.get("accent") and lk.get("goColor") == lk.get("textColor")
                         and "inset" in (lk.get("goShadow") or "") and lk.get("goH") == 24 and lk.get("goRadius") in ("999px", "12px")
                         and lk.get("xBg") == lk.get("ctl") and "close-12.svg" in (lk.get("xImg") or "") and lk.get("xW") == 24 and lk.get("xH") == 24
                         and lk.get("xRadius") in ("50%", "12px") and lk.get("text") == "12px" and lk.get("gap", 0) >= 8)
            return ok, f"{res}"
        check("Testkonto: Nachfassen – Hinweis über dem Posteingang zu eigener Mail ohne Antwort als graue Karte wie die Hinweiskarte über der Mail, „Follow Up“ graue Textkapsel 24 px mit Lichtkante, Schließen grauer Kreis 24 px, 8 px Luft zur Mailliste, Schließen blendet aus, Schalter wirkt sofort", follow_up, results)

        def subscribe_dialog():
            # Abonnieren-Dialog (nur mit IMAP-Konto): öffnet, zeigt den nicht abonnierten Ordner „Projekte“, ohne harte Rahmen
            res = m.js(r"""
              const { MailServices } = ChromeUtils.importESModule("resource:///modules/MailServices.sys.mjs");
              const acc = MailServices.accounts.getAccount("%s");
              const a3 = await toMail();
              w.openDialog("chrome://messenger/content/subscribe.xhtml", "_blank", "chrome,modal=no,titlebar,resizable=yes",
                { folder: acc.incomingServer.rootFolder, okCallback() {} });
              const dw = await until(() => [...Services.wm.getEnumerator(null)].find(x => /subscribe\.xhtml/.test(x.location.href) && x.document.readyState == "complete"), 8000);
              if (!dw) return { open: false };
              const rows = await until(() => { const t = dw.document.getElementById("subscribeTree");
                const names = [...(t?.querySelectorAll("tr[id^='subscribeTree-row']") || [])].map(r => r.textContent.trim()); return names.includes("Projekte") && names; }, 10000);
              const tree = dw.document.getElementById("subscribeTree");
              const out = { open: true, rows: rows || [], border: tree ? dw.getComputedStyle(tree).borderTopColor : null, bw: tree ? dw.getComputedStyle(tree).borderTopWidth : null };
              dw.close();
              return out;""" % key)
            ok = res.get("open") and "Projekte" in res.get("rows", []) and float((res.get("bw") or "0px")[:-2]) <= 1
            return ok, f"{res}"
        check("Testkonto: Abonnieren-Dialog zeigt die Ordner des Servers, ohne harten Rahmen", subscribe_dialog, results)

        def archive_account():
            # Konto lokal archivieren: Kontextmenü des Kontos → Rückfrage → alle Ordner (ohne Papierkorb/Entwürfe) als Kopie in
            # Lokale Ordner/<Konto> (Archiv) mit gleicher Anzahl; zweiter Lauf kopiert nichts doppelt
            servers.imap.add("Archive", "From: Dora <dora@example.invalid>\nTo: Halo Test <halo@example.invalid>\nSubject: Alte Rechnung\n"
                             "Date: Mon, 12 Oct 2026 10:00:00 +0200\nMessage-ID: <srv-arch-1@example.invalid>\n\nRechnung im Anhang.\n")
            servers.imap.add("Trash", "From: Spam <x@example.invalid>\nTo: Halo Test <halo@example.invalid>\nSubject: Weg damit\n"
                             "Date: Mon, 12 Oct 2026 11:00:00 +0200\nMessage-ID: <srv-trash-1@example.invalid>\n\nx\n")
            menu_js = r"""
              const { MailServices } = ChromeUtils.importESModule("resource:///modules/MailServices.sys.mjs");
              const server = MailServices.accounts.getAccount("%s").incomingServer, root = server.rootFolder;
              const a3 = await toMail();
              // Konto wie beim Nutzer schon geöffnet: Ordner vom Server, Posteingang geladen
              const inbox = await until(() => root.getFolderWithFlags(Ci.nsMsgFolderFlags.Inbox), 10000);
              a3.displayFolder(inbox.URI);
              await until(() => a3.gDBView?.rowCount > 0 && root.subFolders.length > 2, 15000);
              const row = await until(() => [...a3.document.querySelectorAll("#folderTree li")].find(li => li.uri == root.URI)?.querySelector(".container"), 8000);
              const popup = a3.document.getElementById("folderPaneContext");
              const shown = new Promise(r => popup.addEventListener("popupshown", r, { once: true }));
              row.dispatchEvent(new a3.MouseEvent("contextmenu", { bubbles: true, button: 2, clientX: 20, clientY: 10 }));
              await Promise.race([shown, wait(3000)]);
              const item = a3.document.getElementById("mcArchiveAccount");
              const out = { visible: !!item && !item.hidden && popup.state == "open", label: item?.getAttribute("label"), subs: root.subFolders.map(f => f.name) };
              popup.hidePopup();
              return out;""" % key
            # (die Rückfrage schließt Marionette selbst – das Kopieren direkt anstoßen)
            run_js = r"""
              const { MailServices } = ChromeUtils.importESModule("resource:///modules/MailServices.sys.mjs");
              const server = MailServices.accounts.getAccount("%s").incomingServer, root = server.rootFolder;
              const job = await w.__mcArchiveAccount(server);
              const local = MailServices.accounts.localFoldersServer.rootFolder;
              const target = local.subFolders.find(f => f.name.startsWith(server.prettyName) && f.name != server.prettyName);
              return { copied: job?.copied, skipped: job?.skipped, failed: job?.failed, target: target?.name,
                folders: target ? Object.fromEntries(target.subFolders.map(f => [f.name, f.getTotalMessages(false)])) : null,
                source: Object.fromEntries(root.subFolders.map(f => [f.name, f.getTotalMessages(false)])) };""" % key
            # Assistent: Übersicht mit Ordnern und Anzahl, Start, Fortschritt je Ordner, Abschluss (hier: alles schon archiviert)
            wizard_js = r"""
              const { MailServices } = ChromeUtils.importESModule("resource:///modules/MailServices.sys.mjs");
              const server = MailServices.accounts.getAccount("%s").incomingServer;
              const hw = w.__mcArchiveWizard(server);
              const doc = await until(() => hw.document?.querySelector("body.archive table tr") && hw.document, 8000);
              if (!doc) return { open: false };
              const rows = () => [...doc.querySelectorAll("table tr")];
              const out = { open: true, title: doc.querySelector("h1")?.textContent, account: doc.querySelector("select")?.selectedOptions[0]?.textContent,
                            folders: rows().map(r => r.cells[0].textContent), summary: doc.querySelector(".summary")?.textContent,
                            trash: rows().some(r => /Trash|Papierkorb/.test(r.cells[0].textContent)) };
              doc.querySelector(".buttons .primary").click();
              await until(() => /Done|Fertig/.test(doc.querySelector(".buttons .primary .label")?.textContent || ""), 30000);
              out.end = { button: doc.querySelector(".buttons .primary .label")?.textContent, states: rows().map(r => r.dataset.state),
                          nums: rows().map(r => r.cells[1].textContent), summary: doc.querySelector(".summary")?.textContent };
              hw.close();
              return out;""" % key
            first = m.js(menu_js)
            first.update(m.js(run_js))
            second = m.js(run_js)
            wiz = m.js(wizard_js)
            f = first.get("folders") or {}
            src = first.get("source") or {}
            inbox = next((k for k in f if k.lower() == "inbox"), None)
            ok = (first.get("visible") and first.get("target") and inbox and f.get(inbox, 0) >= 1
                  and f.get(inbox) == src.get(inbox) and f.get("Archive") == 1 and "Trash" not in f and "Drafts" not in f
                  and second.get("folders") == f)
            we = wiz.get("end") or {}
            ok = ok and (wiz.get("open") and wiz.get("title") == "Archive Account Locally" and wiz.get("account") == first.get("target", "").split(" (")[0]
                         and any("Archiv" in x for x in (wiz.get("folders") or [])) and not wiz.get("trash") and "messages in" in (wiz.get("summary") or "")
                         and we.get("button") == "Done" and we.get("states") and all(x == "done" for x in we["states"])
                         and all(n.endswith("✓") for n in we.get("nums", [])) and "already archived" in (we.get("summary") or ""))
            return ok, f"{first} 2. Lauf: {second} Assistent: {wiz}"
        check("Testkonto: Konto lokal archivieren – Kontextmenü, Assistent mit Übersicht, Fortschritt und Abschluss, alle Ordner als Kopie in Lokale Ordner, zweiter Lauf ohne Duplikate", archive_account, results)

        def archive_account_new():
            # Konto lokal archivieren 3/3: ein weiterer Lauf nach neuen Mails am Server kopiert genau die neuen (Vergleich
            # über die Message-ID, keine Duplikate); CardDAV-Adressbuch (Benutzername = Adresse des Kontos) und Kalender mit
            # der Identität des Kontos landen im lokalen Adressbuch bzw. Kalender „<Konto> (Archive)“, auch dort nur Neues
            setup_js = r"""
              const { MailServices } = ChromeUtils.importESModule("resource:///modules/MailServices.sys.mjs");
              const { CalEvent } = ChromeUtils.importESModule("resource:///modules/CalEvent.sys.mjs");
              const account = MailServices.accounts.getAccount("%s"), id = account.identities[0];
              // CardDAV-Buch ohne Server-Adresse (kein Abgleich); Karten ohne Hochladen anlegen
              const prefId = MailServices.ab.newAddressBook("Halo CardDAV", null, Ci.nsIAbManager.CARDDAV_DIRECTORY_TYPE);
              const book = MailServices.ab.getDirectoryFromId(prefId);
              book.setStringValue("carddav.username", id.email);
              for (const [n, e] of [["Erika Archiv", "erika@example.invalid"], ["Fritz Archiv", "fritz@example.invalid"]]) {
                const c = Cc["@mozilla.org/addressbook/cardproperty;1"].createInstance(Ci.nsIAbCard);
                c.displayName = n; c.primaryEmail = e;
                (book.addCardInternal ? book.addCardInternal(c) : book.addCard(c));
              }
              const c = cal.manager.createCalendar("storage", Services.io.newURI("moz-storage-calendar://"));
              c.name = "Halo Konto-Kalender"; c.setProperty("imip.identity.key", id.key);
              cal.manager.registerCalendar(c);
              const ev = new CalEvent(); ev.title = "Halo Archivtermin"; ev.id = "halo-archiv-termin@example.invalid";
              ev.startDate = cal.createDateTime("20261120T100000Z"); ev.endDate = cal.createDateTime("20261120T110000Z");
              await c.addItem(ev);
              return { book: book.childCards.length, cal: c.id };""" % key
            run_js = r"""
              const { MailServices } = ChromeUtils.importESModule("resource:///modules/MailServices.sys.mjs");
              const server = MailServices.accounts.getAccount("%s").incomingServer, root = server.rootFolder;
              const job = await w.__mcArchiveAccount(server);
              const local = MailServices.accounts.localFoldersServer.rootFolder;
              const target = local.subFolders.find(f => f.name.startsWith(server.prettyName) && f.name != server.prettyName);
              const ids = f => { try { return [...f.msgDatabase.enumerateMessages()].map(h => h.messageId); } catch { return []; } };
              const inbox = target?.subFolders.find(f => f.name.toLowerCase() == "inbox");
              const name = target?.name;
              const book = MailServices.ab.directories.find(d => d.dirName == name && d.dirType == Ci.nsIAbManager.JS_DIRECTORY_TYPE);
              const calendar = cal.manager.getCalendars().find(c => c.name == name && c.type == "storage");
              const events = calendar ? await calendar.getItemsAsArray(Ci.calICalendar.ITEM_FILTER_ALL_ITEMS, 0, null, null) : [];
              return { copied: job?.copied, skipped: job?.skipped, contacts: job?.contacts, events: job?.events, failed: job?.failed,
                inbox: inbox ? ids(inbox) : null, archive: Object.fromEntries((target?.subFolders || []).map(f => [f.name, f.getTotalMessages(false)])),
                cards: book ? book.childCards.map(c => c.displayName).sort() : null, titles: events.map(e => e.title) };""" % key
            wizard_js = r"""
              const { MailServices } = ChromeUtils.importESModule("resource:///modules/MailServices.sys.mjs");
              const server = MailServices.accounts.getAccount("%s").incomingServer;
              const hw = w.__mcArchiveWizard(server);
              const doc = await until(() => hw.document?.querySelector("body.archive tr[data-kind='calendar']") && hw.document, 8000);
              if (!doc) return { open: false };
              const row = k => doc.querySelector(`tr[data-kind='${k}']`);
              await until(() => row("calendar").cells[1].textContent != "…", 5000);
              const out = { open: true, contacts: [row("contacts")?.cells[0].textContent, row("contacts")?.cells[1].textContent],
                            calendar: [row("calendar")?.cells[0].textContent, row("calendar")?.cells[1].textContent], note: doc.querySelector(".note")?.textContent };
              hw.close();
              return out;""" % key
            cleanup_js = r"""
              const { MailServices } = ChromeUtils.importESModule("resource:///modules/MailServices.sys.mjs");
              const server = MailServices.accounts.getAccount("%s").incomingServer;
              const archiv = n => n.startsWith(server.prettyName + " (");
              for (const d of MailServices.ab.directories.filter(d => d.dirName == "Halo CardDAV" || archiv(d.dirName))) MailServices.ab.deleteAddressBook(d.URI);
              for (const c of cal.manager.getCalendars().filter(c => c.name == "Halo Konto-Kalender" || archiv(c.name))) cal.manager.removeCalendar(c);
              return true;""" % key
            res = {}
            try:
                res["setup"] = m.js(setup_js)
                res["wizard"] = m.js(wizard_js)
                res["first"] = m.js(run_js)
                # zwei neue Mails am Server, dann noch ein Lauf
                for i in (1, 2):
                    servers.imap.add("INBOX", f"From: Gerda <gerda@example.invalid>\nTo: Halo Test <halo@example.invalid>\nSubject: Neu nach dem Archiv {i}\n"
                                     f"Date: Tue, 17 Nov 2026 1{i}:00:00 +0100\nMessage-ID: <srv-arch-neu-{i}@example.invalid>\n\nNeu.\n")
                res["second"] = m.js(run_js)
                res["third"] = m.js(run_js)
            finally:
                m.js(cleanup_js)
            first, second, third, wiz = res.get("first") or {}, res.get("second") or {}, res.get("third") or {}, res.get("wizard") or {}
            ids2 = second.get("inbox") or []
            neu = [x for x in ids2 if x.startswith("srv-arch-neu-")]
            ok = (first.get("inbox") is not None and second.get("copied") == 2 and sorted(neu) == ["srv-arch-neu-1@example.invalid", "srv-arch-neu-2@example.invalid"]
                  and len(ids2) == len(set(ids2)) == len(first["inbox"]) + 2
                  and third.get("copied") == 0 and third.get("inbox") == ids2 and third.get("archive") == second.get("archive")
                  and first.get("cards") == ["Erika Archiv", "Fritz Archiv"] and first.get("titles") == ["Halo Archivtermin"]
                  and first.get("contacts") == 2 and first.get("events") == 1
                  and second.get("contacts") == 0 and second.get("events") == 0
                  and third.get("cards") == first.get("cards") and third.get("titles") == first.get("titles") and not third.get("failed")
                  and wiz.get("open") and wiz.get("contacts") == ["Halo CardDAV (Contacts)", "2"] and wiz.get("calendar") == ["Halo Konto-Kalender (Calendar)", "1"]
                  and "address book and calendar" in (wiz.get("note") or ""))
            return ok, f"{res}"
        check("Testkonto: Konto lokal archivieren – weiterer Lauf kopiert nur neue Mails (Message-ID), Kontakte und Kalender des Kontos in lokales Adressbuch und lokalen Kalender, ohne Duplikate", archive_account_new, results)

        def send_error():
            # Server lehnt ab → halo.spaces meldet den Fehler als Dialog mit „Postausgang zeigen“ (statt nur in der
            # Aktivitätsanzeige). Der Dialog selbst unterbräche Marionette – mitgeschnitten wird sein Aufruf. (Unter Windows
            # zeigt Thunderbird zusätzlich eigene Meldungen – die werden geschlossen)
            servers.smtp.fail_next = 1
            m.js(r"""
              const { MailServices } = ChromeUtils.importESModule("resource:///modules/MailServices.sys.mjs");
              const { ExtensionParent } = ChromeUtils.importESModule("resource://gre/modules/ExtensionParent.sys.mjs");
              const g = ExtensionParent.GlobalManager.getExtension("%s").experimentAPIManager.global;
              const enh = Cu.evalInSandbox("enhancer", g);
              w.__mcErrCalls = []; w.__mcErrOrig = enh.showSendError;
              enh.showSendError = async (hdr, message) => { w.__mcErrCalls.push({ subject: hdr?.mime2DecodedSubject || null }); };
              const acc = MailServices.accounts.getAccount("%s");
              Services.prefs.setIntPref("extensions.mailcards.undoSend", 0);
              const params = Cc["@mozilla.org/messengercompose/composeparams;1"].createInstance(Ci.nsIMsgComposeParams);
              const fields = Cc["@mozilla.org/messengercompose/composefields;1"].createInstance(Ci.nsIMsgCompFields);
              fields.to = "ziel@example.invalid"; fields.subject = "Halo Fehlerprobe"; fields.body = "Wird abgelehnt.";
              params.type = Ci.nsIMsgCompType.New; params.format = Ci.nsIMsgCompFormat.PlainText; params.composeFields = fields; params.identity = acc.defaultIdentity;
              MailServices.compose.OpenComposeWindowWithParams(null, params);
              const cw = await until(() => [...Services.wm.getEnumerator("msgcompose")].find(x => x.document.readyState == "complete" && x.gMsgCompose), 10000);
              await bis(() => cw.gLoadingComplete, "Verfassen-Fenster fertig geladen", 8000); await ruhig(1500); cw.goDoCommand("cmd_sendNow");
              return 1;""" % (ADDON_ID, key))
            # Thunderbirds eigene Meldung („Sending of the message failed“, Windows) geht etwa zeitgleich mit dem
            # halo-Dialog auf – auch erst nach der Abfrage, die den Aufruf schon sieht. Marionette schließt sie dann beim
            # nächsten Befehl selbst und lässt ihn mit „Unexpected alert dialog detected“ scheitern (CI 44249378415):
            # Aufräumen darum mit Wiederholung und immer (sonst bliebe die abgelehnte Mail im Postausgang und ginge beim
            # nächsten Senden zuerst hinaus – die OpenPGP-Prüfung fand dann ihre Mail nicht)
            def trotz_alarm(body):
                for i in range(3):
                    try:
                        return m.js(body)
                    except RuntimeError as e:
                        if "Unexpected alert" not in str(e) or i == 2:
                            raise
            res = None
            try:
                for _ in range(20):
                    time.sleep(1)
                    try:
                        m.cmd("WebDriver:DismissAlert", {})
                    except Exception:
                        pass
                    try:
                        res = m.js(r"""
                          const { MailServices } = ChromeUtils.importESModule("resource:///modules/MailServices.sys.mjs");
                          const outbox = MailServices.accounts.localFoldersServer.rootFolder.getFolderWithFlags(Ci.nsMsgFolderFlags.Queue);
                          return { calls: w.__mcErrCalls || [], kept: outbox?.getTotalMessages(false) || 0 };""")
                    except Exception:
                        res = None
                    if res and res.get("calls"):
                        break
            finally:
                trotz_alarm(r"""
                  const { ExtensionParent } = ChromeUtils.importESModule("resource://gre/modules/ExtensionParent.sys.mjs");
                  const enh = Cu.evalInSandbox("enhancer", ExtensionParent.GlobalManager.getExtension("%s").experimentAPIManager.global);
                  if (w.__mcErrOrig) enh.showSendError = w.__mcErrOrig; delete w.__mcErrOrig;
                  Services.prefs.clearUserPref("extensions.mailcards.undoSend");
                  for (const x of [...Services.wm.getEnumerator(null)]) if (!x.location.href.includes("messenger.xhtml")) x.close();
                  return 1;""" % ADDON_ID)
                # Postausgang wieder leeren (die abgelehnte Mail bliebe sonst für die folgenden Prüfungen liegen)
                trotz_alarm(r"""
                  const { MailServices } = ChromeUtils.importESModule("resource:///modules/MailServices.sys.mjs");
                  const outbox = MailServices.accounts.localFoldersServer.rootFolder.getFolderWithFlags(Ci.nsMsgFolderFlags.Queue);
                  const hdrs = outbox ? [...outbox.msgDatabase.enumerateMessages()] : [];
                  if (hdrs.length) outbox.deleteMessages(hdrs, null, true, false, null, false);
                  return 1;""")
            res = res or {}
            c = (res.get("calls") or [{}])[0]
            ok = c.get("subject") == "Halo Fehlerprobe" and res.get("kept", 0) >= 1
            return ok, f"{res}"
        check("Testkonto: abgelehnte Mail → Fehler-Dialog (mit „Postausgang zeigen“), Mail bleibt im Postausgang", send_error, results)

        def chat_irc():
            # Chat mit dem IRC-Testserver: anmelden, Raum betreten, Gespräch in der Liste ausgewählt (grau wie die Ordnerliste),
            # Nachricht einer erfundenen Person erscheint, eigene Nachricht kommt beim Server an
            res = m.js(r"""
              const { IMServices } = ChromeUtils.importESModule("resource:///modules/IMServices.sys.mjs");
              tm.openTab("chat", {}); await ruhig(2000);
              const acc = IMServices.accounts.createAccount("halo@127.0.0.1", "prpl-irc");
              acc.setInt("port", %d); acc.setBool("ssl", false); acc.alias = "Halo Testchat";
              acc.connect();
              const out = { connected: !!(await until(() => acc.connected, 15000)) };
              const fields = acc.getChatRoomDefaultFieldValues(); fields.setValue("channel", "#halo");
              acc.joinChat(fields);
              const conv = await until(() => IMServices.conversations.getConversations().find(c => c.name == "#halo"), 10000);
              const listbox = d.getElementById("contactlistbox");
              const it = await until(() => [...listbox.querySelectorAll("richlistitem")].find(i => i.getAttribute("displayname") == "#halo" || i.textContent.includes("#halo")), 8000);
              if (it) listbox.selectedItem = it;
              await ruhig(1500);
              // Auswahl wie in der Ordnerliste der Mail: grau (--mt-selected-unfocused), Schrift in Textfarbe, ohne
              // Thunderbirds blauen Strich links und ohne Ränder; mit Fokus in der Liste in der Akzentfarbe getönt
              const want = v => { const p = d.createElementNS("http://www.w3.org/1999/xhtml", "div"); p.style.backgroundColor = v; p.style.color = v;
                                  d.documentElement.append(p); const c = w.getComputedStyle(p).backgroundColor; p.remove(); return c; };
              const look = () => { const cs = w.getComputedStyle(it), line = it.querySelector(".box-line");
                return { bg: cs.backgroundColor, color: cs.color, radius: cs.borderTopLeftRadius,
                         borders: [cs.borderTopColor, cs.borderBottomColor, cs.borderLeftColor].every(c => c == "rgba(0, 0, 0, 0)" || cs.borderTopWidth == "0px"),
                         line: line ? w.getComputedStyle(line).backgroundColor : "keine" }; };
              if (it) {
                if (d.activeElement == listbox) listbox.blur();
                await ruhig(300);
                out.item = { ...look(), focus: listbox.matches(":focus"), wantBg: want("var(--mt-selected-unfocused)"), wantColor: want("var(--mt-text)") };
                // Schrift und Zeile wie in den übrigen Seitenleisten: Name 13 px, gewählt halbfett, Zeile 32 px; der Pfeil vor
                // „Conversations“ nur beim Überfahren der Seitenleiste (wie in der Ordnerliste der Mail)
                const nameEl = it.querySelector(".blistDisplayName"), tw = d.querySelector("#conversationsGroup .twisty");
                out.font = { name: nameEl && [w.getComputedStyle(nameEl).fontSize, w.getComputedStyle(nameEl).fontWeight], h: Math.round(it.getBoundingClientRect().height),
                             twisty: tw ? (d.getElementById("listPaneBox").matches(":hover") ? "hover" : w.getComputedStyle(tw).opacity) : "fehlt" };
                // Hauptfenster vorn, sonst greift :focus unter Linux (xvfb) nicht, obwohl activeElement die Liste ist
                for (let i = 0; i < 4 && !listbox.matches(":focus"); i++) {
                  w.focus(); await until(() => Services.focus.activeWindow == w, 3000);
                  listbox.focus(); await until(() => listbox.matches(":focus"), 2000);
                }
                await ruhig(300);
                out.itemFocus = { ...look(), focus: listbox.matches(":focus"), active: Services.focus.activeWindow == w,
                                  wantBg: want("color-mix(in srgb, var(--mt-selection) 22%%, transparent)") };
                listbox.blur(); await ruhig(200);
              }
              conv?.sendMsg("Hallo zurück");
              w.__mcChatAcc = acc.id;
              return out;""" % servers.irc_port)
            time.sleep(2)
            servers.irc.say("#halo", "anna", "Hallo aus dem Testchat")
            res2 = m.js(r"""
              const { IMServices } = ChromeUtils.importESModule("resource:///modules/IMServices.sys.mjs");
              const cb = [...d.querySelectorAll("browser")].find(b => b.currentURI?.spec == "chrome://chat/content/conv.html" && b.getBoundingClientRect().width > 100);
              const texts = () => [...(cb?.contentDocument?.querySelectorAll(".message, .msg") || [])].map(e => e.textContent);
              const got = await until(() => texts().some(t => t.includes("Hallo aus dem Testchat")), 10000);
              const out = { shown: !!got, own: texts().some(t => t.includes("Hallo zurück")) };
              // halo-Stil: Seitenleiste rechts im Seitenleisten-Grau, Teilnehmer mit Kreis und Anfangsbuchstaben,
              // Eingabefeld als Textfeld (kleiner Radius, sichtbarer Rand) statt Thunderbirds schlichter Fläche
              const cs = (e, p) => w.getComputedStyle(e, p);
              const side = d.getElementById("contextPane"), probe = d.createElementNS("http://www.w3.org/1999/xhtml", "div");
              probe.style.backgroundColor = "var(--mt-sidebar)"; d.documentElement.append(probe); const sideWant = cs(probe).backgroundColor; probe.remove();
              const nicks = [...d.querySelectorAll("#nicklist > richlistitem")].filter(i => i.getBoundingClientRect().width);
              const box = [...d.querySelectorAll(".conv-textbox")].find(e => e.getBoundingClientRect().width);
              out.look = { side: side && cs(side).backgroundColor == sideWant, nicks: nicks.length,
                           circles: nicks.filter(i => i.dataset.mcInitial && parseFloat(cs(i, "::before").width) == 22 && cs(i, "::before").borderTopLeftRadius != "0px").length,
                           box: box && { radius: parseFloat(cs(box).borderTopLeftRadius), border: parseFloat(cs(box).borderTopWidth) } };
              // Chat-Leiste mit Konto plastisch wie die Kapseln der übrigen Spaces; unter der Maus Kreis bzw. Kapsel 3 px
              // innen mit Lichtkante, gedrückt ohne Licht (18.11.2026)
              out.bar = {};
              for (const id of ["button-add-buddy", "button-join-chat"]) {
                const b = d.getElementById(id); if (!b) continue;
                const one = { dis: b.disabled, img: cs(b).backgroundImage.split("linear-gradient").length - 1, sh: cs(b).boxShadow };
                InspectorUtils.addPseudoClassLock(b, ":hover"); await ruhig(150);
                const a = cs(b, "::after"); Object.assign(one, { hOp: a.opacity, hSh: a.boxShadow, hW: parseFloat(a.width), bW: b.getBoundingClientRect().width, hImg: cs(b).backgroundImage.split("linear-gradient").length - 1 });
                InspectorUtils.addPseudoClassLock(b, ":active"); await ruhig(150); one.pSh = cs(b, "::after").boxShadow;
                InspectorUtils.clearPseudoClassLocks(b); out.bar[id] = one;
              }
              const acc = IMServices.accounts.getAccountById(w.__mcChatAcc); delete w.__mcChatAcc;
              try { acc.disconnect(); await ruhig(500); IMServices.accounts.deleteAccount(acc.id); } catch {}
              await toMail();
              for (const t of [...tm.tabInfo].slice(1)) tm.closeTab(t);
              return out;""")
            it, itf = res.get("item") or {}, res.get("itemFocus") or {}
            fo = res.get("font") or {}
            ok = (res.get("connected") and it and not it.get("focus") and fo.get("name") == ["13px", "600"] and fo.get("h") == 32
                  and fo.get("twisty") in ("0", "hover") and it.get("bg") == it.get("wantBg") and it.get("color") == it.get("wantColor")
                  and it.get("radius") == "10px" and it.get("borders") and it.get("line") in ("keine", "rgba(0, 0, 0, 0)")
                  and itf.get("focus") and itf.get("bg") == itf.get("wantBg") and itf.get("color") == it.get("wantColor")
                  and itf.get("line") in ("keine", "rgba(0, 0, 0, 0)")
                  and res2.get("shown") and res2.get("own") and ("#halo", "Hallo zurück") in servers.irc.said)
            lk = res2.get("look") or {}
            ok = (ok and lk.get("side") and lk.get("nicks", 0) >= 1 and lk.get("circles") == lk.get("nicks")
                  and (lk.get("box") or {}).get("radius", 99) <= 8 and (lk.get("box") or {}).get("border", 0) > 0)
            bar = res2.get("bar") or {}
            def plastic_btn(o, wpx):
                return (bool(o) and not o["dis"] and o["img"] >= 3 and o["hImg"] == o["img"] and "inset" in o["sh"] and o["hOp"] == "1"
                        and o["hSh"].startswith("rgba(255, 255, 255") and "inset" in o["pSh"] and not o["pSh"].startswith("rgba(255, 255, 255")
                        and abs(o["hW"] - (wpx if wpx else o["bW"] - 6)) <= 0.5)
            ok = ok and plastic_btn(bar.get("button-add-buddy"), None) and plastic_btn(bar.get("button-join-chat"), 32)
            return ok, f"{res} {res2} IRC: {servers.irc.log[:8]}"
        check("Testkonto: Chat mit Testserver – anmelden, Raum betreten, Gespräch ausgewählt (grau wie die Ordnerliste, mit Fokus getönt, ohne blauen Strich; Name 13 px halbfett, Zeile 32 px, Pfeil nur beim Überfahren), Nachrichten hin und zurück; Seitenleiste, Teilnehmer-Kreise und Eingabefeld im halo-Stil; Chat-Leiste plastisch mit Kreis unter der Maus", chat_irc, results)

        def wrong_password():
            # Server lehnt die Anmeldung ab → Thunderbirds Nachfrage erscheint als Kachel im Fenster (wie ein macOS-Sheet)
            servers.imap.fail_login = True
            res = m.js(r"""
              const { MailServices } = ChromeUtils.importESModule("resource:///modules/MailServices.sys.mjs");
              const acc = MailServices.accounts.getAccount("%s"), server = acc.incomingServer;
              await toMail();
              const host = d.getElementById("mcDialogBox");
              const out = { host: !!host, seen: null, count: 0 };
              // jede Nachfrage messen und abbrechen (Marionette bräche sie sonst beim nächsten Befehl selbst ab)
              const onOpen = () => {
                out.count++;
                w.setTimeout(() => {
                  const card = host?.querySelector(".dialogBox"), f = host?.querySelector(".dialogFrame");
                  out.seen ||= { open: !!host?.open, radius: card ? w.getComputedStyle(card).borderTopLeftRadius : null,
                                 text: (f?.contentDocument?.getElementById("infoBody")?.textContent || "").slice(0, 120) };
                  f?.contentDocument?.querySelector("dialog")?.cancelDialog();
                }, 900);
              };
              w.addEventListener("dialogopen", onOpen, true);
              w.__mcPwOff = () => w.removeEventListener("dialogopen", onOpen, true);
              server.closeCachedConnections(); await wait(500);
              // abrufen wie „Nachrichten abrufen“: Thunderbird 162 nimmt bei getNewMessages statt des msgWindow nur noch
              // „interactive“ – der alte Aufruf mit msgWindow fragte dort nicht mehr nach (auch ohne halo.spaces)
              w.setTimeout(() => w.GetMessagesForInboxOnServer(server), 100);
              w.__mcPwTest = out;
              return 1;""" % key)
            time.sleep(8)
            res = m.js(r"""
              const out = w.__mcPwTest || {}; delete w.__mcPwTest;
              w.__mcPwOff?.(); delete w.__mcPwOff;
              const host = d.getElementById("mcDialogBox");
              await until(() => !host?.open, 3000);
              out.closed = !host?.open;
              return out;""")
            servers.imap.fail_login = False
            s_ = res.get("seen") or {}
            ok = res.get("host") and s_.get("open") and s_.get("radius") == "14px" and res.get("closed")
            return ok, f"{res}"
        check("Testkonto: falsches Passwort – Nachfrage als Kachel im Fenster, Abbrechen schließt sie", wrong_password, results)

        def openpgp_roundtrip():
            # OpenPGP mit erfundenem Schlüssel: Verfassen mit Verschlüsselung (Knopf aktiv), Mail an sich selbst über den
            # Testserver, zurück in den Posteingang → Leseansicht entschlüsselt sie und zeigt den Hinweis im Mailkopf
            m.cmd("WebDriver:SetTimeouts", {"script": 120000})
            try:
                before = len(servers.smtp.sent)
                res = m.js(r"""
                  const { MailServices } = ChromeUtils.importESModule("resource:///modules/MailServices.sys.mjs");
                  const { RNP } = ChromeUtils.importESModule("chrome://openpgp/content/modules/RNP.sys.mjs");
                  const { EnigmailKeyRing } = ChromeUtils.importESModule("chrome://openpgp/content/modules/keyRing.sys.mjs");
                  const { PgpSqliteDb2 } = ChromeUtils.importESModule("chrome://openpgp/content/modules/sqliteDb.sys.mjs");
                  const acc = MailServices.accounts.getAccount("%s"), id = acc.defaultIdentity;
                  await RNP.init();
                  const keyId = await RNP.genKey("Halo Test <halo@example.invalid>", "ECC", 0, 30, "");
                  EnigmailKeyRing.clearCache();
                  const key = EnigmailKeyRing.getKeyById(keyId);
                  await PgpSqliteDb2.acceptAsPersonalKey(key.fpr);
                  id.setUnicharAttribute("openpgp_key_id", key.keyId);
                  id.setIntAttribute("encryptionpolicy", 2);
                  Services.prefs.setIntPref("extensions.mailcards.undoSend", 0);
                  const params = Cc["@mozilla.org/messengercompose/composeparams;1"].createInstance(Ci.nsIMsgComposeParams);
                  const fields = Cc["@mozilla.org/messengercompose/composefields;1"].createInstance(Ci.nsIMsgCompFields);
                  fields.to = "Halo Test <halo@example.invalid>"; fields.subject = "Halo geheim"; fields.body = "Nur für mich lesbar.";
                  params.type = Ci.nsIMsgCompType.New; params.format = Ci.nsIMsgCompFormat.PlainText; params.composeFields = fields; params.identity = id;
                  MailServices.compose.OpenComposeWindowWithParams(null, params);
                  const cw = await until(() => [...Services.wm.getEnumerator("msgcompose")].find(x => x.document.readyState == "complete" && x.gMsgCompose), 10000);
                  await bis(() => cw.gLoadingComplete, "Verfassen-Fenster fertig geladen", 8000); await until(() => cw.document.getElementById("button-encryption")?.checked, 4000); await ruhig(2500);
                  const btn = cw.document.getElementById("button-encryption");
                  const ccs = el => cw.getComputedStyle(el);
                  const out = { key: !!key, encrypt: !!cw.gSendEncrypted, btn: btn ? { checked: btn.checked || btn.getAttribute("checked") == "true", shown: btn.getBoundingClientRect().width > 0 } : null };
                  // eingeschaltet erkennbar: getönte Kapsel und Symbol in Akzentfarbe (anders als ein gewöhnlicher Knopf)
                  const plain = cw.document.getElementById("button-attach") || cw.document.getElementById("button-contacts");
                  const icon = btn?.querySelector(".toolbarbutton-icon");
                  out.look = btn && { bg: ccs(btn).backgroundColor, plain: plain && ccs(plain).backgroundColor, fill: icon && ccs(icon).fill };
                  // Warnleiste unten (Schlüssel läuft ab) grau statt gelb
                  const warn = await until(() => cw.document.querySelector('#compose-notification-bottom notification-message[type="warning"]'), 4000);
                  out.warn = warn ? warn.shadowRoot?.querySelector(".container") && cw.getComputedStyle(warn.shadowRoot.querySelector(".container")).backgroundColor : null;
                  const bmp = await cw.browsingContext.currentWindowGlobal.drawSnapshot(null, 1, "white");
                  const c = d.createElementNS("http://www.w3.org/1999/xhtml", "canvas"); c.width = bmp.width; c.height = bmp.height; c.getContext("2d").drawImage(bmp, 0, 0);
                  const blob = await new Promise(r => c.toBlob(r)); await IOUtils.write(PathUtils.join(PathUtils.tempDir, "halo-pgp-compose.png"), new Uint8Array(await blob.arrayBuffer()));
                  cw.goDoCommand("cmd_sendNow");
                  out.closed = !!(await until(() => cw.closed, 20000));
                  return out;""" % key)
                for _ in range(40):
                    if len(servers.smtp.sent) > before:
                        break
                    time.sleep(0.5)
                raw = servers.smtp.sent[-1][2] if len(servers.smtp.sent) > before else ""
                encrypted = "BEGIN PGP MESSAGE" in raw or "application/pgp-encrypted" in raw
                if raw:
                    servers.imap.add("INBOX", raw)
                res2 = m.js(r"""
                  const { MailServices } = ChromeUtils.importESModule("resource:///modules/MailServices.sys.mjs");
                  const acc = MailServices.accounts.getAccount("%s"), inbox = acc.incomingServer.rootFolder.getFolderWithFlags(Ci.nsMsgFolderFlags.Inbox);
                  const a3 = await toMail(); a3.displayFolder(inbox.URI);
                  inbox.getNewMessages(w.msgWindow, null);
                  const idx = await until(() => { for (let i = 0; i < (a3.gDBView?.rowCount || 0); i++) if (a3.gDBView.getMsgHdrAt(i).mime2DecodedSubject.includes("geheim") || a3.gDBView.getMsgHdrAt(i).mime2DecodedSubject == "...") return i + 1; return 0; }, 15000);
                  if (!idx) return { found: false };
                  a3.threadTree.selectedIndex = idx - 1; await bis(() => (a3.messageBrowser?.contentDocument?.getElementById("messagepane")?.contentDocument?.body?.textContent || "").includes("Nur für mich lesbar."), "entschlüsselte Mail in der Leseansicht", 10000); await ruhig(4000);
                  const mb = a3.messageBrowser?.contentDocument || a3.document.getElementById("messageBrowser")?.contentDocument;
                  const body = mb?.getElementById("messagepane")?.contentDocument?.body?.textContent || "";
                  const tech = mb?.getElementById("encryptionTechBtn");
                  const out = { found: true, body: body.includes("Nur für mich lesbar."), tech: tech ? { shown: tech.getBoundingClientRect().width > 0, text: tech.textContent.trim() } : null };
                  // ruhige Symbole statt „OpenPGP“ mit bunten Zeichen; markiert: Stern außen, Symbole daneben ohne Überlappung
                  const mcs = el => el.ownerDocument.defaultView.getComputedStyle(el);
                  const label = tech?.querySelector(".crypto-label"), enc = mb?.getElementById("encryptedHdrIcon");
                  out.crypto = { label: label ? mcs(label).display : null, lock: enc && !enc.hidden ? mcs(enc).content : null };
                  const hdr = a3.gDBView.getMsgHdrAt(idx - 1);
                  hdr.folder.markMessagesFlagged([hdr], true); await ruhig(800);
                  const star = mb?.querySelector("#mcHdrMeta .mc-hdr-star");
                  if (star && tech) { const a = star.getBoundingClientRect(), b = tech.getBoundingClientRect();
                    out.crypto.overlap = !(a.right <= b.left || b.right <= a.left || a.bottom <= b.top || b.bottom <= a.top);
                    out.crypto.starRight = a.left >= b.right - 1; out.crypto.rects = [a, b].map(r => [r.left, r.top, r.right, r.bottom].map(Math.round));
                    out.crypto.middle = Math.abs((a.top + a.bottom) / 2 - (b.top + b.bottom) / 2) <= 3; }
                  const bmp = await w.browsingContext.currentWindowGlobal.drawSnapshot(null, 1, "white");
                  const c = d.createElementNS("http://www.w3.org/1999/xhtml", "canvas"); c.width = bmp.width; c.height = bmp.height; c.getContext("2d").drawImage(bmp, 0, 0);
                  const blob = await new Promise(r => c.toBlob(r)); await IOUtils.write(PathUtils.join(PathUtils.tempDir, "halo-pgp-read.png"), new Uint8Array(await blob.arrayBuffer()));
                  hdr.folder.markMessagesFlagged([hdr], false);
                  Services.prefs.clearUserPref("extensions.mailcards.undoSend");
                  return out;""" % key)
            finally:
                m.cmd("WebDriver:SetTimeouts", {"script": 30000})
            t_ = res2.get("tech") or {}
            ok = (res.get("key") and res.get("encrypt") and (res.get("btn") or {}).get("checked") and res.get("closed") and encrypted
                  and res2.get("found") and res2.get("body") and t_.get("shown"))
            lk, cr = res.get("look") or {}, res2.get("crypto") or {}
            yellow = lambda c: bool(c) and (lambda v: len(v) >= 3 and v[0] > 200 and v[1] > 180 and v[2] < 140)([float(x) for x in re.findall(r"[\d.]+", c)])
            ok = (ok and lk.get("bg") and lk.get("bg") != lk.get("plain") and lk.get("fill") not in (None, "none") and not yellow(res.get("warn"))
                  and cr.get("label") == "none" and "mailcards/icons/lock.svg" in (cr.get("lock") or "") and cr.get("overlap") is False and cr.get("starRight") and cr.get("middle"))
            return ok, f"{res} verschlüsselt: {encrypted} {res2}"
        check("Testkonto: OpenPGP – Verfassen verschlüsselt (Schloss erkennbar eingeschaltet, Schlüssel-Hinweis grau), Mail kommt verschlüsselt an, Leseansicht entschlüsselt mit ruhigen Symbolen im Mailkopf", openpgp_roundtrip, results)
    finally:
        try:
            m.js(r"""
              const { MailServices } = ChromeUtils.importESModule("resource:///modules/MailServices.sys.mjs");
              for (const x of [...Services.wm.getEnumerator(null)]) if (!x.location.href.includes("messenger.xhtml")) x.close();
              Services.io.offline = true; await ruhig(300); Services.io.offline = false;
              return 1;""")
        except Exception:
            pass
        servers.close()


def run_checks(m, version, profile, results):
    global SCREEN_W
    # verfügbare Bildschirmbreite (Windows-VM: 1024 px) – einige Breitenprüfungen hängen davon ab
    SCREEN_W = m.js("return w.screen.availWidth;") or 99999
    if sys.platform.startswith("linux"):
        # xvfb: der Zeiger steht unbewegt in der Bildschirmmitte. Erscheint dort ein per Skript (ohne Klick) geöffnetes
        # Menü, schließt GTK es sofort wieder (popuphiding vor popupshown) – im schmalen Terminfenster lagen die Listen der
        # Zeitkarte genau dort; mit echtem Klick bleiben sie offen (CI-Fehlersuche 9.11.2026). Zeiger daher einmal in die
        # Ecke unten rechts, wo kein Menü erscheint
        m.js("""const u = w.windowUtils, s = w.devicePixelRatio;
          u.sendNativeMouseEvent(Math.round((w.screen.width - 1) * s), Math.round((w.screen.height - 1) * s), u.NATIVE_MOUSE_MESSAGE_MOVE ?? 3, 0, 0, w.document.documentElement, null);
          await ruhig(300); return true;""")

    def welcome():
        # Erstinstallation (frisches Profil): einmal die Begrüßung im Info-Fenster – was halo.spaces ändert, wo die
        # Einstellungen liegen; Windows/Linux mit dem Plattform-Hinweis im selben Fenster. Theme bleibt „System“
        res = m.js(r"""
          const hw = await until(() => [...Services.wm.getEnumerator(null)].find(x => x.location?.href.startsWith("resource://mailcards/about/halo.html")
                                                                               && x.document.documentElement.classList.contains("welcome")), 15000);
          const { AddonManager } = ChromeUtils.importESModule("resource://gre/modules/AddonManager.sys.mjs");
          const theme = (await AddonManager.getAddonsByTypes(["theme"])).find(a => a.isActive)?.id;
          if (!hw) return { window: false, theme, shown: Services.prefs.getBoolPref("extensions.mailcards.welcomeShown", false) };
          await ruhig(400); const hd = hw.document, vis = id => { const e = hd.getElementById(id); return !!e && e.getBoundingClientRect().height > 0; };
          const out = { window: true, theme, title: hd.querySelector("h1").textContent, lines: hd.querySelectorAll("#platform-note .line").length,
                        text: hd.getElementById("platform-note").textContent, buttons: ["settings", "close", "update", "feedback", "donate"].filter(vis),
                        overflow: hd.documentElement.scrollHeight - hw.innerHeight, shown: Services.prefs.getBoolPref("extensions.mailcards.welcomeShown", false),
                        note: Services.prefs.getBoolPref("extensions.mailcards.platformNoteShown", false),
                        windows: [...Services.wm.getEnumerator(null)].filter(x => x.location?.href.startsWith("resource://mailcards/about/halo.html")).length };
          hd.getElementById("close").click(); await ruhig(400);
          out.closed = ![...Services.wm.getEnumerator(null)].some(x => x.location?.href.startsWith("resource://mailcards/about/halo.html"));
          return out;""")
        mac = sys.platform == "darwin"
        ok = (res["window"] and res["title"] == "Welcome to halo.spaces" and "calm and tidy." in res["text"] and " – " not in res["text"]
              and res["buttons"] == ["settings", "close"] and res["overflow"] <= 0 and res["shown"] and res["windows"] == 1
              and res["lines"] == (1 if mac else 2) and ("made for macOS" in res["text"]) != mac and res["note"] != mac
              and res["theme"] == "default-theme@mozilla.org" and "follow your system" not in res["text"] and res["closed"])
        return ok, f"{res}"
    check("Begrüßung: einmal nach der Erstinstallation (kurz, Win/Linux mit Plattform-Hinweis), Theme bleibt System", welcome, results)

    def selector_guard():
        # Selektor-Wächter (Anlass GitHub-Issue #15, Thunderbird 159): die Elemente von Thunderbird, an denen
        # halo.spaces am häufigsten hängt, gibt es in dieser Version noch – je Dokument (Hauptfenster, Mailbereich,
        # Mailansicht, Adressbuch). Fehlt eines, nennt die Prüfung es; die CI testet damit Release, Beta und ESR
        res = m.js(r"""
          await toMail(); await ruhig(600);
          const want = {
            main: ["tabmail", "tabmail-container", "unifiedToolbarContainer", "unifiedToolbarContent", "spacesToolbar", "spacesPinnedButton",
                   "status-bar", "mainPopupSet", "today-pane-panel", "agenda", "calSidebar", "calendar-task-tree", "calendar-task-details-container",
                   "calendar-task-view-splitter", "task-tree-filtergroup", "task-actions-toolbar", "calendar-list", "calendarListHeader",
                   "calendar-list-inner-pane", "list-calendars-context-menu", "menu_FilePopup", "menu_View_Popup", "messageMenuPopup", "menu_HelpPopup",
                   "settingsButton", "multiweek-view", "month-view"],
            about3pane: ["folderPane", "folderTree", "folderPaneSplitter", "threadPane", "threadTree", "messageBrowser", "folderPaneContext",
                         "mailContext"],
            aboutMessage: ["messageHeader", "messagepanebox", "messagepane", "attachmentView", "attachmentList", "attachmentBar", "attachment-splitter"],
            toolbarItems: ["search-bar", "write-message", "get-messages", "reply", "reply-all", "forward-inline", "archive", "delete", "junk", "move-to", "mark-as"],
            addressBook: ["booksPane", "booksSplitter", "cardsPane", "detailsPane", "sharedSplitter"],
          };
          const missing = {};
          const look = (key, doc, list) => { const m = list.filter(id => !doc?.getElementById(id)); if (m.length) missing[key] = m; };
          look("main", d, want.main);
          const a3 = tm.currentAbout3Pane; look("about3pane", a3?.document, want.about3pane);
          look("aboutMessage", a3?.document.getElementById("messageBrowser")?.contentDocument, want.aboutMessage);
          const ids = [...d.querySelectorAll("#unifiedToolbarContent > li[item-id]")].map(li => li.getAttribute("item-id"));
          const mi = want.toolbarItems.filter(i => !ids.includes(i)); if (mi.length) missing.toolbarItems = mi;
          tm.openTab("addressBookTab", {}); await ruhig(1500);
          look("addressBook", tm.currentTabInfo.browser?.contentDocument, want.addressBook);
          for (const t of [...tm.tabInfo].slice(1)) tm.closeTab(t);
          await toMail();
          return { missing, n: Object.values(want).flat().length };""")
        return not res.get("missing"), f"{res}"
    check("Selektor-Wächter: die wichtigsten Elemente von Thunderbird (Hauptfenster, Mailbereich, Mailansicht, Toolbar, Adressbuch) gibt es in dieser Version", selector_guard, results)

    def pst_read_guard():
        # Outlook-Datendatei (PST) öffnen: eine Datei, an der die Bibliothek scheitert, hält Thunderbird nicht mehr an
        # (vorher endlos im Hauptprozess, Absturz mit einer PST aus Office 365) – Fehler sofort, „keine PST“ von
        # „PST, aber nicht lesbar“ unterschieden; mit der privaten Beispieldatei des Maintainers, wenn sie da ist (nur neon):
        # sie muss gelesen werden, mit Ordnern und Mails (PST aus Microsoft 365, Tabellenkopf nicht an HID 0x20)
        priv = os.path.expanduser("~/halo-aufgaben/testdaten/text_pst_export.pst")
        res = m.js(r"""
          // absichtlich: die Bibliothek scheitert an kaputten bzw. nicht lesbaren Dateien, unser Code protokolliert das
          erwartet(/pst folder error|PSTNodeInputStream|PSTInputStream/);
          const dir = PathUtils.tempDir, junk = PathUtils.join(dir, "halo-kein.pst"), head = PathUtils.join(dir, "halo-kaputt.pst");
          await IOUtils.write(junk, new TextEncoder().encode("keine Outlook-Datei"));
          const bytes = new Uint8Array(4096); bytes.set([0x21, 0x42, 0x44, 0x4e]); await IOUtils.write(head, bytes);
          const out = {};
          const tryRead = path => { const t0 = Date.now(); try { const r = w.__mcPstRead(path); return { ok: true, folders: r.folders.length, total: r.total, ms: Date.now() - t0 }; }
            catch (e) { return { ok: false, ms: Date.now() - t0 }; } };
          out.junk = { ...tryRead(junk), pst: w.__mcPstIsPst(junk) };
          out.head = { ...tryRead(head), pst: w.__mcPstIsPst(head) };
          const priv = %s;
          if (priv && await IOUtils.exists(priv)) out.priv = { ...tryRead(priv), pst: w.__mcPstIsPst(priv) };
          await IOUtils.remove(junk); await IOUtils.remove(head);
          return out;""" % json.dumps(priv if os.path.exists(priv) else None))
        j, h, p_ = res.get("junk") or {}, res.get("head") or {}, res.get("priv")
        ok = (j.get("ok") is False and j.get("pst") is False and h.get("ok") is False and h.get("pst") is True
              and all(x.get("ms", 1e9) < 10000 for x in (j, h)) and (p_ is None or (p_.get("ms", 1e9) < 10000 and p_.get("pst") and p_.get("ok") is True
                                  and p_.get("folders", 0) > 0 and (p_.get("total") or 0) > 0)))
        return ok, f"{res}"
    check("Import: Outlook-PST – nicht lesbare Datei hält Thunderbird nicht an (Fehler sofort), „keine PST“ und „PST, aber nicht lesbar“ unterschieden", pst_read_guard, results)

    def pst_import_mail():
        # Outlook-Datendatei importieren (Reihe PST 2/3): Mails als Kopie nach Lokale Ordner/<Datei> mit Ordnerbaum, Betreff
        # mit Umlauten, gelesen/markiert und Anhang; ein zweiter Import legt nichts doppelt an (Message-ID); der Assistent
        # zeigt Ordner mit Anzahl, Fortschritt und Abschluss. Die CI hat keine PST: erfundene Daten gehen denselben Weg wie die
        # aus der Datei (Lesen aus der Datei prüfen die Logik-Tests und HALO_PST=<Datei> zusätzlich hier)
        real = os.environ.get("HALO_PST") or ""
        res = m.js(r"""
          const { MailServices } = ChromeUtils.importESModule("resource:///modules/MailServices.sys.mjs");
          const { MsgHdrToMimeMessage } = ChromeUtils.importESModule("resource:///modules/gloda/MimeMessage.sys.mjs");
          const mk = (i, extra = {}) => ({ subject: `PST-Probe ${i} Grüße`, date: new Date(Date.UTC(2026, 9, i, 10)),
            from: { name: "Dora Müller", email: "dora@example.invalid" }, to: [{ name: "Halo Test", email: "halo@example.invalid" }],
            text: `Text ${i}`, messageId: `pst-probe-${i}@example.invalid`, read: (i & 1) == 0, flagged: i == 1, ...extra });
          const source = () => ({ name: "Halo PST-Probe", mail: [
            { name: "Posteingang", count: 3, depth: 0, path: ["Posteingang"], items: [mk(1, { html: "<p>Hallo <b>1</b></p>",
              attachments: [{ name: "Rechnung.txt", type: "text/plain", data: new TextEncoder().encode("Summe 42") }] }), mk(2), mk(3)] },
            { name: "Projekte", count: 0, depth: 0, path: ["Projekte"], items: [] },
            { name: "2026/Q4", count: 1, depth: 1, path: ["Projekte", "2026/Q4"], items: [mk(4)] } ] });
          const first = await w.__mcPstImport(source());
          const second = await w.__mcPstImport(source());
          const local = MailServices.accounts.localFoldersServer.rootFolder;
          const target = local.getChildNamed("Halo PST-Probe");
          const inbox = target?.getChildNamed("Posteingang"), q4 = target?.getChildNamed("Projekte")?.getChildNamed("2026-Q4");
          const hdrs = inbox ? [...inbox.msgDatabase.enumerateMessages()] : [];
          const h1 = hdrs.find(h => h.messageId == "pst-probe-1@example.invalid");
          const atts = h1 ? await Promise.race([new Promise(r => MsgHdrToMimeMessage(h1, null, (h, mm) => r(mm ? mm.allUserAttachments.map(a => a.name) : null), true)), wait(8000)]) : null;
          const out = { first: { copied: first?.copied, skipped: first?.skipped, failed: first?.failed }, second: { copied: second?.copied, skipped: second?.skipped },
            inbox: inbox?.getTotalMessages(false), q4: q4?.getTotalMessages(false),
            mails: Object.fromEntries(hdrs.map(h => [h.mime2DecodedSubject, [h.isRead, h.isFlagged]])), from: h1?.mime2DecodedAuthor, atts };
          // Import-Assistent (File → Import…): eigene Auswahl in Schritt 1, Ordner mit Anzahl und Häkchen (Schritt 2),
          // Ziel und Übersicht (Schritt 3), Import (alles schon da) mit Abschluss; Menü File ohne eigenen PST-Punkt
          out.menu = !!w.document.getElementById("mcFileImportPst");
          const cw = await w.__mcPstWizard(source());
          const doc = cw?.document;
          if (doc) {
            const vis = e => !!e && !e.closest("[hidden]") && e.getBoundingClientRect().height > 0;
            const pane = doc.getElementById("tabPane-halopst");
            const rows = () => [...doc.querySelectorAll("#halopst-items .mc-pst-folders > label")];
            out.wiz = { sources: [...doc.querySelectorAll("#start-sources input[name=appSource]")].map(i => i.value),
              choice: [...doc.querySelectorAll("#mcPstSource p")].map(p => p.textContent),
              items: vis(doc.getElementById("halopst-items")), start: vis(doc.getElementById("tabPane-start")),
              folders: rows().map(r => r.querySelector(".mc-pst-name").textContent), nums: rows().map(r => r.querySelector(".mc-pst-count").textContent),
              checked: rows().map(r => r.querySelector("input").checked), indent: rows().map(r => r.getBoundingClientRect().left),
              file: doc.querySelector("#halopst-items .mc-pst-file")?.textContent, steps: doc.querySelectorAll("#stepNav li").length };
            pane.querySelector("footer .continue").click();
            await until(() => vis(doc.getElementById("halopst-summary")), 5000);
            out.wiz.sum = { dest: doc.querySelector(".mc-pst-dest")?.textContent, list: [...doc.querySelectorAll("#halopst-summary .summary-items li")].map(l => l.textContent),
              confirm: doc.getElementById("navConfirm")?.classList.contains("current"), start: vis(doc.querySelector("#halopst-summary .before-progress")) };
            doc.querySelector("#halopst-summary .before-progress").click();
            await until(() => pane.classList.contains("complete"), 30000);
            out.wiz.end = { result: pane.dataset.result, report: doc.querySelector(".mc-pst-report")?.textContent,
              finish: vis(doc.querySelector("#halopst-summary .progressFinish.primary")), bar: doc.querySelector("#halopst-summary progress")?.value };
            cw.close();
          }
          // echte Datei (nur von Hand mit HALO_PST): Anzahl je Ordner wie in der Datei
          const real = %s;
          if (real) {
            const { source: rs, close } = w.__mcPstSource(real);
            try {
              const job = await w.__mcPstImport(rs);
              out.real = { copied: job?.copied, failed: job?.failed, folders: rs.mail.map(f => [f.path.join("/"), f.count,
                job?.done.find(d => d.path.join("/") == f.path.join("/"))?.dest.getTotalMessages(false)]) };
            } finally { close(); }
            try { local.propagateDelete(local.getChildNamed(rs.name), true); } catch {}
          }
          // aufräumen: leere Lokale Ordner bleiben in der Ordnerliste ausgeblendet
          try { target && local.propagateDelete(target, true); } catch (e) { out.cleanup = String(e); }
          return out;""" % json.dumps(real))
        mails, wiz = res.get("mails") or {}, res.get("wiz") or {}
        end = wiz.get("end") or {}
        ok = (res.get("first", {}).get("copied") == 4 and not res["first"].get("failed") and res.get("second", {}).get("copied") == 0
              and res["second"].get("skipped") == 4 and res.get("inbox") == 3 and res.get("q4") == 1
              and mails.get("PST-Probe 1 Grüße") == [False, True] and mails.get("PST-Probe 2 Grüße") == [True, False]
              and mails.get("PST-Probe 3 Grüße") == [False, False] and "Dora Müller" in (res.get("from") or "")
              and res.get("atts") == ["Rechnung.txt"]
              and res.get("menu") is False
              and wiz.get("sources", [])[-2:] == ["halo-pst", "file"]
              and wiz.get("choice") == ["Import from an Outlook data file (PST)", "Import messages, contacts, and calendars from an Outlook data file (PST)."]
              and wiz.get("items") and not wiz.get("start") and wiz.get("file") == "Halo PST-Probe.pst" and wiz.get("steps", 0) >= 3
              and wiz.get("folders") == ["Posteingang", "Projekte", "2026/Q4"] and wiz.get("checked") == [True] * 3
              and wiz.get("nums") == ["3", "0", "1"] and wiz.get("indent", [0, 0, 0])[2] > wiz.get("indent", [0, 0, 0])[1]
              and (wiz.get("sum") or {}).get("dest", "").endswith("/Halo PST-Probe") and (wiz.get("sum") or {}).get("list") == ["4 messages in 3 folders"]
              and (wiz.get("sum") or {}).get("confirm") and (wiz.get("sum") or {}).get("start")
              and end.get("result") == "done" and end.get("finish") and end.get("bar") == 1
              and "4 messages were already there" in (end.get("report") or ""))
        if real:
            r = res.get("real") or {}
            ok = ok and r.get("folders") and all(c == d for _, c, d in r["folders"]) and not r.get("failed")
        return ok, f"{res}"
    check("Import: Outlook-PST – Mails als Kopie in Lokale Ordner mit Ordnerbaum, Betreff, gelesen/markiert und Anhang, zweiter Import ohne Duplikate, im Import-Assistenten eigene Quelle mit Ordnern, Anzahl und Häkchen, Ziel, Abschluss; Menü File ohne eigenen PST-Punkt", pst_import_mail, results)

    def pst_import_contacts_calendar():
        # Outlook-Datendatei importieren (Reihe PST 3/3): Kontakte als neues Adressbuch und Termine/Aufgaben als neuer lokaler
        # Kalender mit dem Namen der Datei, je als Kopie; zweiter Import ohne Duplikate (UID); im Assistenten die Auswahl der
        # Teile (Mail, Kontakte, Kalender) – hier nur Kontakte und Kalender gewählt, die Mailordner bleiben unberührt
        res = m.js(r"""
          const { MailServices } = ChromeUtils.importESModule("resource:///modules/MailServices.sys.mjs");
          const name = "Halo PST-Kontakte";
          const day = (d, h = 9) => new Date(Date.UTC(2026, 10, d, h));
          const source = () => ({ name,
            mail: [{ name: "Posteingang", count: 1, depth: 0, path: ["Posteingang"], items: [{ subject: "Nur Mail", text: "x", messageId: "pst-kc-1@example.invalid" }] }],
            contacts: [{ name: "Kontakte", count: 2, items: [
              { uid: "aaaaaaaa-0000-4000-8000-000000000001", first: "Dora", last: "Müller", emails: ["dora@example.invalid"], org: "Halo", phones: [["cell", "+43 660 1"]],
                birthday: new Date(Date.UTC(1980, 4, 3, 23)) },
              { uid: "aaaaaaaa-0000-4000-8000-000000000002", display: "Erik Probe", emails: ["erik@example.invalid"] }] }],
            calendar: [{ name: "Kalender", count: 3, items: [
              { uid: "pst-kc-ev-1", summary: "Besprechung PST", start: day(18), end: day(18, 10), location: "Wien" },
              { uid: "pst-kc-ev-2", summary: "Feiertag PST", allDay: true, start: day(19, 0), end: day(20, 0) },
              { uid: "pst-kc-task-1", task: true, summary: "Aufgabe PST", due: day(21, 0), done: false }] }] });
          const first = await w.__mcPstImport(source(), { contacts: true, calendar: true });
          const second = await w.__mcPstImport(source(), { contacts: true, calendar: true });
          const book = MailServices.ab.directories.find(d => d.dirName == name);
          const calendar = cal.manager.getCalendars().find(c => c.name == name);
          const cards = book ? book.childCards : [];
          const dora = cards.find(c => c.primaryEmail == "dora@example.invalid");
          const calItems = calendar ? await Promise.all(["pst-kc-ev-1", "pst-kc-ev-2", "pst-kc-task-1"].map(u => calendar.getItem(u))) : [];
          const out = { first: { contacts: first?.contacts, events: first?.events }, second: { contacts: second?.contacts, events: second?.events },
            book: !!book, cards: cards.length, dora: dora && [dora.displayName, String(dora.vCardProperties?.getFirstValue("org") ?? ""), dora.vCardProperties?.getFirstValue("bday")],
            calType: calendar?.type, items: calItems.map(i => i && [i.title, "dueDate" in i ? "task" : "event", i.startDate?.isDate ?? null, i.getProperty?.("LOCATION") || null]) };
          // Import-Assistent: Mailordner und Kontakte/Kalender zur Auswahl; nur Kontakte und Kalender importieren (alles schon da),
          // ohne Häkchen ist „Continue“ gesperrt, Mailordner bleiben unberührt
          const cw = await w.__mcPstWizard(source());
          const doc = cw?.document;
          if (doc) {
            const pane = doc.getElementById("tabPane-halopst");
            const next = pane.querySelector("footer .continue");
            const label = l => [l.querySelector(".mc-pst-name").textContent, l.querySelector(".mc-pst-count").textContent].join(" ");
            out.wiz = { parts: [...doc.querySelectorAll(".mc-pst-parts > label")].map(label), folders: [...doc.querySelectorAll(".mc-pst-folders > label")].map(label) };
            const all = [...doc.querySelectorAll("#halopst-items input[type=checkbox]")];
            all.forEach(b => b.checked && b.click());
            out.wiz.noneBlocked = next.disabled;
            all.filter(b => b.dataset.part).forEach(b => b.click());
            out.wiz.partsOk = !next.disabled;
            next.click();
            await until(() => !doc.getElementById("halopst-summary").hidden, 5000);
            out.wiz.list = [...doc.querySelectorAll("#halopst-summary .summary-items li")].map(l => l.textContent);
            doc.querySelector("#halopst-summary .before-progress").click();
            await until(() => pane.classList.contains("complete"), 30000);
            out.wiz.end = doc.querySelector(".mc-pst-report")?.textContent;
            try { out.wiz.localMail = !!MailServices.accounts.localFoldersServer.rootFolder.getChildNamed(name); } catch { out.wiz.localMail = false; }
            cw.close();
          }
          // aufräumen
          try { book && MailServices.ab.deleteAddressBook(book.URI); } catch (e) { out.cleanup = String(e); }
          try { calendar && cal.manager.removeCalendar(calendar); } catch (e) { out.cleanup = String(e); }
          return out;""")
        f, s = res.get("first") or {}, res.get("second") or {}
        wiz = res.get("wiz") or {}
        items = res.get("items") or []
        ok = (f.get("contacts", {}).get("added") == 2 and f.get("events", {}).get("added") == 3
              and s.get("contacts", {}).get("added") == 0 and s.get("contacts", {}).get("skipped") == 2
              and s.get("events", {}).get("added") == 0 and s.get("events", {}).get("skipped") == 3
              and res.get("cards") == 2 and (res.get("dora") or [None])[0] == "Dora Müller" and (res.get("dora") or [None, None])[1] == "Halo"
              and str((res.get("dora") or [None] * 3)[2] or "").replace("-", "") == "19800504" and res.get("calType") == "storage"
              and len(items) == 3 and all(items) and items[0][:2] == ["Besprechung PST", "event"] and items[0][3] == "Wien"
              and items[1][:3] == ["Feiertag PST", "event", True] and items[2][:2] == ["Aufgabe PST", "task"]
              and wiz.get("parts") == ["Contacts 2", "Calendar 3"] and wiz.get("folders") == ["Posteingang 1"]
              and wiz.get("noneBlocked") and wiz.get("partsOk") and wiz.get("list") == ["2 contacts", "3 events and tasks"]
              and "2 contacts were already there" in (wiz.get("end") or "") and "3 events and tasks were already there" in (wiz.get("end") or "")
              and "messages imported" not in (wiz.get("end") or "") and not wiz.get("localMail"))
        return ok, f"{res}"
    check("Import: Outlook-PST – Kontakte als eigenes Adressbuch, Termine und Aufgaben als eigener Kalender, zweiter Import ohne Duplikate, Auswahl der Teile und Ordner im Import-Assistenten", pst_import_contacts_calendar, results)

    def pst_import_recurring():
        # Serientermine aus der Outlook-Datendatei kommen als Serie an (vorher nur der erste Termin): wöchentlich Mo 09:00–10:30
        # über die Umstellung auf Winterzeit bis 30.11., ein Termin gelöscht – jeder Termin um 09:00 in der eingestellten Zone;
        # Geburtstag im Kalender jährlich ganztägig. Das Lesen der Outlook-Struktur prüfen die Logik-Tests (tests/logik/pst.test.mjs)
        res = m.js(r"""
          const name = "Halo PST-Serie";
          const source = { name, mail: [], contacts: [], calendar: [{ name: "Kalender", count: 2, items: [
            { uid: "pst-rec-1", summary: "Jour fixe PST", start: new Date(Date.UTC(2026, 9, 19, 7)),
              recur: { rule: "FREQ=WEEKLY;INTERVAL=1;BYDAY=MO;WKST=MO", day: "20261019", startMin: 540, endMin: 630, count: 0, until: "20261130", exdays: ["20261109"] } },
            { uid: "pst-rec-2", summary: "Geburtstag PST", allDay: true, start: null,
              recur: { rule: "FREQ=YEARLY;INTERVAL=1;BYMONTH=5;BYMONTHDAY=3", day: "19800503", startMin: 0, endMin: 1440, count: 0, until: "", exdays: [] } }] }] };
          const job = await w.__mcPstImport(source, { calendar: true });
          const calendar = cal.manager.getCalendars().find(c => c.name == name);
          const out = { events: job?.events, tz: cal.dtz.defaultTimezone?.tzid };
          if (calendar) {
            const dt = s => cal.createDateTime(s);
            const occ = async (uid, a, b) => {
              const item = await calendar.getItem(uid);
              return item?.recurrenceInfo ? item.recurrenceInfo.getOccurrences(dt(a), dt(b), 0) : [];
            };
            const local = d => d.getInTimezone(cal.dtz.defaultTimezone);
            const fmt = d => { const l = local(d); return `${l.year}-${l.month + 1}-${l.day} ${l.hour}:${String(l.minute).padStart(2, "0")}`; };
            const weekly = await occ("pst-rec-1", "20261001T000000Z", "20270101T000000Z");
            out.weekly = weekly.map(o => fmt(o.startDate));
            out.weeklyEnd = weekly.map(o => fmt(o.endDate));
            const bday = await occ("pst-rec-2", "20260101T000000Z", "20280101T000000Z");
            out.bday = bday.map(o => [o.startDate.isDate, o.startDate.year, o.startDate.month + 1, o.startDate.day]);
            cal.manager.removeCalendar(calendar);
          }
          return out;""")
        ev = res.get("events") or {}
        ok = (ev.get("added") == 2 and not ev.get("failed")
              and res.get("weekly") == ["2026-10-19 9:00", "2026-10-26 9:00", "2026-11-2 9:00", "2026-11-16 9:00", "2026-11-23 9:00", "2026-11-30 9:00"]
              and all(e.endswith(" 10:30") for e in res.get("weeklyEnd") or [""])
              and res.get("bday") == [[True, 2026, 5, 3], [True, 2027, 5, 3]])
        return ok, f"{res}"
    check("Import: Outlook-PST – Serientermine als Serie (wöchentlich über die Zeitumstellung zur selben Uhrzeit, gelöschter Termin fehlt, Ende nach Datum; Geburtstag jährlich ganztägig)", pst_import_recurring, results)

    def halo_window_closes_with_main():
        # Fenster „halo.spaces“ (Begrüßung, Hilfe → halo.spaces…) schließt mit seinem Hauptfenster – sonst lief
        # Thunderbird unter Windows/Linux nach dem Schließen des Hauptfensters weiter (GitHub-Issue #15).
        # Nachgestellt mit einem zweiten Hauptfenster, das erste bleibt offen
        res = m.js(r"""
          const { ExtensionParent } = ChromeUtils.importESModule("resource://gre/modules/ExtensionParent.sys.mjs");
          const g = ExtensionParent.GlobalManager.getExtension("%s").experimentAPIManager.global;
          const halo = () => [...Services.wm.getEnumerator(null)].find(x => x.location?.href.startsWith("resource://mailcards/about/halo.html"));
          halo()?.close(); await ruhig(300);
          const second = w.openDialog("chrome://messenger/content/messenger.xhtml", "_blank", "chrome,all,dialog=no");
          await until(() => second.document.readyState == "complete" && second.document.getElementById("tabmail")?.currentTabInfo, 15000);
          await ruhig(1500);
          g.__mcSecond = second;
          Cu.evalInSandbox("enhancer.openHaloWindow(globalThis.__mcSecond)", g);
          const hw = await until(() => halo(), 8000);
          const out = { opened: !!hw };
          second.close();
          out.closed = !!(await until(() => !halo() || halo().closed, 5000));
          out.mainOpen = !w.closed;
          delete g.__mcSecond;
          halo()?.close();
          return out;""" % ADDON_ID)
        return res.get("opened") and res.get("closed") and res.get("mainOpen"), f"{res}"
    check("halo.spaces-Fenster schließt mit seinem Hauptfenster (Thunderbird lässt sich unter Windows/Linux beenden)", halo_window_closes_with_main, results)

    def welcome_steps():
        # Begrüßung schrittweise (KISS): Wetter und Chat erst nur Ja/Nein; Ja beim Wetter bzw. Nein beim Chat lässt die
        # Einzelheiten aufgleiten und das Fenster wächst mit; Stadt mit Vorschlägen beim Tippen; keine Gedankenstriche
        res = m.js(r"""
          const { ExtensionParent } = ChromeUtils.importESModule("resource://gre/modules/ExtensionParent.sys.mjs");
          const g = ExtensionParent.GlobalManager.getExtension("%s").experimentAPIManager.global;
          const halo = () => [...Services.wm.getEnumerator(null)].find(x => x.location?.href.startsWith("resource://mailcards/about/halo.html"));
          halo()?.close(); await ruhig(300);
          Cu.evalInSandbox(`globalThis.__mcRealFetch = fetchWithTimeout;
            fetchWithTimeout = async (win, url) => {
              const body = url.includes("geocoding") ? { results: [{ name: "Wien", country: "Österreich", latitude: 48.20849, longitude: 16.37208 }] }
                : { current: { weather_code: 1, is_day: 1, temperature_2m: 12.3 } };
              return { ok: true, status: 200, text: async () => JSON.stringify(body) }; };
            enhancer.openHaloWindow(Services.wm.getMostRecentWindow("mail:3pane"), { welcome: true });`, g);
          const out = {};
          try {
            const hw = await until(() => { const x = halo(); return x?.document.getElementById("fifth") && x; }, 8000);
            if (!hw) return { window: false };
            await ruhig(600);
            const hd = hw.document, P = "extensions.mailcards.";
            const btn = (sec, text) => [...hd.querySelectorAll(`#${sec} button`)].find(b => b.textContent == text);
            const isOpen = sec => hd.querySelector(`#${sec} .more`).classList.contains("open") && hd.querySelector(`#${sec} .more`).getBoundingClientRect().height > 10;
            const shut = sec => hd.querySelector(`#${sec} .more`).getBoundingClientRect().height < 1;
            const fits = () => hd.documentElement.scrollHeight - hw.innerHeight <= 1;
            out.start = { h: hw.innerHeight, weatherShut: shut("weather"), fifthShut: shut("fifth"), dashes: hd.body.textContent.includes(" – "),
                          chatChosen: btn("fifth", "Yes")?.classList.contains("chosen") };
            // auf den Endzustand warten statt fest 700 ms: gilt die Begrüßung als verdeckt (visibilityState hidden, auf dem
            // Testrechner nach dem Ein- oder Zuklappen), laufen Übergänge und requestAnimationFrame stark gedrosselt
            const done = (f, h0) => until(() => f() && fits() && (h0 == null || hw.innerHeight != h0), 10000).then(() => ruhig(200));
            btn("weather", "Yes").click(); await done(() => isOpen("weather"), out.start.h);
            out.weatherYes = { open: isOpen("weather"), h: hw.innerHeight, fits: fits() };
            btn("weather", "City …").click(); await ruhig(300);
            const input = hd.querySelector("#weather .city input"); input.value = "Wi"; input.dispatchEvent(new hw.Event("input"));
            await until(() => hd.querySelector("#weather .suggest:not([hidden]) .suggestion"), 3000); await ruhig(300);
            const sug = [...hd.querySelectorAll("#weather .suggestion")];
            out.suggest = { labels: sug.map(b => b.textContent), fits: fits() };
            sug[0]?.click(); await ruhig(800);
            out.chosen = { on: Services.prefs.getBoolPref(P + "weather", false), place: Services.prefs.getStringPref(P + "weatherPlace", ""),
                           status: hd.querySelector("#weather .status").textContent };
            const hOpen = hw.innerHeight; btn("weather", "No").click(); await done(() => shut("weather"), hOpen);
            out.weatherNo = { shut: shut("weather"), on: Services.prefs.getBoolPref(P + "weather", false), h: hw.innerHeight, fits: fits() };
            btn("fifth", "No").click(); await done(() => isOpen("fifth"));
            out.chatNo = { open: isOpen("fifth"), mode: Services.prefs.getStringPref(P + "fifthSpace", "chat"),
                           nothing: btn("fifth", "Nothing")?.classList.contains("chosen"), choices: [...hd.querySelectorAll("#fifth .choices:not(.yesno) button")].map(b => b.textContent), fits: fits() };
            btn("fifth", "Website …").click(); await ruhig(300);
            const url = hd.querySelector("#fifth .city input"); url.value = "kalender.example.com"; btn("fifth", "OK").click(); await ruhig(300);
            out.web = { mode: Services.prefs.getStringPref(P + "fifthSpace", ""), url: Services.prefs.getStringPref(P + "fifthSpaceUrl", "") };
            btn("fifth", "Yes").click(); await done(() => shut("fifth"));
            out.chatYes = { shut: shut("fifth"), mode: Services.prefs.getStringPref(P + "fifthSpace", "chat"), fits: fits() };
            out.endDashes = hd.body.textContent.includes(" – ");
            hw.close();
          } finally {
            Cu.evalInSandbox("fetchWithTimeout = __mcRealFetch;", g);
            for (const p of ["weather", "weatherPlace", "weatherState", "fifthSpace", "fifthSpaceUrl"]) Services.prefs.clearUserPref("extensions.mailcards." + p);
          }
          return out;""" % ADDON_ID)
        if res.get("window") is False:
            return False, f"{res}"
        st, wy, sg, ch, wn, cn, wb, cy = (res.get(k) or {} for k in ("start", "weatherYes", "suggest", "chosen", "weatherNo", "chatNo", "web", "chatYes"))
        ok = (st.get("weatherShut") and st.get("fifthShut") and not st.get("dashes") and st.get("chatChosen")
              and wy.get("open") and wy.get("h", 0) > st.get("h", 0) and wy.get("fits")
              and sg.get("labels") == ["Wien, Österreich"] and ch.get("on") and ch.get("place") == "Wien, Österreich" and "Wien" in (ch.get("status") or "")
              and wn.get("shut") and not wn.get("on") and wn.get("h", 999) < wy.get("h", 0) and wn.get("fits")
              and cn.get("open") and cn.get("mode") == "none" and cn.get("nothing") and cn.get("choices") == ["Website …", "Add-on", "Nothing"]
              and wb.get("mode") == "web" and wb.get("url") == "https://kalender.example.com/"
              and cy.get("shut") and cy.get("mode") == "chat" and not res.get("endDashes"))
        return ok, f"{res}"
    check("Begrüßung schrittweise: Wetter und Chat erst Ja/Nein, Einzelheiten gleiten auf, Fenster wächst mit; Stadt mit Vorschlägen", welcome_steps, results)


    # Vorbereitung: Fenstergröße, Testkalender, Fenster ohne Dialoge
    m.js("""
      for (const x of [...Services.wm.getEnumerator(null)]) if (!x.location.href.includes("messenger.xhtml")) x.close();
      w.moveTo(0, 0); w.resizeTo(1500, 900); await wait(500);
      // Marionette sperrt Add-on-Updates – für die Prüfung „Updates beim Start“ erlauben. Die Update-Liste
      // (updates.json auf GitHub) bleibt im Testprofil aber unerreichbar: ein veröffentlichtes Update
      // ersetzte sonst mitten im Lauf Design und Logik des geprüften Pakets
      Services.obs.addObserver({ observe(ch) { ch.QueryInterface(Ci.nsIHttpChannel);
        if (/\\/updates\\.json(\\?|$)/.test(ch.URI.spec)) ch.cancel(Cr.NS_ERROR_ABORT); } }, "http-on-modify-request");
      Services.prefs.setBoolPref("extensions.update.enabled", true);
      if (!testCalendar()) { const c = cal.manager.createCalendar("storage", Services.io.newURI("moz-storage-calendar://")); c.name = "Halo Test"; c.setProperty("color", "#FF9500"); cal.manager.registerCalendar(c); }
      return 1;""")

    # (nach der Vorbereitung: sie erlaubt Add-on-Updates, bevor die Prüfung beim Start nach 20 s läuft)
    def today_everywhere():
        # Today-Pane in allen Bereichen außer dem Kalender, nach der Erstinstallation überall eingeblendet
        # (frisches Testprofil = Erstinstallation); im Kalender aus und ihr Schalter dort gesperrt
        res = m.js(r"""
          const panel = d.getElementById("today-pane-panel"), cmd = d.getElementById("calendar_toggle_todaypane_command");
          const shown = () => !!panel && !panel.collapsed && panel.getBoundingClientRect().width > 0;
          // überall gleich wie in der Mail: ohne Aufgabenteil, Termine bis unten
          const look = () => { const todo = d.getElementById("todo-tab-panel"), ag = d.getElementById("agenda-panel");
            return { todo: !!todo && todo.getBoundingClientRect().height > 0, agendaH: Math.round(ag?.getBoundingClientRect().height || 0) }; };
          const looks = {};
          const out = { looks, modes: panel.getAttribute("mode"), collapsed: panel.getAttribute("collapsedinmodes"),
                        pref: Services.prefs.getBoolPref("extensions.mailcards.todayPaneEverywhere", false) };
          await toMail(); await ruhig(800); out.mail = shown(); looks.mail = look();
          tm.openTab("tasks", {}); await ruhig(1200); out.tasks = shown(); looks.tasks = look();
          tm.openTab("addressBookTab", {}); await ruhig(2000); out.addressbook = [shown(), w.gCurrentMode]; looks.addressbook = look();
          w.openPreferencesTab("paneGeneral"); await ruhig(2000); out.settings = shown(); looks.settings = look();
          tm.openTab("chat", {}); await ruhig(1500); out.chat = shown(); looks.chat = look();
          await toCalendar(); await ruhig(1200); out.calendar = [shown(), !!cmd?.disabled];
          for (const t of [...tm.tabInfo].slice(1)) tm.closeTab(t);
          await toMail(); await ruhig(600);
          return out;""")
        ok = (res["pref"] and "special" in res["modes"] and "calendar" not in res["modes"].split(",")
              and res["mail"] and res["tasks"] and res["addressbook"][0] and res["settings"] and res["chat"]
              and res["calendar"] == [False, True]
              and not any(v["todo"] for v in res["looks"].values())
              and all(abs(v["agendaH"] - res["looks"]["mail"]["agendaH"]) <= 2 for v in res["looks"].values()))
        return ok, f"{res}"
    check("Today-Pane: in Mail, Aufgaben, Adressbuch, Einstellungen und Chat gleich (ohne Aufgabenteil), nicht im Kalender; nach der Installation eingeblendet", today_everywhere, results)

    def addon():
        v = m.js("""const { AddonManager } = ChromeUtils.importESModule("resource://gre/modules/AddonManager.sys.mjs");
                    const a = await AddonManager.getAddonByID("%s"); return [a?.version, a?.isActive];""" % ADDON_ID)
        return v == [version, True], f"{v}"
    check("Erweiterung aktiv und richtige Version", addon, results)

    def parts_loaded():
        # Reihe „implementation.js in Module zerlegen“: jeder Teil (api/…) ist in der Experiment-API geladen, seine
        # Namen sind dort da (gleiche Liste wie tests/logik/teile.test.mjs)
        teile = {"texte.js": ["TRANSLATIONS"], "mail.js": ["UndoSend"], "bereiche.js": ["Weather"], "import.js": ["PstImport"],
                 "kalender.js": ["parseNatural"], "grundlagen.js": ["LogoCache"],
                 "unterhaltung.js": ["ConversationCards", "foldQuotedHistory", "CONVERSATION_PREF"],
                 "oberflaeche.js": ["EnhancerOberflaeche"], "kalenderfenster.js": ["EnhancerKalender"],
                 "halofenster.js": ["EnhancerHaloFenster"], "mailliste.js": ["EnhancerMailliste"],
                 "mailkarten.js": ["EnhancerMailkarten"], "suchvorschlag.js": ["EnhancerSuchvorschlag", "searchSuggestRows"]}
        # Methoden aus den CardEnhancer-Teilen am laufenden enhancer
        methoden = ["styleSearch", "openQuickCreate", "openHaloWindow", "hookConversation", "decorateHeader", "refreshPreviewsNow",
                    "hookSearchSuggest"]
        res = m.js(r"""
          const { ExtensionParent } = ChromeUtils.importESModule("resource://gre/modules/ExtensionParent.sys.mjs");
          const g = ExtensionParent.GlobalManager.getExtension("%s").experimentAPIManager.global;
          const namen = %s;
          return { geladen: Cu.evalInSandbox("typeof loadedParts == 'undefined' ? null : loadedParts.join(',')", g),
                   fehlt: namen.filter(n => Cu.evalInSandbox(`typeof ${n}`, g) == "undefined"),
                   ohne: %s.filter(n => Cu.evalInSandbox(`typeof enhancer?.${n}`, g) != "function") };""" % (
            ADDON_ID, json.dumps(sorted({n for v in teile.values() for n in v})), json.dumps(methoden)))
        geladen = (res["geladen"] or "").split(",")
        ok = all(t in geladen for t in teile) and not res["fehlt"] and not res["ohne"]
        return ok, f"{res}"
    check("Erweiterung: Teile der Experiment-API (api/unterhaltung.js, Teile von CardEnhancer …) geladen, ihre Namen da", parts_loaded, results)

    def folder_start_width():
        # Neues Profil, Mail-Tab zuerst offen: Ordnerliste 206 px wie in Apple Mail (und wie nach
        # Doppelklick auf den Trenner) statt Thunderbirds 198 px. „Local Folders“ steht unter All Inboxes
        # eine Stufe tiefer und darf dort gekürzt erscheinen, aber nur mit „…“ und mit sichtbarer
        # Ungelesen-Zahl daneben (Maintainer 15.11.2026: „den namen "local folder" optisch abkürzen falls
        # das notwendig ist“). Muss vor „Ordnerleiste: Ziehen und Doppelklick“ laufen, das die gespeicherte
        # Breite ändert
        res = m.js("""
          const { MailServices } = ChromeUtils.importESModule("resource:///modules/MailServices.sys.mjs");
          try { MailServices.accounts.localFoldersServer; } catch { MailServices.accounts.createLocalMailAccount(); }
          const root = MailServices.accounts.localFoldersServer.rootFolder;
          if (!root.containsChildNamed("Inbox")) { root.createSubfolder("Inbox", null); }
          const inbox = root.getChildNamed("Inbox");
          const a3 = await toMail(); await ruhig(1000); const ad = a3.document;
          // „All Inboxes“ ist bei einem erst nachträglich entstandenen Posteingang zugeklappt: für die Messung aufklappen
          const row = await until(() => {
            const li = [...ad.querySelectorAll('#folderTree > li[data-mode="smart"] li[is="folder-tree-row"]')].find(l => l.uri == inbox.URI);
            const eltern = li?.parentElement?.closest("li");
            if (eltern?.classList.contains("collapsed")) eltern.querySelector(":scope > .container .twisty")?.click();
            return li?.querySelector(":scope > .container .name")?.clientWidth ? li : null;
          }, 8000);
          const name = row?.querySelector(":scope > .container .name");
          // Ungelesen-Zahl wie im Alltag (einstellig) nur für die Messung anzeigen
          if (row) row.unreadCount = 6; await ruhig(300);
          const out = { width: Math.round(ad.getElementById("folderPane").getBoundingClientRect().width),
                        pref: Services.prefs.getIntPref("extensions.mailcards.sidebarWidth", 0), text: name?.textContent,
                        count: row?.querySelector(":scope > .container .unread-count")?.textContent,
                        client: name?.clientWidth, scroll: name?.scrollWidth };
          // gekürzt nur mit „…“ (nicht hart abgeschnitten), die Zahl ganz sichtbar rechts neben dem Namen in der Liste
          const cs = name && a3.getComputedStyle(name), cnt = row?.querySelector(":scope > .container .unread-count");
          const pr = ad.getElementById("folderPane").getBoundingClientRect(), cr = cnt?.getBoundingClientRect(), nr = name?.getBoundingClientRect();
          out.ellipsis = cs ? cs.textOverflow == "ellipsis" && cs.whiteSpace == "nowrap" : null;
          out.countShown = !!cr && cr.width > 0 && cr.left >= nr.right - 1 && cr.right <= pr.right + 0.5;
          if (row) row.unreadCount = inbox.getNumUnread(false);
          // Mit „Local Folders“ ohne Posteingang wählt Thunderbird dessen Kontozeile (Kontoübersicht, ohne Liste und
          // Mail); die Sammelordner kommen erst jetzt dazu und ändern die Auswahl nicht. Die folgenden Prüfungen
          // brauchen die Mailansicht wie im Alltag: „All Inboxes“ wählen
          const alle = row?.parentElement?.closest("li");
          if (alle?.uri) { a3.displayFolder(alle.uri); await bis(() => a3.gFolder?.URI == alle.uri, "All Inboxes gewählt", 3000); await ruhig(500); }
          out.selected = !!alle?.uri && a3.gFolder?.URI == alle.uri && a3.document.getElementById("threadPane").getBoundingClientRect().width > 0;
          return out;""")
        # ganz oder mit „…“ gekürzt (auf allen Systemen)
        fits = res["scroll"] <= res["client"] or res.get("ellipsis") is True
        # Linux: Thunderbird legt die Ordnerliste mit der breiteren Systemschrift schon breiter an (240 px) –
        # dort bleibt sie so (nie schmaler als 206), gemerkt als eigene Breite
        width_ok = res["width"] == 206 and res["pref"] in (0, 206) if sys.platform == "darwin" else \
            res["width"] >= 206 and res["pref"] in (0, res["width"])
        ok = (width_ok and res["text"] == "Local Folders"
              and res["count"] == "6" and res.get("countShown") and res["client"] and fits and res.get("selected"))
        return ok, f"{res}"
    check("Ordnerliste: im neuen Profil 206 px breit, „Local Folders“ ganz oder mit … gekürzt, Zahl sichtbar", folder_start_width, results)

    def folder_header_hidden():
        # Thunderbirds Knopfzeile über der Ordnerliste („…“, Abrufen, Verfassen) ist immer aus, auch wenn
        # Thunderbird sie als sichtbar führt (frisches Profil); Abrufen und Verfassen stehen in der Toolbar
        res = m.js("""
          const a3 = await toMail(); await ruhig(500); const ad = a3.document;
          const bar = ad.getElementById("folderPaneHeaderBar");
          const was = bar.hidden; bar.hidden = false; await ruhig(200);
          const out = { display: a3.getComputedStyle(bar).display, h: bar.getBoundingClientRect().height };
          bar.hidden = was;
          const pane = ad.getElementById("folderPane").getBoundingClientRect();
          const head = [...ad.querySelectorAll("#folderTree > li > .container, #folderPane .mode-container")]
            .map(e => e.getBoundingClientRect()).find(r => r.height);
          out.gap = head ? Math.round(head.top - pane.top) : null;
          out.toolbar = ["get-messages", "write-message"].map(id =>
            !![...d.querySelectorAll(`#unifiedToolbarContent li[item-id="${id}"]`)].find(l => l.getBoundingClientRect().width));
          return out;""")
        ok = res["display"] == "none" and res["h"] == 0 and res["toolbar"] == [True, True] and res["gap"] is not None and 0 <= res["gap"] <= 24
        return ok, f"{res}"
    check("Ordnerliste: keine Knopfzeile über den Postfächern, Abrufen und Verfassen in der Toolbar", folder_header_hidden, results)

    def list_width():
        res = m.js("""
          const out = {};
          const msgAtMin = {};
          for (const width of [1500, 2000, 2600]) { w.resizeTo(width, 900); await wait(1300);
            const a3 = await toMail(); out[width] = Math.round(a3.document.getElementById("threadPane").getBoundingClientRect().width);
            const mp = a3.document.getElementById("messagePane");
            msgAtMin[width] = mp.getBoundingClientRect().width <= (parseFloat(a3.getComputedStyle(mp).minWidth) || 0) + 1; }
          w.resizeTo(1500, 900); await wait(800); return { out, msgAtMin };""")
        lists, at_min = res["out"], res["msgAtMin"]
        # Windows und Linux: die Fensterknöpfe stehen mit in der Toolbar-Zeile – bei 1500 px braucht die Leseansicht
        # dort etwas mehr Platz und die Liste gibt bis zu 30 px ab (gewollte Begrenzung im engen Fenster; unter Linux
        # je nach Fenstermanager, daher dort mal 460, mal 431); ab 2000 px muss sie wieder ihre 460 haben.
        # Ebenso schmaler, wenn die Leseansicht schon auf ihrer Mindestbreite (480 px) steht – dann fehlt der Platz
        # wirklich (ESR: schmalere Ansicht; Linux: Ordnerliste mit breiterer Schrift 240 statt 206 px, siehe
        # „Ordnerliste: im neuen Profil“), die Liste bekommt dann alles, was übrig ist
        ok = all(abs(v - 460) <= 1 or (v < 460 and at_min.get(k))
                 or (sys.platform != "darwin" and k == "1500" and 430 <= v <= 460) for k, v in lists.items())
        return ok, f"Listenbreite je Fensterbreite {lists} (soll 460), Leseansicht auf Mindestbreite {at_min}"
    check("Mailliste behält ihre Breite", list_width, results)

    def toolbar_edges():
        res = m.js("""
          const out = [];
          for (const width of [1280, 1500, 2400]) { w.resizeTo(width, 900); await wait(1300);
            const a3 = await toMail(); const off = a3.browsingContext.embedderElement.getBoundingClientRect();
            const row = d.getElementById("unifiedToolbarContainer"); const rl = row.getBoundingClientRect().left;
            const paneRight = Math.round(off.left + a3.document.getElementById("threadPane").getBoundingClientRect().right);
            const lineVar = parseFloat(getComputedStyle(row).getPropertyValue("--mc-list-right"));
            const spacer = d.querySelector('#unifiedToolbarContent > li[item-id="spacer"]').getBoundingClientRect().right;
            const search = Math.round(d.querySelector('#unifiedToolbarContent > li[item-id="search-bar"]').getBoundingClientRect().width);
            out.push({ width, line: Math.round(lineVar + rl) == paneRight || Math.abs(lineVar + rl - paneRight) <= 2, buttonsRightOfList: spacer >= paneRight, search }); }
          w.resizeTo(1500, 900); await wait(800); return out;""")
        ok = all(r["line"] and r["buttonsRightOfList"] and r["search"] >= 40 for r in res)
        detail = " · ".join(f"{r['width']}px: Linie {'✓' if r['line'] else '✗'}, Knöpfe {'✓' if r['buttonsRightOfList'] else '✗'}, Suche {r['search']}" for r in res)
        return ok, detail
    check("Toolbar: Trennlinie, Knopfkante, Suchfeld", toolbar_edges, results)

    def toolbar_write_gap():
        # Abstand nach „Verfassen“ 69 px wie Apple Mail; im schmalen Fenster schrumpft er (bis 12 px), danach wächst er
        # wieder – vorher blieb er klein, weil der Überlauf-Knopf „»“ (auch ausgeblendet) vor dem Suchfeld als
        # Abstandhalter gemessen wurde (im breiten Fenster standen die Gruppen dicht, rechts viel leerer Platz)
        res = m.js("""
          const gap = () => Math.round(parseFloat(getComputedStyle(d.querySelector('#unifiedToolbarContent > li[item-id="write-message"]')).marginInlineEnd));
          const out = {};
          await toMail(); w.resizeTo(2400, 900); await wait(1500); out.wide = gap();
          w.resizeTo(1000, 900); await wait(1500); out.narrow = gap();
          w.resizeTo(2400, 900); await wait(1500); out.again = gap();
          out.overflow = d.getElementById("mcToolbarOverflow")?.nextElementSibling?.getAttribute("item-id") || null;
          w.resizeTo(1500, 900); await wait(800);
          return out;""")
        ok = res["wide"] == 69 and res["narrow"] < 69 and res["again"] == 69
        return ok, f"{res}"
    check("Toolbar: Abstand nach „Verfassen“ 69 px, im schmalen Fenster kleiner, danach wieder 69 px", toolbar_write_gap, results)

    def toolbar_center_group():
        # Mail wie Apple Mail: Abrufen + Verfassen links an der Mailliste, die übrigen Pillen mittig zwischen „Verfassen“ und
        # Suchfeld (je ein wachsender Abstand), Suchfeld rechts; im schmalen Fenster schrumpfen die Abstände zuerst (keine
        # Pille ragt aus der Zeile, Suche mindestens Lupe). Eine gespeicherte frühere halo.spaces-Anordnung (ohne Abstand
        # nach „Verfassen“, mit Knopf eines Add-ons) bekommt den neuen Abstand, der Add-on-Knopf bleibt am Ende
        res = m.js(r"""
          const R = el => el.getBoundingClientRect();
          const out = {};
          const measure = () => {
            const content = d.getElementById("unifiedToolbarContent"), row = R(content);
            const q = id => content.querySelector(`:scope > li[item-id="${id}"]`);
            const shown = [...content.children].filter(l => R(l).width > 0 && getComputedStyle(l).display != "none");
            const mid = shown.filter(l => !["spacer", "search-bar", "get-messages", "write-message"].includes(l.getAttribute("item-id")) && l.id != "mcToolbarOverflow");
            const write = q("write-message"), search = q("search-bar");
            return { left: Math.round(R(mid[0]).left - R(write).right), right: Math.round(R(search).left - R(mid.at(-1)).right),
                     search: Math.round(R(search).width), squeezed: content.querySelectorAll(":scope > li[mc-squeezed][item-id]").length,
                     clipped: shown.filter(l => R(l).right > row.right + 1).length };
          };
          await toMail(); w.resizeTo(2400, 900); await wait(1500); out.wide = measure();
          w.resizeTo(1000, 900); await wait(1500); out.narrow = measure();
          w.resizeTo(1500, 900); await wait(800);
          const { getState, storeState } = ChromeUtils.importESModule("resource:///modules/CustomizationState.mjs");
          const { EXTENSION_PREFIX } = ChromeUtils.importESModule("resource:///modules/CustomizableItems.sys.mjs");
          const saved = getState(), ext = EXTENSION_PREFIX + "halo-test-addon";
          const old = ["spacer", "get-messages", "write-message", "reply", "reply-all", "forward-inline", "archive", "delete", "junk", "move-to", "mark-as", "spacer", "search-bar"];
          try { storeState({ ...saved, mail: [...old, ext] }); await ruhig(600); out.migrated = getState().mail; }
          finally { storeState(saved); await ruhig(500); }
          return out;""")
        wide, narrow, mig = res.get("wide") or {}, res.get("narrow") or {}, res.get("migrated") or []
        ok = (not wide.get("squeezed") and wide.get("left", 0) >= 69 and abs(wide.get("left", 0) - wide.get("right", 0)) <= 2
              and not narrow.get("clipped") and narrow.get("search", 0) >= 40 and 12 <= narrow.get("left", 0) <= 69
              and mig[:5] == ["spacer", "get-messages", "write-message", "spacer", "reply"]
              and mig[-1].endswith("halo-test-addon") and mig.count("spacer") == 3)
        return ok, f"{res}"
    check("Toolbar: Mail-Pillen mittig zwischen „Verfassen“ und Suchfeld, im schmalen Fenster schrumpfen zuerst die Abstände; frühere Anordnung wird übernommen", toolbar_center_group, results)

    def toolbar_search_first():
        # schmales Fenster mit Today-Pane: in jedem Bereich schrumpft zuerst das Suchfeld (bis zur Lupe), Knöpfe ragen nie aus der
        # Zeile; in der Mail weichen Knöpfe erst, wenn die Suche schon zur Lupe geworden ist (danach hat sie höchstens einen Knopf
        # mehr Platz). MacBook Pro 16" (1728 px) mit Today-Pane: alle Mail-Knöpfe sichtbar
        res = m.js("""
          const out = {};
          const tp = () => d.getElementById("today-pane-panel");
          const go = { mail: toMail, calendar: toCalendar, tasks: async () => { tm.openTab("tasks", {}); await ruhig(1500); },
                       addressbook: async () => { tm.openTab("addressBookTab", {}); await ruhig(2000); } };
          const tpCmd = d.getElementById("calendar_toggle_todaypane_command");
          const opened = [];
          const state = name => {
            const row = d.getElementById("unifiedToolbarContent").getBoundingClientRect();
            const items = [...d.querySelectorAll("#unifiedToolbarContent > li")].filter(l => !["spacer", "search-bar"].includes(l.getAttribute("item-id")) && !l.hidden && getComputedStyle(l).display != "none");
            const search = d.querySelector('#unifiedToolbarContent > li[item-id="search-bar"]');
            const sw = search && getComputedStyle(search).display != "none" ? Math.round(search.getBoundingClientRect().width) : null;
            return { today: Math.round(tp()?.getBoundingClientRect().width || 0), search: sw,
                     squeezed: name == "mail" ? [...d.querySelectorAll("#unifiedToolbarContent > li[mc-squeezed][item-id]")].map(l => l.getAttribute("item-id")) : [],
                     clipped: items.filter(l => { const r = l.getBoundingClientRect(); return r.width && r.right > row.right + 1; }).map(l => l.getAttribute("item-id")) };
          };
          w.resizeTo(1512, 900); await wait(800);
          for (const [name, open] of Object.entries(go)) {
            await open(); await ruhig(700);
            if (!w.TodayPane.isVisible) { tpCmd.doCommand(); await ruhig(1500); opened.push(name); }
            await ruhig(800);
            out[name] = state(name);
          }
          await toMail(); w.resizeTo(1728, 1000); await wait(1800);
          out.mail16 = state("mail");
          // Today-Pane in jedem Bereich wieder so wie vorher (sie merkt sich den Zustand je Bereich)
          for (const name of opened) { await go[name](); await ruhig(500); if (w.TodayPane.isVisible) { tpCmd.doCommand(); await ruhig(800); } }
          for (const t of [...tm.tabInfo].slice(1)) tm.closeTab(t);
          w.resizeTo(1500, 900); await wait(800);
          return out;""")
        # (Pillen weichen ganz: danach hat die Suche höchstens eine Pille mehr Platz – die breiteste hat drei Knöpfe, 3 × 44 px)
        ok = (all((v["today"] > 0 or k == "calendar") and not v["clipped"] and (v["search"] is None or v["search"] >= 40)
                  and (not v["squeezed"] or (v["search"] or 0) <= 40 + 3 * 44 + 8) for k, v in res.items())
              and res["mail16"]["today"] > 0 and not res["mail16"]["squeezed"])
        return ok, f"{res}"
    check("Toolbar: im schmalen Fenster mit Today-Pane schrumpft zuerst das Suchfeld, Knöpfe bleiben in allen Bereichen sichtbar", toolbar_search_first, results)

    def toolbar_addon_hint():
        # Add-on-Hinweis (Puzzle nach „Add-on aus Datei installieren“, GitHub #43): runder Knopf links neben dem Today-Knopf,
        # nicht am Fensterrand und nicht darunter; die Knopfleiste macht ihm Platz – mit offener und geschlossener Today-Pane
        res = m.js(r"""
          await toMail(); w.resizeTo(1400, 850); await ruhig(600);
          const box = d.getElementById("notification-popup-box"), img = d.getElementById("addons-notification-icon");
          if (!box || !img) return { box: false };
          const R = e => { const r = e.getBoundingClientRect(); return [Math.round(r.left), Math.round(r.right)]; };
          const measure = () => { const lis = [...d.querySelectorAll("#unifiedToolbarContent > li:not([hidden])")].filter(li => li.getBoundingClientRect().width > 0);
            return { box: R(box), toggle: R(d.getElementById("mcTodayToggle")), last: R(lis.at(-1)), tp: !!w.TodayPane?.isVisible }; };
          const out = { win: w.innerWidth };
          try {
            box.hidden = false; img.setAttribute("showing", "true"); await ruhig(400);
            out.one = measure();
            d.getElementById("mcTodayToggle").click(); await bis(() => !!w.TodayPane?.isVisible != out.one.tp, "Today-Pane umgeschaltet", 3000); await ruhig(1200);
            out.two = measure();
            d.getElementById("mcTodayToggle").click(); await bis(() => !!w.TodayPane?.isVisible == out.one.tp, "Today-Pane zurück", 3000); await ruhig(1200);
            // Kalender (ohne Today-Knopf): am Ende der Leiste mit Abstand zum Rand
            await toCalendar(); await ruhig(600);
            const lis = [...d.querySelectorAll("#unifiedToolbarContent > li:not([hidden])")].filter(li => li.getBoundingClientRect().width > 0);
            out.cal = { box: R(box), last: R(lis.at(-1)) };
            await toMail();
          } finally { box.hidden = true; img.removeAttribute("showing"); }
          return out;""")
        if res.get("box") is False:
            return False, "kein Add-on-Hinweis im Dokument"
        win = res.get("win", 0)
        def fits(x):
            return (isinstance(x, dict) and x["box"][1] - x["box"][0] == 40 and x["box"][1] <= x["toggle"][0] - 4
                    and x["last"][1] <= x["box"][0] + 1 and x["box"][1] <= win - 50)
        c = res.get("cal") or {}
        ok = (fits(res.get("one")) and fits(res.get("two")) and res["one"]["tp"] != res["two"]["tp"]
              and bool(c) and c["box"][1] - c["box"][0] == 40 and c["box"][1] <= win - 8 and c["last"][1] <= c["box"][0] + 1)
        return ok, f"{res}"
    check("Toolbar: Add-on-Hinweis (Puzzle) als runder Knopf links neben dem Today-Knopf, nicht am Fensterrand (GitHub #43)", toolbar_addon_hint, results)

    def toolbar_hint_box_empty():
        # Thunderbird blendet die Hinweis-Box auch ohne sichtbares Symbol ein (unter Windows beobachtet): dann kein leerer
        # grauer Kreis am Ende des Suchfelds (Mail, Today-Pane offen und zu) bzw. rechts daneben (Kalender)
        res = m.js(r"""
          await toMail(); w.resizeTo(1500, 900); await ruhig(600);
          const box = d.getElementById("notification-popup-box"), img = d.getElementById("addons-notification-icon");
          if (!box || !img) return { box: false };
          const M = () => { const r = box.getBoundingClientRect(), cs = w.getComputedStyle(box);
            return { w: Math.round(r.width), bg: cs.backgroundColor, shown: cs.display != "none" }; };
          const out = {};
          try {
            img.removeAttribute("showing"); box.hidden = false; await ruhig(400);
            out.mail = M();
            d.getElementById("mcTodayToggle").click(); await ruhig(1500);
            out.mail2 = M();
            d.getElementById("mcTodayToggle").click(); await ruhig(1500);
            await toCalendar(); await ruhig(600);
            out.cal = M();
            img.setAttribute("showing", "true"); await ruhig(400);
            out.calIcon = M();
            await toMail();
          } finally { box.hidden = true; img.removeAttribute("showing"); }
          return out;""")
        if res.get("box") is False:
            return False, "keine Hinweis-Box im Dokument"
        leer = lambda x: isinstance(x, dict) and (not x["shown"] or (x["w"] == 0 and x["bg"] in ("transparent", "rgba(0, 0, 0, 0)")))
        ok = leer(res.get("mail")) and leer(res.get("mail2")) and leer(res.get("cal")) and (res.get("calIcon") or {}).get("w") == 40
        return ok, f"{res}"
    check("Toolbar: Hinweis-Box ohne Symbol zeigt keinen leeren grauen Kreis am Suchfeld (Mail, Kalender)", toolbar_hint_box_empty, results)

    def message_min_width():
        # Trennlinie zwischen Mailliste und Mail weit nach rechts ziehen: die Mail klappt nicht weg, bleibt mindestens
        # 300 px breit, Knöpfe der Toolbar ragen nicht aus der Zeile
        pre = m.js(r"""
          const a3 = await toMail(); w.resizeTo(1500, 900); await wait(1000);
          const sp = a3.document.getElementById("messagePaneSplitter"), fr = a3.frameElement.getBoundingClientRect(), r = sp.getBoundingClientRect();
          w.__mcPrevList = Services.prefs.getIntPref("extensions.mailcards.listWidth", 0);
          w.__mcPrevMsg = sp.width;
          return { x: Math.round(fr.left + r.left + r.width / 2), y: Math.round(fr.top + r.top + 200), right: Math.round(fr.left + fr.width - 5) };""")
        m.pointer([{"type": "pointerMove", "x": pre["x"], "y": pre["y"], "origin": "viewport"}, {"type": "pointerDown", "button": 0},
                   {"type": "pointerMove", "x": pre["x"] + 60, "y": pre["y"], "origin": "viewport", "duration": 100},
                   {"type": "pointerMove", "x": pre["right"], "y": pre["y"], "origin": "viewport", "duration": 300},
                   {"type": "pointerUp", "button": 0}])
        res = m.js(r"""
          const a3 = tm.currentAbout3Pane; await ruhig(800);
          const sp = a3.document.getElementById("messagePaneSplitter"), mp = a3.document.getElementById("messagePane");
          const row = d.getElementById("unifiedToolbarContent").getBoundingClientRect();
          const clipped = [...d.querySelectorAll("#unifiedToolbarContent > li")].filter(l => { const r = l.getBoundingClientRect(); return r.width && r.right > row.right + 1; }).map(l => l.getAttribute("item-id"));
          const out = { collapsed: sp.isCollapsed, msg: Math.round(mp.getBoundingClientRect().width), clipped };
          // zurück
          if (sp.isCollapsed) sp.expand?.();
          if (w.__mcPrevList) Services.prefs.setIntPref("extensions.mailcards.listWidth", w.__mcPrevList); else Services.prefs.clearUserPref("extensions.mailcards.listWidth");
          sp.width = w.__mcPrevMsg; await ruhig(800);
          return out;""")
        ok = res.get("collapsed") is False and res.get("msg", 0) >= 299 and not res.get("clipped")
        return ok, f"{pre} {res}"
    check("Mailansicht: Trennlinie lässt sich nicht so weit ziehen, dass die Mail wegklappt (mindestens 300 px, Knöpfe bleiben in der Zeile)", message_min_width, results)

    def list_splitter_drag_cards():
        # GitHub #75: Kartenansicht, ungruppiert, Today-Pane offen und wenig Platz für Liste und Mail (rund 700 px, z. B.
        # Laptop): nie gezogen steht die Liste wie bisher auf 300 px (sie gibt zuerst nach), die Trennlinie folgt aber dem
        # Ziehen nach rechts (Mail bis 300 px) und wieder nach links; vorher bewegte sie sich in keine Richtung. Der
        # Engpass entsteht nur auf einem kleinen Bildschirm (Laptop, 1280 px): auf einem großen hält die Mindestbreite des
        # Fensters (hookMinWindowWidth, endet am Bildschirm) es mit Today-Pane bei rund 1500 px, resizeTo wirkt dann nicht
        # (allein gestartet stand sie noch nicht, im vollen Lauf schon – dort blieb der Platz bei rund 900 px). Darum
        # Bildschirm vorgetäuscht wie in „Mail: mit gewählter Mail und Today-Pane (1500 px und kleiner Bildschirm) …“
        def drag(dx):
            p = m.js(r"""
              const a3 = tm.currentAbout3Pane, sp = a3.document.getElementById("messagePaneSplitter");
              const fr = a3.frameElement.getBoundingClientRect(), r = sp.getBoundingClientRect();
              return { x: Math.round(fr.left + r.left + r.width / 2), y: Math.round(fr.top + r.top + 200) };""")
            m.pointer([{"type": "pointerMove", "x": p["x"], "y": p["y"], "origin": "viewport"}, {"type": "pointerDown", "button": 0},
                       {"type": "pointerMove", "x": p["x"] + (dx // 3), "y": p["y"], "origin": "viewport", "duration": 100},
                       {"type": "pointerMove", "x": p["x"] + dx, "y": p["y"], "origin": "viewport", "duration": 200},
                       {"type": "pointerUp", "button": 0}])
            return m.js(r"""
              const a3 = tm.currentAbout3Pane; await ruhig(800);
              return { list: Math.round(a3.document.getElementById("threadPane").getBoundingClientRect().width),
                       msg: Math.round(a3.document.getElementById("messagePane").getBoundingClientRect().width) };""")
        def shot(name):
            # mit HALO_SHOTS ein Bild des ganzen Fensters (Testprofil)
            if not os.environ.get("HALO_SHOTS"):
                return
            import base64
            png = m.js(r"""
              const bm = await w.browsingContext.currentWindowGlobal.drawSnapshot(new w.DOMRect(0, 0, w.innerWidth, w.innerHeight), 1, "white");
              const cv = d.createElementNS("http://www.w3.org/1999/xhtml", "canvas"); cv.width = bm.width; cv.height = bm.height;
              cv.getContext("2d").drawImage(bm, 0, 0); return cv.toDataURL("image/png").split(",")[1];""")
            os.makedirs(os.environ["HALO_SHOTS"], exist_ok=True)
            path = os.path.join(os.environ["HALO_SHOTS"], f"mailliste-trennlinie-schmal-{name}.png")
            open(path, "wb").write(base64.b64decode(png))
            print(f"Bild {path}", flush=True)
        pre = m.js(MAILLIST_JS + r"""
          await showFolder(); await asCards();
          const PREF = "extensions.mailcards.listWidth";
          w.__mcPrev75 = { list: Services.prefs.prefHasUserValue(PREF) ? Services.prefs.getIntPref(PREF) : 0,
                           msg: a3.document.getElementById("messagePaneSplitter").width, threaded: a3.gViewWrapper.showThreaded,
                           tp: w.TodayPane.isVisible, ww: w.outerWidth, wh: w.outerHeight, ws: w.windowState,
                           screen: Object.getOwnPropertyDescriptor(w, "screen") };
          // (vorige Prüfungen lassen das Fenster teils maximiert zurück, dann wirkt resizeTo nicht)
          if (w.windowState != w.STATE_NORMAL) { w.restore(); await bis(() => w.windowState == w.STATE_NORMAL, "Fenster normal", 3000); await ruhig(500); }
          a3.gViewWrapper.showUnthreaded = true; await ruhig(800);
          if (!w.TodayPane.isVisible) { d.getElementById("calendar_toggle_todaypane_command").doCommand(); await ruhig(1500); }
          // nie gezogen
          Services.prefs.clearUserPref(PREF);
          const tp = a3.document.getElementById("threadPane"), mp = a3.document.getElementById("messagePane");
          const room = () => Math.round(tp.getBoundingClientRect().width + mp.getBoundingClientRect().width);
          // (eine vorige Prüfung kann der Mail eine feste Breite gelassen haben, die das Fenster nicht schmaler werden lässt;
          // die Mail bekommt danach wieder den Rest)
          a3.document.getElementById("messagePaneSplitter").width = 300;
          // kleiner Bildschirm: die Mindestbreite des Fensters endet am Bildschirm. Erst 1280 px, dann so nachgestellt, dass
          // für Liste und Mail auf jeder Plattform rund 700 px bleiben (unter Linux sind Ordnerliste und Today-Pane zusammen
          // rund 30 px breiter: bei 1280 px blieben 669 px, die Mail hält mit ihren Knöpfen bei rund 340 px, und die
          // Trennlinie hatte nur 29 px Weg statt der verlangten 40)
          const small = async W => {
            w.screen = { availWidth: W, availHeight: 860, availLeft: 0, availTop: 0, width: W, height: 900, left: 0, top: 0 };
            w.dispatchEvent(new w.Event("resize")); await ruhig(300); d.documentElement.style.minWidth = "";
            w.resizeTo(W, 860); await until(() => w.outerWidth == W, 3000); await stabil(() => [room(), w.innerWidth], 4000); };
          await small(1280);
          for (let i = 0; i < 2 && Math.abs(room() - 700) > 2; i++) await small(Math.round(w.outerWidth + 700 - room()));
          return { room: room(), win: w.outerWidth, list: Math.round(tp.getBoundingClientRect().width), max: a3.getComputedStyle(tp).maxWidth,
                   msg: Math.round(mp.getBoundingClientRect().width), unthreaded: a3.gViewWrapper.showUnthreaded, cards: Services.prefs.getIntPref("mail.threadpane.listview", 0) == 0 };""")
        try:
            shot("vorher")
            right = drag(80)
            shot("rechts")
            left = drag(-60)
        finally:
            m.js(r"""
              const a3 = tm.currentAbout3Pane, p = w.__mcPrev75 || {};
              if (p.threaded) a3.gViewWrapper.showThreaded = true;
              if (p.list) Services.prefs.setIntPref("extensions.mailcards.listWidth", p.list); else Services.prefs.clearUserPref("extensions.mailcards.listWidth");
              if (p.screen) Object.defineProperty(w, "screen", p.screen); else delete w.screen;
              if (p.ww) w.resizeTo(p.ww, p.wh);
              if (p.ws == w.STATE_MAXIMIZED) w.maximize();
              if (p.msg) a3.document.getElementById("messagePaneSplitter").width = p.msg;
              if (!p.tp && w.TodayPane.isVisible) { d.getElementById("calendar_toggle_todaypane_command").doCommand(); await ruhig(1500); }
              await wait(1000); await ruhig(800); return true;""")
        # der Engpass muss auf jeder Plattform entstehen (auch unter Linux, mit vorgetäuschtem Bildschirm geht es dort)
        band = 620 <= pre["room"] <= 780
        default = abs(pre["list"] - max(300, pre["room"] - 480)) <= 2
        ok = (band and pre["unthreaded"] and pre["cards"] and default and right["list"] - pre["list"] >= 40 and right["msg"] >= 299
              and right["list"] - left["list"] >= 30)
        return ok, (f"vorher {pre}, nach rechts {right}, nach links {left}" + ("" if band else " (Platz nicht im Band 620–780)") + ("" if default else " (Liste nie gezogen nicht wie bisher)"))
    check("Mailansicht: Trennlinie zwischen Mailliste und Mail folgt dem Ziehen auch bei wenig Platz mit Today-Pane (Kartenansicht, ungruppiert, nie gezogen zuerst wie bisher; GitHub #75)", list_splitter_drag_cards, results)

    def toolbar_wider_list():
        # Mailliste breiter ziehen (Today-Pane offen): weichen Pillen, dann nur so viele, wie nötig – die zuletzt ausgeblendete
        # Pille hätte neben der Suche keinen Platz mehr (sie weichen streng der Reihe nach und immer ganz, siehe SQUEEZE_PILLS)
        res = m.js(r"""
          const a3 = await toMail();
          const tpCmd = d.getElementById("calendar_toggle_todaypane_command");
          const opened = !w.TodayPane.isVisible; if (opened) { tpCmd.doCommand(); await ruhig(1500); }
          const PREF = "extensions.mailcards.listWidth", before = Services.prefs.getIntPref(PREF, 0);
          const sp = a3.paneLayout?.messagePaneSplitter;
          const tbItems = () => [...d.querySelectorAll("#unifiedToolbarContent > li[item-id]")].filter(l => !["spacer", "search-bar"].includes(l.getAttribute("item-id")));
          w.resizeTo(1728, 1000); await wait(1800);
          const widths = Object.fromEntries(tbItems().filter(l => !l.hasAttribute("mc-squeezed")).map(l => [l.getAttribute("item-id"), l.getBoundingClientRect().width]));
          const search = () => Math.round(d.querySelector('#unifiedToolbarContent > li[item-id="search-bar"]').getBoundingClientRect().width);
          const out = { searchStart: search(), steps: [] };
          // sichtbarer Platzhalter: erstes Wort („Search“) ganz, der Zusatz darf mit „…“ enden
          const firstWordFits = ph => { const n = ph.firstChild; if (!n?.length) return true; const sp = n.data.indexOf(" ");
            const rg = d.createRange(); rg.setStart(n, 0); rg.setEnd(n, sp > 0 ? sp : n.length); return rg.getBoundingClientRect().width <= ph.clientWidth + 1; };
          const list = a3.document.getElementById("threadPane");
          try {
            for (const add of [60, 120, 180, 240]) {
              const lw = Math.round(list.getBoundingClientRect().width);
              Services.prefs.setIntPref(PREF, (before || lw) + add);
              sp.width = Math.max(200, Math.round(a3.document.getElementById("messagePane").getBoundingClientRect().width - (before || lw) - add + lw));
              await ruhig(900);
              const hidden = tbItems().filter(l => l.hasAttribute("mc-squeezed")).map(l => l.getAttribute("item-id"));
              const ph = d.querySelector("global-search-bar")?.querySelector('[slot="placeholder"]');
              // Pillen weichen streng der Reihe nach und kommen umgekehrt zurück: zurückkommen könnte nur die zuletzt
              // ausgeblendete (letzte in der Reihenfolge), nicht eine schmalere, die früher wich
              const PILLS = [["mark-as"], ["move-to"], ["archive", "delete", "junk"], ["reply", "reply-all", "forward-inline"]];
              const lastPill = PILLS.filter(p => p.some(id => hidden.includes(id))).pop();
              // eine Pille weicht nur ganz (nie einzelne Knöpfe daraus)
              out.partial = (out.partial || []).concat(PILLS.filter(p => p.some(id => hidden.includes(id)) && p.some(id => widths[id] && !hidden.includes(id))).map(p => p.join("+")));
              out.steps.push({ add, search: search(), hidden, minHidden: lastPill ? Math.round(lastPill.reduce((a, id) => a + (widths[id] || 0), 0)) || 999 : null,
                chevron: !!d.getElementById("mcToolbarOverflow") && !d.getElementById("mcToolbarOverflow").hasAttribute("mc-squeezed"),
                ph: ph ? [w.getComputedStyle(ph).visibility != "hidden", firstWordFits(ph)] : null });
            }
          } finally {
            if (before) Services.prefs.setIntPref(PREF, before); else Services.prefs.clearUserPref(PREF);
            sp.width = Math.round(a3.document.getElementById("messagePane").getBoundingClientRect().width - 240);
            await ruhig(800);
            if (opened) { tpCmd.doCommand(); await ruhig(800); }
            w.resizeTo(1500, 900); await wait(800);
          }
          return out;""")
        # hätte der zuletzt ausgeblendete Knopf (plus Abstand) noch neben die Suche gepasst, ist zu viel ausgeblendet
        bad = [st for st in res.get("steps", []) if st["hidden"] and st["minHidden"] and st["search"] - 40 >= st["minHidden"] + 8]
        # Platzhalter nur, wenn wenigstens das erste Wort ganz hineinpasst, sonst nur die Lupe
        ph_bad = [st for st in res.get("steps", []) if st.get("ph") and st["ph"][0] and not st["ph"][1]]
        ok = bool(res.get("steps")) and not bad and not ph_bad and any(st["hidden"] for st in res["steps"]) \
            and any(st.get("ph") and not st["ph"][0] for st in res["steps"]) and not res.get("partial") \
            and all(st["chevron"] == bool(st["hidden"]) for st in res["steps"])
        return ok, f"{res}"
    check("Toolbar: Mailliste breiter ziehen blendet nur so viele Knöpfe aus wie nötig, die Suche bleibt klein und zeigt dann nur die Lupe", toolbar_wider_list, results)

    def search_lupe_opens():
        # Suchfeld als Lupe (schmales Fenster mit Today-Pane, Pillen im Menü „»“): ein Klick auf die Lupe öffnet es wie in
        # Apple Mail auf Lupe + Platzhalter mit dem Textfeld im Fokus, dafür weichen weitere Pillen; leer verlassen ist es
        # wieder die Lupe, ebenso nach dem Fokus per Tastatur; wieder breit stehen Pillen und Suchfeld wie vorher (GitHub #67:
        # vorher blieb das Feld 40 px schmal, man tippte unsichtbar hinein)
        res = m.js(r"""
          const a3 = await toMail();
          const tpCmd = d.getElementById("calendar_toggle_todaypane_command");
          const opened = !w.TodayPane.isVisible; if (opened) { tpCmd.doCommand(); await ruhig(1500); }
          const R = e => e.getBoundingClientRect();
          const content = () => d.getElementById("unifiedToolbarContent");
          const li = () => content().querySelector(':scope > li[item-id="search-bar"]');
          const inp = () => li().querySelector("global-search-bar")?.shadowRoot?.querySelector("input");
          const st = () => { const c = content(), s = li(), i = inp(), ov = d.getElementById("mcToolbarOverflow");
            const pad = parseFloat(getComputedStyle(c).paddingInlineEnd) || 0;
            return { iw: w.innerWidth, w: Math.round(R(s).width), inp: i ? Math.round(R(i).width) : -1,
              fit: Math.round(parseFloat(s.style.getPropertyValue("--mc-search-fit")) || 0),
              lupe: c.hasAttribute("mc-search-lupe"), offen: s.hasAttribute("mc-search-open"), ov: !!ov && !ov.hasAttribute("mc-squeezed"),
              hidden: [...c.querySelectorAll(":scope > li[mc-squeezed]")].filter(l => l.id != "mcToolbarOverflow").map(l => l.getAttribute("item-id")),
              fokus: !!i && i.getRootNode().activeElement == i, drin: Math.round(R(s).right - (R(c).right - pad)) <= 1 }; };
          const weg = async () => { a3.document.getElementById("threadTree")?.focus(); await ruhig(800); };
          const out = {};
          try {
            const breit = Math.min(1900, w.screen.availWidth);
            w.resizeTo(breit, 900); await ruhig(1500); out.vorher = st();
            w.resizeTo(800, 900); await ruhig(1500); out.schmal = st();
            // Klick auf die Lupe: an das Element an dieser Stelle (windowUtils.sendMouseEvent gibt es nicht mehr)
            const r = R(li()), cx = r.left + 20, cy = r.top + r.height / 2;
            const ziel = d.elementFromPoint(cx, cy) || li();
            for (const type of ["mousedown", "mouseup", "click"]) {
              ziel.dispatchEvent(new w.MouseEvent(type, { bubbles: true, cancelable: true, composed: true, view: w, button: 0, clientX: cx, clientY: cy }));
            }
            await ruhig(800); out.klick = st();
            await weg(); out.weg = st();
            inp()?.focus(); await ruhig(800); out.taste = st();
            await weg(); out.weg2 = st();
            // bei jeder Breite, nicht nur im schmalsten Fenster: von der ersten Breite an, bei der Pillen weichen, in kleinen
            // Schritten schmaler (unter Linux blieb das Feld bei 1551 px nach dem Öffnen 42 px breit, weil die Pillen nur
            // wichen, bis es breiter als die Lupe war)
            out.stufen = [];
            let b = breit;
            w.resizeTo(b, 900); await ruhig(1500);
            while (b > out.schmal.iw + 40 && !st().lupe) { b -= 40; w.resizeTo(b, 900); await ruhig(1000); }
            for (let n = 0; n < 8 && b > out.schmal.iw; n++, b -= 14) {
              w.resizeTo(b, 900); await ruhig(1000);
              const zu = st();
              if (!zu.lupe) { continue; }
              inp()?.focus(); await ruhig(800);
              const auf = st();
              await weg();
              // (wieder zu: dieselben Pillen wie vor dem Öffnen, nicht mehr)
              out.stufen.push({ b, zu: zu.hidden.length, wiederZu: st().hidden.length, abstand: getComputedStyle(content()).getPropertyValue("--mc-write-gap").trim(), ...auf });
            }
            // dieselbe Breite in einem Sprung statt in Schritten: dieselben Pillen (vorher wichen im Sprung mehr, und sie
            // kamen nicht zurück, weil der Abstand nach „Verfassen“ den frei gewordenen Platz nahm)
            if (out.stufen.length) {
              const z = out.stufen.at(-1);
              w.resizeTo(breit, 900); await ruhig(1500);
              w.resizeTo(z.b, 900); await ruhig(1500);
              out.sprung = { soll: z.zu, ...st() };
            }
            w.resizeTo(breit, 900); await ruhig(1500); out.nachher = st();
          } finally {
            await weg();
            if (opened) { tpCmd.doCommand(); await ruhig(800); }
            w.resizeTo(1500, 900); await ruhig(800);
          }
          return out;""")
        s, k, t, v, n = (res.get(x, {}) for x in ("schmal", "klick", "taste", "vorher", "nachher"))
        voll = lambda z, zu=None: z.get("offen") and z.get("fokus") and z.get("w", 0) >= min(160, z.get("fit") or 160) - 1 and z.get("inp", 0) >= 40 \
            and z.get("drin") and z.get("ov") and len(z.get("hidden", [])) >= (len(s.get("hidden", [])) if zu is None else zu)
        lupe = lambda z: not z.get("offen") and z.get("w", 99) <= 41 and z.get("lupe")
        stufen = res.get("stufen") or []
        ok = bool(s.get("lupe") and s.get("w", 99) <= 41 and s.get("ov")) and voll(k) and voll(t) and lupe(res.get("weg", {})) \
            and len(res.get("sprung", {}).get("hidden", [9])) == res.get("sprung", {}).get("soll") \
            and len(stufen) >= 3 and all(voll(z, z.get("zu", 0)) and z.get("wiederZu") == z.get("zu") for z in stufen) \
            and lupe(res.get("weg2", {})) and n.get("hidden") == v.get("hidden") and abs(n.get("w", 0) - v.get("w", -9)) <= 1
        return ok, f"{res}"
    check("Toolbar: Suchfeld als Lupe öffnet sich per Klick (und per Tastatur) auf Lupe + Platzhalter mit Fokus, dafür weichen Pillen; "
          "leer verlassen wieder die Lupe; wieder breit alles wie vorher (GitHub #67)", search_lupe_opens, results)

    def toolbar_overflow():
        # Symbolleisten-Überlauf wie Apple Mail (alle Bereiche): im schmalen Fenster mit Today-Pane ist das Suchfeld nur noch die
        # Lupe, Pillen weichen ganz (nie einzelne Knöpfe daraus, nichts ragt aus der Zeile), direkt links neben dem Suchfeld steht
        # der Überlauf-Knopf „»“ (eigene Kapsel); sein Menü zeigt die Aktionen aller ausgeblendeten Knöpfe in Toolbar-Reihenfolge
        # mit Symbol, „Verschieben“ öffnet das Ordnermenü. Im breiten Fenster ohne Today-Pane: kein Überlauf-Knopf
        res = m.js(MESSAGE_JS + r"""
          const out = {};
          const tpCmd = d.getElementById("calendar_toggle_todaypane_command");
          const opened = !w.TodayPane.isVisible; if (opened) { tpCmd.doCommand(); await ruhig(1500); }
          const PILLS = [["get-messages", "write-message"], ["reply", "reply-all", "forward-inline"], ["archive", "delete", "junk"], ["move-to"], ["mark-as"],
                         ["new-event", "new-task"], ["create-contact"], ["create-address-book", "create-list"]];
          const R = e => e.getBoundingClientRect();
          const state = () => {
            const content = d.getElementById("unifiedToolbarContent"), row = R(content);
            const lis = [...content.children].filter(l => !l.hidden && !["spacer", "search-bar"].includes(l.getAttribute("item-id")) && l.id != "mcToolbarOverflow");
            const hidden = lis.filter(l => l.hasAttribute("mc-squeezed")).map(l => l.getAttribute("item-id"));
            const shown = lis.filter(l => !l.hasAttribute("mc-squeezed") && getComputedStyle(l).display != "none").map(l => l.getAttribute("item-id"));
            const ov = d.getElementById("mcToolbarOverflow"), search = content.querySelector(':scope > li[item-id="search-bar"]');
            const o = ov && !ov.hasAttribute("mc-squeezed") && R(ov).width ? R(ov) : null, sr = R(search);
            const icon = ov?.querySelector(".button-icon");
            return { hidden, partial: PILLS.filter(p => p.some(id => hidden.includes(id)) && p.some(id => shown.includes(id))).map(p => p.join("+")),
                     clipped: [...content.children].filter(l => l.getAttribute("item-id") != "spacer" && R(l).width && R(l).right > row.right + 1).map(l => l.getAttribute("item-id") || l.id),
                     search: Math.round(sr.width), ov: o ? { w: Math.round(o.width), gap: Math.round(sr.left - o.right), next: ov.nextElementSibling == search } : null,
                     icon: icon ? [getComputedStyle(icon).maskImage != "none", getComputedStyle(icon).backgroundColor] : null,
                     labels: hidden.map(id => (content.querySelector(`:scope > li[item-id="${id}"] .button-label`)?.textContent || "").trim()) };
          };
          try {
            // breit ohne Today-Pane: alles sichtbar, kein Überlauf-Knopf; Breiten der Knöpfe für den Vergleich unten
            if (w.TodayPane.isVisible) { tpCmd.doCommand(); await ruhig(1200); }
            w.resizeTo(Math.min(1900, w.screen.availWidth), 900); await ruhig(1500);
            out.wide = state();
            out.widths = Object.fromEntries([...d.querySelectorAll("#unifiedToolbarContent > li[item-id]")].map(l => [l.getAttribute("item-id"), Math.round(R(l).width)]));
            tpCmd.doCommand(); await ruhig(1500);
            w.resizeTo(800, 900); await ruhig(1500);
            out.narrow = state(); out.win = w.innerWidth;
            const btn = d.querySelector("#mcToolbarOverflow > button");
            if (btn && out.narrow.ov) {
              btn.click(); const menu = await bis(() => d.getElementById("mcToolbarOverflowMenu")?.state == "open" && d.getElementById("mcToolbarOverflowMenu"), "Überlauf-Menü offen", 3000);
              out.menu = [...menu.children].map(i => ({ label: i.getAttribute("label"), id: i.getAttribute("mc-item"), disabled: i.disabled,
                icon: getComputedStyle(i.querySelector(".menu-icon") || i).maskImage != "none" }));
              const move = [...menu.children].find(i => i.getAttribute("mc-item") == "move-to");
              if (move && !move.disabled) {
                menu.activateItem(move);
                out.movePopup = !!await until(() => d.getElementById("toolbarMoveToPopup")?.state == "open", 3000);
                d.getElementById("toolbarMoveToPopup")?.hidePopup(); await ruhig(400);
              } else { menu.hidePopup(); }
              await ruhig(400);
            }
            // übrige Bereiche: keine abgeschnittene oder halbe Pille, Überlauf-Knopf nur mit ausgeblendeten Pillen
            out.spaces = {};
            for (const [name, open] of [["calendar", toCalendar], ["tasks", async () => { tm.openTab("tasks", {}); await ruhig(1500); }],
                                        ["addressbook", async () => { tm.openTab("addressBookTab", {}); await ruhig(2000); }]]) {
              await open(); await ruhig(1000); const st = state();
              out.spaces[name] = { partial: st.partial, clipped: st.clipped, ovOk: !st.ov == !st.hidden.length };
            }
            for (const t of [...tm.tabInfo].slice(1)) tm.closeTab(t);
          } finally {
            d.getElementById("mcToolbarOverflowMenu")?.hidePopup?.();
            await toMail(); if (w.TodayPane.isVisible != !opened) { tpCmd.doCommand(); await ruhig(1000); }
            w.resizeTo(1500, 900); await ruhig(800);
          }
          return out;""")
        n, menu = res.get("narrow") or {}, res.get("menu") or []
        # nur so viele Pillen wie nötig: die zuletzt ausgeblendete hätte neben der Lupe keinen Platz (ist sie die einzige,
        # fiele mit ihr auch „»“ weg)
        order = [["mark-as"], ["move-to"], ["archive", "delete", "junk"], ["reply", "reply-all", "forward-inline"]]
        hid = [p for p in order if any(i in n.get("hidden", []) for i in p)]
        last = sum(res.get("widths", {}).get(i, 0) for i in hid[-1]) if hid else 0
        room = n.get("search", 0) - 40 + (46 if len(hid) == 1 else 0)
        ok = (bool(n.get("hidden")) and not n.get("partial") and not n.get("clipped") and room < last + 6
              and bool(n.get("ov")) and n["ov"]["w"] == 40 and n["ov"]["next"] and 0 <= n["ov"]["gap"] <= 8
              and bool(n.get("icon")) and n["icon"][0] and n["icon"][1] not in ("rgba(0, 0, 0, 0)", "transparent")
              and [i["id"] for i in menu] == n["hidden"] and [i["label"] for i in menu] == n["labels"] and all(i["icon"] and i["label"] for i in menu)
              and all(not i["disabled"] for i in menu if i["id"] in ("reply", "forward-inline", "move-to"))
              and res.get("movePopup") is True
              and all(not v["partial"] and not v["clipped"] and v["ovOk"] for v in res.get("spaces", {}).values())
              and not (res.get("wide") or {}).get("ov") and not (res.get("wide") or {}).get("hidden"))
        return ok, f"{res}"
    check("Toolbar: Überlauf wie Apple Mail – im schmalen Fenster weichen Pillen ganz, links neben der Lupe erscheint „»“ mit den ausgeblendeten Aktionen", toolbar_overflow, results)

    def toolbar_overflow_back():
        # GitHub #67 Teil c: wird das Fenster wieder breiter (z. B. größerer Bildschirm), kommen die gewichenen Pillen
        # zurück in die Leiste und „»“ verschwindet – in der Mail und in den übrigen Bereichen, auch wenn das Fenster in
        # einem anderen Bereich schmal war und erst danach in der Mail breiter wird (mit und ohne Today-Pane)
        res = m.js(MESSAGE_JS + r"""
          const out = {};
          const tpCmd = d.getElementById("calendar_toggle_todaypane_command");
          const tpWas = w.TodayPane.isVisible;
          const st = () => {
            const content = d.getElementById("unifiedToolbarContent");
            const ov = d.getElementById("mcToolbarOverflow");
            return { hidden: [...content.children].filter(l => !l.hidden && l.hasAttribute("mc-squeezed") && l.id != "mcToolbarOverflow").map(l => l.getAttribute("item-id")),
                     ov: !!(ov && !ov.hasAttribute("mc-squeezed") && ov.getBoundingClientRect().width) };
          };
          const breit = Math.min(1900, w.screen.availWidth);
          try {
            if (!w.TodayPane.isVisible) { tpCmd.doCommand(); await ruhig(1500); }
            for (const [name, open] of [["mail", toMail], ["calendar", toCalendar]]) {
              await open(); await ruhig(1000);
              w.resizeTo(800, 900); await ruhig(1500);
              const schmal = st();
              w.resizeTo(breit, 900); await ruhig(1500);
              if (w.TodayPane.isVisible) { tpCmd.doCommand(); await ruhig(1500); }
              out[name] = { schmal, breit: st() };
              tpCmd.doCommand(); await ruhig(1500);
            }
            // schmal im Kalender, breit erst nach dem Wechsel in die Mail
            await toCalendar(); await ruhig(1000);
            w.resizeTo(800, 900); await ruhig(1500);
            await toMail(); await ruhig(1500);
            const schmal = st();
            w.resizeTo(breit, 900); await ruhig(1500);
            if (w.TodayPane.isVisible) { tpCmd.doCommand(); await ruhig(1500); }
            out.wechsel = { schmal, breit: st() };
            for (const t of [...tm.tabInfo].slice(1)) tm.closeTab(t);
            // Hinweis-Symbol einer Add-on-Installation (steht in derselben Zeile wie die Knöpfe): solange es sichtbar
            // ist, weichen Pillen; danach kommen sie bei gleicher Fensterbreite zurück (vorher blieb z. B. „Archiv“
            // nach Installieren über einen Add-on-Tab eingeklappt, die Zeile selbst änderte ihre Breite ja nicht)
            await toMail(); if (!w.TodayPane.isVisible) { tpCmd.doCommand(); await ruhig(1500); }
            w.resizeTo(1500, 900); await ruhig(1500);
            const box = d.getElementById("notification-popup-box"), icon = d.getElementById("addons-notification-icon");
            // (nutzbare Breite: in der Mail steht das Symbol schwebend über der Zeile, die Knopfleiste macht ihm mit ihrem
            // Innenabstand Platz)
            const breiteKnoepfe = () => { const c = d.getElementById("unifiedToolbarContent"), cs = getComputedStyle(c);
                                          return Math.round(c.clientWidth - parseFloat(cs.paddingInlineStart) - parseFloat(cs.paddingInlineEnd)); };
            const vorher = { ...st(), zeile: breiteKnoepfe() };
            box.hidden = false; icon.setAttribute("showing", "true");
            await ruhig(1500);
            const mit = { ...st(), zeile: breiteKnoepfe() };
            box.hidden = true; icon.removeAttribute("showing");
            await ruhig(1500);
            out.hinweis = { vorher, mit, nachher: { ...st(), zeile: breiteKnoepfe() } };
          } finally {
            d.getElementById("notification-popup-box").hidden = true; d.getElementById("addons-notification-icon")?.removeAttribute("showing");
            await toMail(); if (w.TodayPane.isVisible != tpWas) { tpCmd.doCommand(); await ruhig(1000); }
            w.resizeTo(1500, 900); await ruhig(800);
          }
          return out;""")
        # (der Kalender hat wenige Pillen – weicht dort schmal keine, zählt nur „wieder breit nichts gewichen“)
        cases = [(res.get(k) or {}, k != "calendar") for k in ("mail", "calendar", "wechsel")]
        h = res.get("hinweis") or {}
        hv, hm, hn = h.get("vorher") or {}, h.get("mit") or {}, h.get("nachher") or {}
        ok = (all((not muss or (c.get("schmal", {}).get("hidden") and c.get("schmal", {}).get("ov")))
                  and c.get("breit", {}).get("hidden") == [] and c.get("breit", {}).get("ov") is False for c, muss in cases)
              # das Symbol nahm der Knopfzeile Platz, danach wieder dieselbe Breite und dieselben Pillen wie vorher
              and hm.get("zeile", 0) < hv.get("zeile", 0) and len(hm.get("hidden", [])) > len(hv.get("hidden", []))
              and hn.get("zeile") == hv.get("zeile") and hn.get("hidden") == hv.get("hidden") and hn.get("ov") == hv.get("ov"))
        return ok, f"{res}"
    check("Toolbar: Überlauf – wieder breit kommen alle Pillen zurück und „»“ verschwindet (Mail, Kalender, nach Bereichswechsel, nach Hinweis-Symbol einer Add-on-Installation; GitHub #67)", toolbar_overflow_back, results)

    def toolbar_min_window():
        # Mail-Space auf Mindestbreite (Fenster so schmal wie möglich, geöffnete Mail, mit und ohne Today-Pane, mit
        # Ordnerliste): die Knopfleiste über der Mail schneidet nichts ab – keine Pille halb, kein Knopf über einem anderen
        # oder über dem Seitenleisten-Knopf, nichts aus der Zeile; Suchfeld mindestens die Lupe; „»“ nur mit ausgeblendeten Pillen
        res = m.js(MESSAGE_JS + r"""
          const out = {};
          const tpCmd = d.getElementById("calendar_toggle_todaypane_command");
          const tpBefore = w.TodayPane.isVisible;
          const PILLS = [["get-messages", "write-message"], ["reply", "reply-all", "forward-inline"], ["archive", "delete", "junk"], ["move-to"], ["mark-as"]];
          const R = e => e.getBoundingClientRect();
          const state = () => {
            const content = d.getElementById("unifiedToolbarContent"), row = R(content);
            const lis = [...content.children].filter(l => !l.hidden && l.getAttribute("item-id") != "spacer" && getComputedStyle(l).display != "none" && R(l).width > 0);
            const ids = l => l.getAttribute("item-id") || l.id;
            const all = [...content.children].filter(l => !l.hidden && !["spacer", "search-bar"].includes(l.getAttribute("item-id")) && l.id != "mcToolbarOverflow");
            const hidden = all.filter(l => l.hasAttribute("mc-squeezed")).map(ids);
            const shown = lis.map(ids);
            const overlap = [];
            for (let i = 1; i < lis.length; i++) if (R(lis[i]).left < R(lis[i - 1]).right - 1) overlap.push(ids(lis[i - 1]) + "/" + ids(lis[i]));
            const tog = d.getElementById("spacesPinnedButton"), tr = tog && R(tog).width ? R(tog) : null;
            const ov = d.getElementById("mcToolbarOverflow");
            const search = content.querySelector(':scope > li[item-id="search-bar"]');
            return { win: w.outerWidth, today: !!w.TodayPane.isVisible, hidden, shown,
                     partial: PILLS.filter(p => p.some(id => hidden.includes(id)) && p.some(id => shown.includes(id))).map(p => p.join("+")),
                     clipped: lis.filter(l => R(l).right > row.right + 1 || R(l).right > w.innerWidth).map(ids),
                     overToggle: tr ? lis.filter(l => R(l).left < tr.right - 1).map(ids) : [],
                     overlap, search: search ? Math.round(R(search).width) : null,
                     ov: !!ov && !ov.hasAttribute("mc-squeezed") && R(ov).width > 0 };
          };
          const sp = a3.paneLayout.folderPaneSplitter;
          let sideHidden = false;
          try {
            for (const side of [true, false]) {
              if (!side) {
                d.getElementById("spacesPinnedButton").click(); sideHidden = true;
                await bis(() => w.gSpacesToolbar.isHidden && sp.isCollapsed && !w.__mcSpacesAnimating && !a3.__mcAnimating, "Seitenleiste aus", 3000);
              }
              for (const today of [false, true]) {
                if (w.TodayPane.isVisible != today) { tpCmd.doCommand(); await ruhig(1500); }
                w.resizeTo(200, 800); await ruhig(1800);
                out[(side ? "" : "ohneLeiste-") + (today ? "today" : "plain")] = state();
              }
            }
            // Mail im eigenen Tab
            const hdr = a3.gDBView.hdrForFirstSelectedMessage;
            tm.openTab("mailMessageTab", { messageURI: hdr.folder.getUriForMsg(hdr), background: false });
            await bis(() => tm.currentTabInfo.mode.name == "mailMessageTab", "Mail-Tab offen", 4000); await ruhig(1500);
            w.resizeTo(200, 800); await ruhig(1500);
            out.tab = state();
            tm.closeTab(tm.currentTabInfo); await ruhig(800);
          } finally {
            if (sideHidden) { d.getElementById("spacesPinnedButton").click(); await ruhig(1200); }
            if (w.TodayPane.isVisible != tpBefore) { tpCmd.doCommand(); await ruhig(1000); }
            w.resizeTo(1500, 900); await ruhig(800);
          }
          return out;""")
        ok = bool(res) and all(not v["partial"] and not v["clipped"] and not v["overToggle"] and not v["overlap"]
                               and (v["search"] or 0) >= 38 and v["ov"] == bool(v["hidden"]) for v in res.values())
        return ok, f"{res}"
    check("Toolbar: Mail-Space auf Mindestbreite mit geöffneter Mail – Knopfleiste ohne abgeschnittene oder überlappende Knöpfe, Suche mindestens Lupe", toolbar_min_window, results)

    def capsules():
        res = m.js("""
          w.resizeTo(1280, 900); await wait(1300); await toMail();
          const GROUPS = [["get-messages","write-message"],["reply","reply-all","forward-inline"],["archive","delete","junk"],["move-to"],["mark-as"]];
          const bad = [];
          for (const g of GROUPS) {
            const vis = g.map(id => d.querySelector(`#unifiedToolbarContent > li[item-id="${id}"]`)).filter(li => li && li.getBoundingClientRect().width);
            if (!vis.length) continue;
            if (getComputedStyle(vis[0]).borderStartStartRadius != "999px") bad.push(vis[0].getAttribute("item-id") + " links eckig");
            if (getComputedStyle(vis.at(-1)).borderStartEndRadius != "999px") bad.push(vis.at(-1).getAttribute("item-id") + " rechts eckig");
          }
          w.resizeTo(1500, 900); await wait(800); return bad;""")
        return not res, ", ".join(res) or "alle Gruppen rund"
    check("Toolbar-Kapseln auch mit ausgeblendeten Knöpfen rund", capsules, results)

    def week_fits():
        res = m.js("""
          w.resizeTo(1280, 900); await wait(800); await toCalendar(); w.switchToView("week"); await ruhig(1200);
          const week = rect(d.getElementById("week-view")); const tab = rect(d.getElementById("tabmail"));
          const cols = d.querySelectorAll("#week-view .day-column-heading").length;
          w.resizeTo(1500, 900); await wait(600); return { week: week.r, tab: tab.r, cols };""")
        return res["week"] <= res["tab"] + 1 and res["cols"] == 7, f"Woche endet bei {res['week']}, Tab bei {res['tab']}, {res['cols']} Tage"
    check("Wochenansicht passt ins Fenster (alle 7 Tage)", week_fits, results)

    def quick_window():
        res = m.js("""
          await toCalendar();
          const li = [...d.querySelectorAll('#unifiedToolbarContent li[item-id="new-event"]')].find(l => l.getBoundingClientRect().width);
          li.querySelector("button").click(); await ruhig(900);
          const p = d.getElementById("mcQuickPanel"); const t = p.querySelector(".mc-qc-title");
          p.querySelector(".mc-qc-calsel").value = testCalendar().id; p.querySelector(".mc-qc-calsel").dispatchEvent(new w.Event("change"));
          t.value = "Halo Testtermin";
          t.dispatchEvent(new w.KeyboardEvent("keydown", { key: "Enter", isComposing: true, bubbles: true })); await wait(600);
          const afterIme = (await items("Halo Testtermin")).length;
          t.dispatchEvent(new w.KeyboardEvent("keydown", { key: "Enter", bubbles: true })); for (let i = 0; i < 40 && !(await items("Halo Testtermin")).length; i++) await wait(100); await ruhig(1200);
          await until(() => p.state == "closed", 3000);
          return { opened: true, afterIme, created: (await items("Halo Testtermin")).length, closed: p.state, visibility: d.visibilityState };""")
        # verdeckt pausiert macOS die Schließ-Animation – dann bleibt es bei „hiding“
        closed = res["closed"] == "closed" or (res["closed"] == "hiding" and res["visibility"] == "hidden")
        ok = res["afterIme"] == 0 and res["created"] == 1 and closed
        return ok, f"nach IME-Enter {res['afterIme']}, nach Enter {res['created']} Termin, Fenster {res['closed']} ({res['visibility']})"
    check("Schnellfenster: legt an, IME-Enter nicht", quick_window, results)

    def quick_radius():
        # Schnellfenster als Popover mit 20 px Radius (früher 16, die übrigen Panels 12)
        res = m.js("""
          await toCalendar();
          const li = [...d.querySelectorAll('#unifiedToolbarContent li[item-id="new-event"]')].find(l => l.getBoundingClientRect().width);
          li.querySelector("button").click();
          const p = await until(() => { const q = d.getElementById("mcQuickPanel"); return q?.state == "open" && q; }, 4000);
          if (!p) return { err: "nicht offen" };
          const r = { panel: w.getComputedStyle(p).getPropertyValue("--panel-border-radius").trim() };
          p.hidePopup(); await until(() => p.state == "closed", 3000); return r;""")
        return res.get("panel") == "20px", f"{res}"
    check("Schnellfenster: Popover mit 20 px Radius", quick_radius, results)

    def natural():
        res = m.js('''
          await toCalendar();
          const li = [...d.querySelectorAll('#unifiedToolbarContent li[item-id="new-event"]')].find(l => l.getBoundingClientRect().width);
          li.querySelector("button").click(); await ruhig(900);
          const p = d.getElementById("mcQuickPanel"); const t = p.querySelector(".mc-qc-title");
          p.querySelector(".mc-qc-calsel").value = testCalendar().id; p.querySelector(".mc-qc-calsel").dispatchEvent(new w.Event("change"));
          t.value = "Halo NL Essen morgen 12:30 für 90 min"; t.dispatchEvent(new w.Event("input", { bubbles: true })); await ruhig(300);
          p.querySelector(".mc-qc-primary").click(); for (let i = 0; i < 40 && !(await items("Halo NL Essen")).length; i++) await wait(100); await ruhig(1200);
          const it = (await items("Halo NL Essen"))[0];
          if (!it) return null;
          const s = cal.dtz.dateTimeToJsDate(it.startDate), e = cal.dtz.dateTimeToJsDate(it.endDate), tm2 = new Date(); tm2.setDate(tm2.getDate() + 1);
          // nur Tag und Dauer („morgen für 2h“): nicht ganztägig, 2 Stunden lang
          li.querySelector("button").click(); await ruhig(900);
          const t2 = p.querySelector(".mc-qc-title");
          p.querySelector(".mc-qc-calsel").value = testCalendar().id; p.querySelector(".mc-qc-calsel").dispatchEvent(new w.Event("change"));
          t2.value = "Halo NL Dauer morgen für 2h"; t2.dispatchEvent(new w.Event("input", { bubbles: true })); await ruhig(300);
          p.querySelector(".mc-qc-primary").click(); for (let i = 0; i < 40 && !(await items("Halo NL Dauer")).length; i++) await wait(100); await ruhig(1200);
          const it2 = (await items("Halo NL Dauer"))[0];
          const dur = it2 ? { allDay: it2.startDate.isDate, minutes: (cal.dtz.dateTimeToJsDate(it2.endDate) - cal.dtz.dateTimeToJsDate(it2.startDate)) / 60000,
                              tomorrow: cal.dtz.dateTimeToJsDate(it2.startDate).getDate() == tm2.getDate() } : null;
          return { tomorrow: s.getDate() == tm2.getDate(), start: s.getHours() * 60 + s.getMinutes(), minutes: (e - s) / 60000, dur };''')
        ok = (bool(res) and res["tomorrow"] and res["start"] == 750 and res["minutes"] == 90
              and bool(res["dur"]) and res["dur"]["allDay"] is False and res["dur"]["minutes"] == 120 and res["dur"]["tomorrow"])
        return ok, f"{res}"
    check("Schnellfenster: natürliche Eingabe („morgen 12:30 für 90 min“, „morgen für 2h“ nicht ganztägig)", natural, results)

    def quick_custom():
        # „Custom…“ bei Wiederholung und Erinnerung öffnet Thunderbirds Dialoge (hier nachgestellt: sie würden das Skript
        # blockieren); die Regel bzw. die Erinnerungen kommen im Termin an, der Text steht in der Auswahl; Abbrechen lässt die
        # vorige Auswahl stehen
        res = m.js('''
          const { CalRecurrenceInfo } = ChromeUtils.importESModule("resource:///modules/CalRecurrenceInfo.sys.mjs");
          const { CalAlarm } = ChromeUtils.importESModule("resource:///modules/CalAlarm.sys.mjs");
          // die Erinnerung (10 Minuten vorher) ist sofort fällig: Mitteilungen stumm abfangen, sonst ginge eine echte auf
          // (unter Linux/xvfb ohne Mitteilungsdienst stattdessen Thunderbirds Erinnerungsfenster)
          const { ExtensionParent } = ChromeUtils.importESModule("resource://gre/modules/ExtensionParent.sys.mjs");
          const AA = Cu.evalInSandbox("AlarmAlerts", ExtensionParent.GlobalManager.getExtension("mail-cards@sebastian.local").experimentAPIManager.global);
          AA.alerts = { showAlertWithCallbacks() {}, showAlert() {} };
          try {
          await toCalendar();
          const li = [...d.querySelectorAll('#unifiedToolbarContent li[item-id="new-event"]')].find(l => l.getBoundingClientRect().width);
          li.querySelector("button").click(); await ruhig(900);
          const p = d.getElementById("mcQuickPanel"), f = p.__mc;
          p.querySelector(".mc-qc-calsel").value = testCalendar().id; p.querySelector(".mc-qc-calsel").dispatchEvent(new w.Event("change"));
          f.title.value = "Halo Eigene Regel";
          const orig = w.openDialog, calls = []; let cancel = true;
          w.openDialog = (url, name, feat, args) => {
            calls.push(url.split("/").pop());
            if (cancel) return null;
            if (url.includes("recurrence")) {
              const info = new CalRecurrenceInfo(args.calendarEvent), r = cal.createRecurrenceRule();
              r.type = "WEEKLY"; r.interval = 2; info.appendRecurrenceItem(r); args.onOk(info);
            } else {
              const mk = v => { const a = new CalAlarm(); a.related = Ci.calIAlarm.ALARM_RELATED_START; const o = cal.createDuration(v); o.isNegative = true;
                                a.offset = o; a.action = "DISPLAY"; return a; };
              args.onOk([mk("PT10M"), mk("P1D")]);
            }
            return null;
          };
          const out = {};
          try {
            const pick = (sel, v) => { sel.value = v; sel.dispatchEvent(new w.Event("change", { bubbles: true })); };
            pick(f.repeat, "WEEKLY"); pick(f.repeat, "CUSTOM");
            out.cancelled = f.repeat.value;
            cancel = false;
            pick(f.repeat, "CUSTOM"); pick(f.alert, "CUSTOM");
            out.labels = [f.repeat.selectedOptions[0]?.textContent, f.alert.selectedOptions[0]?.textContent];
            out.summary = f.line2.textContent;
            p.querySelector(".mc-qc-primary").click(); for (let i = 0; i < 40 && !(await items("Halo Eigene Regel")).length; i++) await wait(100); await ruhig(1200);
          } finally { w.openDialog = orig; }
          out.calls = calls;
          const it = (await items("Halo Eigene Regel"))[0];
          const rule = it?.recurrenceInfo?.getRecurrenceItems()[0];
          out.item = it ? { type: rule?.type, interval: rule?.interval, alarms: it.getAlarms().length } : null;
          // neu geöffnet: wieder „Custom…“ ohne Regel
          li.querySelector("button").click(); await ruhig(900);
          out.reset = [f.repeat.value, f.repeat.querySelector('option[value="CUSTOM"]').textContent];
          p.hidePopup(); await ruhig(300);
          // Termin wieder weg, sonst gehen seine Erinnerungen mitten im Lauf auf. Vorher abwarten, bis halo.spaces die
          // schon fällige Erinnerung (1 Tag vorher) als erledigt gespeichert hat: Löschen davor lässt dieses Speichern
          // scheitern, Thunderbird hält den Testkalender dann für „Lesen fehlgeschlagen“ (später rot: Kalenderliste zeigt Status)
          for (const end = Date.now() + 5000; Date.now() < end && !(await items("Halo Eigene Regel"))[0]?.alarmLastAck; await takt(50));
          for (const x of await items("Halo Eigene Regel")) { try { await x.calendar.deleteItem(x); } catch {} }
          out.left = (await items("Halo Eigene Regel")).length;
          return out;
          } finally { AA.alerts = null; }''')
        it = res.get("item") or {}
        ok = (res.get("cancelled") == "WEEKLY" and it.get("type") == "WEEKLY" and it.get("interval") == 2 and it.get("alarms") == 2
              and res["labels"][1] == "2 alerts" and res["labels"][0] not in ("Custom…", "", None) and "\n" not in res["labels"][0] and "2" in res["labels"][0]
              and res.get("calls", [])[:3] == ["calendar-event-dialog-recurrence.xhtml"] * 2 + ["calendar-event-dialog-reminder.xhtml"]
              and res.get("reset") == ["", "Custom…"] and res.get("left") == 0)
        return ok, f"{res}"
    check("Schnellfenster: „Custom…“ bei Wiederholung und Erinnerung über Thunderbirds Dialoge, Regel und Erinnerungen kommen im Termin an", quick_custom, results)

    def natural_rules():
        # parseNatural direkt über das Experiment-Modul, „jetzt“ = Di 20.10.2026 15:00
        res = m.js('''
          const { ExtensionParent } = ChromeUtils.importESModule("resource://gre/modules/ExtensionParent.sys.mjs");
          const g = ExtensionParent.GlobalManager.getExtension("%s").experimentAPIManager.global;
          const parse = Cu.evalInSandbox("parseNatural", g);
          const p = n => String(n).padStart(2, "0");
          const f = x => x ? `${p(x.getDate())}.${p(x.getMonth() + 1)}.${x.getFullYear()} ${p(x.getHours())}:${p(x.getMinutes())}` : "-";
          const out = {};
          for (const t of ["Lunch für 2h um 12 Uhr", "Workshop für 1.5h morgen um 10 Uhr", "Meeting 14:00 für 2h", "Arzt Freitag morgen 8 Uhr",
                           "Arzt morgen 8 Uhr", "Termin 1.3.25", "Call 11-1pm", "Call 2-4pm", "Party 22-2 Uhr", "Arbeit 9-5",
                           "Schicht 18-7 Uhr", "Standup 11-12am", "Gottesdienst Karfreitag morgen 10 Uhr", "Party 11-1am", "Party 10-2am",
                           "Meeting morgen für 2h", "Lunch next Thursday", "Lunch Thursday", "Essen nächsten Freitag 19 Uhr"]) {
            const r = parse(t, new Date(2026, 9, 20, 15, 0));
            out[t] = `${r.title} | ${f(r.start)} – ${f(r.end)}` + (!r.end && !r.allDay ? ` | ohne Uhrzeit, ${r.duration} min` : "");
          }
          return out;''' % ADDON_ID)
        expected = {
            "Lunch für 2h um 12 Uhr": "Lunch | 20.10.2026 12:00 – 20.10.2026 14:00",
            "Workshop für 1.5h morgen um 10 Uhr": "Workshop | 21.10.2026 10:00 – 21.10.2026 11:30",
            "Meeting 14:00 für 2h": "Meeting | 20.10.2026 14:00 – 20.10.2026 16:00",
            "Arzt Freitag morgen 8 Uhr": "Arzt | 23.10.2026 08:00 – 23.10.2026 09:00",
            "Arzt morgen 8 Uhr": "Arzt | 21.10.2026 08:00 – 21.10.2026 09:00",
            "Termin 1.3.25": "Termin | 01.03.2025 00:00 – -",
            "Call 11-1pm": "Call | 20.10.2026 11:00 – 20.10.2026 13:00",
            "Call 2-4pm": "Call | 20.10.2026 14:00 – 20.10.2026 16:00",
            "Party 22-2 Uhr": "Party | 20.10.2026 22:00 – 21.10.2026 02:00",
            "Arbeit 9-5": "Arbeit | 20.10.2026 09:00 – 20.10.2026 17:00",
            "Schicht 18-7 Uhr": "Schicht | 20.10.2026 18:00 – 21.10.2026 07:00",
            "Standup 11-12am": "Standup | 20.10.2026 11:00 – 20.10.2026 12:00",
            "Gottesdienst Karfreitag morgen 10 Uhr": "Gottesdienst Karfreitag | 21.10.2026 10:00 – 21.10.2026 11:00",
            "Party 11-1am": "Party | 20.10.2026 23:00 – 21.10.2026 01:00",
            "Party 10-2am": "Party | 20.10.2026 22:00 – 21.10.2026 02:00",
            "Meeting morgen für 2h": "Meeting | 21.10.2026 00:00 – - | ohne Uhrzeit, 120 min",
            # „next“/„nächsten“ = Tag in der nächsten Kalenderwoche (wie macOS), ohne Zusatz das nächste Vorkommen;
            # von Di 20.10. aus gleich für Wochenbeginn Sonntag und Montag
            "Lunch next Thursday": "Lunch | 29.10.2026 00:00 – -",
            "Lunch Thursday": "Lunch | 22.10.2026 00:00 – -",
            "Essen nächsten Freitag 19 Uhr": "Essen | 30.10.2026 19:00 – 30.10.2026 20:00",
        }
        bad = [f"„{k}“ → {res.get(k)}" for k, v in expected.items() if res.get(k) != v]
        return not bad, "; ".join(bad) or f"{len(expected)} Eingaben richtig (Dauer, Dauer ohne Uhrzeit, „Freitag morgen“, „Karfreitag morgen“, Jahr „25“, am/pm, „12am“, „11-1am“, über Mitternacht, „next Thursday“)"
    check("Schnellfenster: Dauer, Wochentag mit „morgen“, zweistelliges Jahr, Zeiträume", natural_rules, results)

