    def quick_dst():
        # Ende der Sommerzeit (25.10.2026, in Europa doppelte Stunde 02:00–03:00): Dauer zählt als
        # echte Dauer wie in Apple Kalender; 02:00 zählt als zweite 02:00 (Winterzeit), wie der Kalender
        # sie speichert – „für 2h“ sind 02:00–04:00 und 120 echte Minuten, angezeigt wie angelegt. Festes
        # Datum, unabhängig vom Testzeitpunkt; ohne Zeitumstellung (CI: UTC) gilt dasselbe
        res = m.js('''
          const { ExtensionParent } = ChromeUtils.importESModule("resource://gre/modules/ExtensionParent.sys.mjs");
          const enh = Cu.evalInSandbox("enhancer", ExtensionParent.GlobalManager.getExtension("%s").experimentAPIManager.global);
          await toCalendar();
          enh.openQuickCreate(w, "event", null, { start: new Date(2026, 9, 25, 2, 0), allDay: false });
          const p = d.getElementById("mcQuickPanel"); const f = p.__mc;
          f.calendar.value = testCalendar().id; f.calendar.dispatchEvent(new w.Event("change"));
          const preset = [f.startTime.value, f.endDate.value, f.endTime.value].join(" ");
          f.title.value = "Halo Umstellung 25.10.2026 für 2h"; f.title.dispatchEvent(new w.Event("input", { bubbles: true }));
          const typed = [f.startDate.value, f.startTime.value, f.endDate.value, f.endTime.value].join(" ");
          f.add.click();
          let it = null;
          for (let i = 0; i < 40 && !it; i++) { it = (await items("Halo Umstellung"))[0]; if (!it) await wait(100); }
          await until(() => p.state == "closed", 3000);
          const tz = cal.dtz.defaultTimezone;
          const hm = dt => { const x = dt.getInTimezone(tz); return `${x.day}. ${x.hour}:${String(x.minute).padStart(2, "0")}`; };
          const out = { preset, typed, item: it ? `${hm(it.startDate)} – ${hm(it.endDate)}` : null, tz: tz.tzid,
                        minutes: it ? (it.endDate.nativeTime - it.startDate.nativeTime) / 60e6 : null,
                      };
          // Termin wieder entfernen – sonst stört er spätere Prüfungen im Oktober 2026
          if (it) try { await testCalendar().deleteItem(it); } catch {}
          return out;''' % ADDON_ID)
        ok = (res["preset"] == "02:00 2026-10-25 03:00" and res["typed"] == "2026-10-25 02:00 2026-10-25 04:00"
              and res["item"] == "25. 2:00 – 25. 4:00" and res["minutes"] == 120)
        return ok, f"{res}"
    check("Schnellfenster: Dauer über die Zeitumstellung (25.10.2026 02:00 „für 2h“ → 120 echte Minuten)", quick_dst, results)

    def quick_checks():
        # ganztägig mit Ende vor dem Beginn → ein Tag; Aufgabe mit Erinnerung bekommt eine Fälligkeit
        res = m.js('''
          const { ExtensionParent } = ChromeUtils.importESModule("resource://gre/modules/ExtensionParent.sys.mjs");
          const enh = Cu.evalInSandbox("enhancer", ExtensionParent.GlobalManager.getExtension("%s").experimentAPIManager.global);
          await toCalendar();
          const open = mode => {
            enh.openQuickCreate(w, mode);
            const p = d.getElementById("mcQuickPanel"); const f = p.__mc;
            f.calendar.value = testCalendar().id; f.calendar.dispatchEvent(new w.Event("change"));
            return [p, f];
          };
          const set = (input, v) => { if (typeof v == "boolean") input.checked = v; else input.value = v; input.dispatchEvent(new w.Event("change")); };
          const find = async t => { for (let i = 0; i < 40; i++) { const x = (await items(t))[0]; if (x) return x; await wait(100); } return null; };
          let [p, f] = open("event");
          f.title.value = "Halo Ganztag rückwärts"; f.title.dispatchEvent(new w.Event("input", { bubbles: true }));
          set(f.allDay, true); set(f.startDate, "2026-11-12"); set(f.endDate, "2026-11-10");
          f.add.click();
          const ev = await find("Halo Ganztag rückwärts");
          await until(() => p.state == "closed", 3000);
          [p, f] = open("task");
          f.title.value = "Halo Aufgabe Erinnerung"; f.title.dispatchEvent(new w.Event("input", { bubbles: true }));
          const before = f.hasDue.checked;
          set(f.alert, "PT15M"); const due = f.hasDue.checked;
          set(f.hasDue, false); const cleared = f.alert.value;
          set(f.alert, "PT15M");
          // Fälligkeit morgen: vorgegeben ist die nächste volle Stunde, zwischen :45 und :59 wäre die Erinnerung dann schon
          // fällig – halo.spaces zeigte eine echte Mitteilung und speicherte sie als erledigt, während die Prüfung die Aufgabe
          // gleich löscht; das gescheiterte Speichern ließ Thunderbird den Testkalender als „Lesen fehlgeschlagen“ führen
          // (CI mac hell 11.11. 03:46: „Kalenderliste zeigt Status bei Schreibschutz“ rot)
          const morgen = new Date(Date.now() + 864e5), zwei = n => String(n).padStart(2, "0");
          set(f.dueDate, `${morgen.getFullYear()}-${zwei(morgen.getMonth() + 1)}-${zwei(morgen.getDate())}`);
          f.add.click();
          const td = await find("Halo Aufgabe Erinnerung");
          await until(() => p.state == "closed", 3000);
          const out = { ev: ev ? [ev.startDate.icalString, ev.endDate.icalString] : null,
                        task: { before, due, cleared, hasDue: !!td?.dueDate, alarms: td ? td.getAlarms().length : null } };
          for (const it of [ev, td].filter(Boolean)) await testCalendar().deleteItem(it);
          return out;''' % ADDON_ID)
        ok = (res["ev"] == ["20261112", "20261113"] and res["task"] == {"before": False, "due": True, "cleared": "", "hasDue": True, "alarms": 1})
        return ok, f"{res}"
    check("Schnellfenster: ganztägiges Ende vor Beginn, Erinnerung bei Aufgabe", quick_checks, results)

    def quick_text_fields():
        # Schnellfenster: Datum und Uhrzeit wie im Termin-Dialog als Text zum Eintippen (keine Eingabefelder des Systems):
        # Klick ins Datum zeigt den Monatskalender, Klick auf einen Tag übernimmt ihn, das Ende rückt mit (gleiche Dauer);
        # Uhrzeit eintippen; danach überschreibt die natürliche Eingabe im Titel die Zeiten nicht mehr; ganztägig ohne Uhrzeit
        res = m.js(CAL_CHECK_JS + r'''
          const { ExtensionParent } = ChromeUtils.importESModule("resource://gre/modules/ExtensionParent.sys.mjs");
          const enh = Cu.evalInSandbox("enhancer", ExtensionParent.GlobalManager.getExtension("%s").experimentAPIManager.global);
          await toCalendar();
          enh.openQuickCreate(w, "event");
          const qp = await bis(() => { const q = d.getElementById("mcQuickPanel"); return q?.state == "open" && q; }, "Schnellfenster offen", 4000);
          const f = qp.__mc, out = {};
          try {
            // erst wenn der Titel den Fokus hat (kommt verzögert) – sonst schließt das den Monatskalender gleich wieder
            await bis(() => d.activeElement == f.title, "Titel im Fokus", 3000);
            f.summary.click(); await bis(() => vis(f.allDay), "Schnellfenster aufgeklappt", 3000);
            // feste Zeiten (ohne „change“ – sonst schöbe schon das Setzen das Ende mit)
            f.startDate.value = "2026-11-16"; f.startTime.value = "09:00"; f.endDate.value = "2026-11-16"; f.endTime.value = "10:00";
            qp.__mcSetLastStart(new Date(2026, 10, 16, 9, 0));
            const row = x => x.parentNode, sd = row(f.startDate).querySelector(".mc-date-edit"), st = row(f.startTime).querySelector(".mc-time-edit");
            const seg = (box, k) => box.querySelector(`[data-seg="${k}"]`);
            const down = el => el.dispatchEvent(new w.MouseEvent("mousedown", { bubbles: true, cancelable: true, button: 0 }));
            const press = (...keys) => { for (const k of keys) d.activeElement?.dispatchEvent(new w.KeyboardEvent("keydown", { key: k, bubbles: true, cancelable: true })); };
            out.shown = { inputs: [f.startDate, f.startTime].map(vis), date: sd?.textContent, time: st?.textContent };
            const mini = [...d.querySelectorAll(".mc-date-panel")].find(x => x.__mcFor == sd);
            down(seg(sd, "d")); await bis(() => mini?.state == "open", "Monatskalender offen", 3000); await ruhig(200);
            out.mini = { title: mini.querySelector(".mc-mini-title").textContent, sel: mini.querySelector(".mc-mini-day[selected]")?.dataset.date };
            [...mini.querySelectorAll(".mc-mini-day:not([othermonth])")].find(x => x.textContent == "18")
              ?.dispatchEvent(new w.MouseEvent("click", { bubbles: true, cancelable: true, button: 0 }));
            await bis(() => mini.state == "closed", "Monatskalender zu", 3000); await ruhig(200);
            out.day = [f.startDate.value, f.endDate.value, sd.textContent.includes("18"), qp.state];
            // Tasten je Format (Linux, en-US: 12 Stunden – Stunde, Minuten, dann a/p)
            const h12 = !!seg(st, "ap"), keys = (k24, k12) => (h12 ? k12 : k24);
            down(seg(st, "h")); press(...keys(["1", "4", "3", "0"], ["0", "2", "3", "0", "p"])); await ruhig(300);
            out.time = [f.startTime.value, f.endTime.value, st.textContent.includes("30"), f.line1.textContent.includes("30")];
            // Ende vor dem Beginn eingetippt (14:30 → „10“) → Folgetag; Beginn bleibt
            const et = row(f.endTime).querySelector(".mc-time-edit");
            down(seg(et, "h")); press(...keys(["1", "0"], ["1", "0", "ArrowRight", "a"])); await ruhig(300);
            out.endNext = [f.startDate.value, f.startTime.value, f.endDate.value, f.endTime.value];
            // natürliche Eingabe im Titel ändert die von Hand gesetzten Zeiten nicht mehr
            f.title.value = "Mittagessen morgen 12 Uhr"; f.title.dispatchEvent(new w.Event("input", { bubbles: true })); await ruhig(200);
            out.natural = [f.startDate.value, f.startTime.value];
            f.allDay.click(); await ruhig(300);
            out.allDay = [vis(st), vis(sd)];
          } finally { await shutPop(qp); }
          return out;''' % ADDON_ID)
        ok = (res.get("shown", {}).get("inputs") == [False, False] and "16" in (res["shown"].get("date") or "") and "9" in (res["shown"].get("time") or "")
              and (res.get("mini") or {}).get("sel") == "2026-10-16"
              and res.get("day") == ["2026-11-18", "2026-11-18", True, "open"]
              and res.get("time") == ["14:30", "15:30", True, True] and res.get("natural") == ["2026-11-18", "14:30"]
              and res.get("endNext") == ["2026-11-18", "14:30", "2026-11-19", "10:30"]
              and res.get("allDay") == [False, True])
        return ok, f"{res}"
    check("Schnellfenster: Datum und Uhrzeit zum Eintippen wie im Termin-Dialog, Monatskalender (Klick auf Tag übernimmt, Ende rückt mit), Ende vor dem Beginn auf den Folgetag, Tippen bleibt bei natürlicher Eingabe", quick_text_fields, results)

